{
  "name": "AccuData Parser",
  "description": "A professional accounting data parser that organizes raw text inputs into structured grids using a 3-panel layout."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface AccountEntry {
  id: string;
  code: string;
  description: string;
  category: string;
  bilanzPosten?: string;
  programmverbindung?: string;
  abschlusszweck?: string;
}

export enum ViewMode {
  GRID = 'GRID',
  SETTINGS = 'SETTINGS'
}

export enum PanelMode {
  DETAILS = 'DETAILS',
  IMPORT = 'IMPORT'
}

import React, { useState, useEffect, useCallback } from 'react';
import { AccountEntry, PanelMode } from './types';
import { 
  TableCellsIcon, 
  DocumentArrowUpIcon, 
  MagnifyingGlassIcon, 
  FunnelIcon,
  ArchiveBoxIcon,
  ChevronRightIcon
} from '@heroicons/react/24/outline';

// --- Helper Components ---

const Button: React.FC<{
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost';
  className?: string;
  fullWidth?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', fullWidth = false }) => {
  const baseStyle = "px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200 flex items-center justify-center gap-2";
  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-sm",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
  };

  return (
    <button 
      onClick={onClick} 
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

// --- Main Application ---

export default function App() {
  // State
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [rightPanelMode, setRightPanelMode] = useState<PanelMode>(PanelMode.IMPORT);
  const [rawInput, setRawInput] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState<string>("");

  // Derived State
  const selectedAccount = accounts.find(a => a.id === selectedId);
  const filteredAccounts = accounts.filter(acc => 
    acc.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    acc.code.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Parsing Logic
  const handleProcessData = useCallback(() => {
    if (!rawInput.trim()) return;

    const lines = rawInput.split('\n');
    const newEntries: AccountEntry[] = [];
    let currentCategory = "Genel";
    let lastHeader = "";

    lines.forEach((line) => {
      const trimmed = line.trim();
      if (!trimmed) return;

      // Regex to find Account Codes (e.g., 0005, 0100) or Ranges (KU 0600)
      // Looking for lines starting with 4 digits or "KU"
      const codeMatch = trimmed.match(/^(\d{4}|KU\s?[\d-]+|R\s?\d{4}[-]?\d{0,2})\s+(.*)/);

      if (codeMatch) {
        // It is an account line
        newEntries.push({
          id: crypto.randomUUID(),
          code: codeMatch[1],
          description: codeMatch[2],
          category: currentCategory,
          bilanzPosten: lastHeader
        });
      } else {
        // If it's not a code, it might be a category or header
        // Heuristic: If it's short, treat as Category, otherwise ignore or sub-header
        if (trimmed.length > 3 && !trimmed.includes(')')) {
          currentCategory = trimmed;
        }
        // Capture specific headers user mentioned
        if (trimmed.includes("Bilanz") || trimmed.includes("Posten")) {
            lastHeader = trimmed;
        }
      }
    });

    setAccounts(prev => [...prev, ...newEntries]);
    setRawInput(""); // Clear input
    setRightPanelMode(PanelMode.IMPORT); // Stay on import to show success or switch? Let's stay.

    // Auto select first if exists
    if (newEntries.length > 0) {
        setRightPanelMode(PanelMode.DETAILS);
        setSelectedId(newEntries[0].id);
    }
  }, [rawInput]);

  // --- Layout Render ---

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden">

      {/* 1. LEFT PANEL: Navigation (Fixed Width) */}
      <nav className="w-64 bg-slate-900 text-slate-300 flex flex-col border-r border-slate-800 flex-shrink-0">
        <div className="p-4 h-16 flex items-center border-b border-slate-800">
          <div className="flex items-center gap-2 text-white font-semibold text-lg">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <TableCellsIcon className="w-5 h-5" />
            </div>
            AccuParse
          </div>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-3 space-y-1">
            <p className="px-3 text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Veri Yönetimi</p>
            <button 
              onClick={() => setRightPanelMode(PanelMode.IMPORT)}
              className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${rightPanelMode === PanelMode.IMPORT ? 'bg-blue-600 text-white' : 'hover:bg-slate-800'}`}
            >
              <DocumentArrowUpIcon className="w-5 h-5" />
              <span>Veri Ekle / Import</span>
            </button>
            <button 
              onClick={() => setRightPanelMode(PanelMode.DETAILS)}
              className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${rightPanelMode === PanelMode.DETAILS ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}
            >
              <ArchiveBoxIcon className="w-5 h-5" />
              <span>Hesap Listesi</span>
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800 text-xs text-slate-500">
          v1.0.4 &copy; 2024
        </div>
      </nav>

      {/* 2. CENTER PANEL: Data Grid/List (Flexible Width) */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative border-r border-slate-200">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 flex-shrink-0">
          <h1 className="text-xl font-semibold text-slate-800">Hesap Planı</h1>
          <div className="flex items-center gap-2">
            <span className="text-sm text-slate-500 bg-slate-100 px-3 py-1 rounded-full">
              {accounts.length} Kayıt
            </span>
          </div>
        </header>

        {/* Toolbar */}
        <div className="p-4 bg-white border-b border-slate-200 flex items-center gap-4 flex-shrink-0">
          <div className="relative flex-1 max-w-md">
            <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input 
              type="text" 
              placeholder="Hesap kodu veya isim ara..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
            />
          </div>
          <Button variant="secondary">
            <FunnelIcon className="w-4 h-4" />
            Filtrele
          </Button>
        </div>

        {/* Data Grid */}
        <div className="flex-1 overflow-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-32">Kod</th>
                <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200">Açıklama (Posten)</th>
                <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 hidden md:table-cell">Kategori</th>
                <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-10"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 bg-white">
              {filteredAccounts.length === 0 ? (
                <tr>
                  <td colSpan={4} className="py-12 text-center text-slate-400">
                    Kayıt bulunamadı. Lütfen sağ panelden veri ekleyin.
                  </td>
                </tr>
              ) : (
                filteredAccounts.map((account) => (
                  <tr 
                    key={account.id} 
                    onClick={() => {
                      setSelectedId(account.id);
                      setRightPanelMode(PanelMode.DETAILS);
                    }}
                    className={`cursor-pointer transition-colors group ${selectedId === account.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
                  >
                    <td className="py-3 px-4 text-sm font-medium text-slate-900 whitespace-nowrap">{account.code}</td>
                    <td className="py-3 px-4 text-sm text-slate-600 truncate max-w-xs">{account.description}</td>
                    <td className="py-3 px-4 text-xs text-slate-500 hidden md:table-cell">
                        <span className="bg-slate-100 px-2 py-1 rounded text-slate-600 border border-slate-200">
                            {account.category}
                        </span>
                    </td>
                    <td className="py-3 px-4 text-slate-400 text-right">
                      <ChevronRightIcon className={`w-4 h-4 inline-block ${selectedId === account.id ? 'text-blue-500' : 'opacity-0 group-hover:opacity-100'}`} />
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </main>

      {/* 3. RIGHT PANEL: Details & Form (Fixed Width) */}
      <aside className="w-96 bg-white flex flex-col border-l border-slate-200 shadow-xl flex-shrink-0 z-20">

        {/* Panel Header */}
        <div className="h-16 border-b border-slate-200 flex items-center justify-between px-6 bg-slate-50">
          <h2 className="font-semibold text-slate-800">
            {rightPanelMode === PanelMode.IMPORT ? 'Veri İçe Aktar' : 'Hesap Detayı'}
          </h2>
          <div className="flex bg-slate-200 rounded-lg p-0.5">
             <button 
                onClick={() => setRightPanelMode(PanelMode.IMPORT)}
                className={`p-1.5 rounded-md transition-all ${rightPanelMode === PanelMode.IMPORT ? 'bg-white shadow text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
                title="İçe Aktar"
             >
                <DocumentArrowUpIcon className="w-4 h-4" />
             </button>
             <button 
                onClick={() => setRightPanelMode(PanelMode.DETAILS)}
                className={`p-1.5 rounded-md transition-all ${rightPanelMode === PanelMode.DETAILS ? 'bg-white shadow text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
                title="Detaylar"
                disabled={!selectedId}
             >
                <ArchiveBoxIcon className="w-4 h-4" />
             </button>
          </div>
        </div>

        {/* Panel Content */}
        <div className="flex-1 overflow-y-auto p-6">

          {rightPanelMode === PanelMode.IMPORT && (
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">Metin Yapıştırma Alanı</label>
                <p className="text-xs text-slate-500 mb-3">
                  Aşağıdaki alana kopyaladığınız metni yapıştırın. Sistem satırları analiz edip otomatik olarak listeye ekleyecektir.
                </p>
                <div className="relative">
                  <textarea 
                    value={rawInput}
                    onChange={(e) => setRawInput(e.target.value)}
                    className="w-full h-80 p-3 text-xs font-mono border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 resize-none bg-slate-50"
                    placeholder={`"Posten2)\nProgrammverbindung4)\n0005 Rückständige Fällige..."`}
                  ></textarea>
                </div>
              </div>

              <div className="bg-blue-50 border border-blue-100 rounded-md p-3 text-xs text-blue-800">
                <p className="font-semibold mb-1">Format İpucu:</p>
                <ul className="list-disc pl-4 space-y-1 opacity-80">
                   <li>4 haneli kodlar (0005, 0100) otomatik algılanır.</li>
                   <li>KU, R gibi ön ekler desteklenir.</li>
                   <li>Başlık satırları kategori olarak atanır.</li>
                </ul>
              </div>

              <div className="pt-4 border-t border-slate-100">
                <Button fullWidth onClick={handleProcessData} disabled={!rawInput.trim()}>
                  Analiz Et ve Ekle
                </Button>
              </div>
            </div>
          )}

          {rightPanelMode === PanelMode.DETAILS && (
            selectedAccount ? (
              <div className="space-y-6">
                <div className="flex items-start justify-between">
                  <div className="bg-blue-100 text-blue-800 px-3 py-1 rounded text-lg font-bold font-mono">
                    {selectedAccount.code}
                  </div>
                  <span className="text-xs font-medium text-slate-400 border border-slate-200 rounded px-2 py-1 uppercase">
                    Aktif Hesap
                  </span>
                </div>

                <div>
                  <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider block mb-1">
                    Hesap Adı
                  </label>
                  <p className="text-slate-800 text-lg leading-snug font-medium">
                    {selectedAccount.description}
                  </p>
                </div>

                <div className="grid grid-cols-1 gap-4 bg-slate-50 p-4 rounded-lg border border-slate-100">
                  <div>
                    <label className="text-xs text-slate-500 block">Kategori / Üst Grup</label>
                    <p className="text-sm font-medium text-slate-700">{selectedAccount.category}</p>
                  </div>
                  {selectedAccount.bilanzPosten && (
                    <div>
                        <label className="text-xs text-slate-500 block">Bilanz Posten</label>
                        <p className="text-sm font-medium text-slate-700">{selectedAccount.bilanzPosten}</p>
                    </div>
                  )}
                </div>

                {/* Simulated Form Fields for Editing - As per request to show forms */}
                <div className="space-y-4 pt-4 border-t border-slate-200">
                    <h3 className="text-sm font-semibold text-slate-900">Düzenle</h3>

                    <div>
                        <label className="block text-xs font-medium text-slate-700 mb-1">Programmverbindung</label>
                        <input type="text" className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500" placeholder="-" />
                    </div>

                    <div>
                        <label className="block text-xs font-medium text-slate-700 mb-1">Abschlusszweck</label>
                        <select className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500 bg-white">
                            <option>Seçiniz</option>
                            <option>Bilanz</option>
                            <option>GuV</option>
                        </select>
                    </div>

                    <div className="flex gap-2 pt-2">
                         <Button fullWidth variant="primary">Kaydet</Button>
                         <Button variant="secondary">İptal</Button>
                    </div>
                </div>

              </div>
            ) : (
               <div className="flex flex-col items-center justify-center h-full text-center text-slate-400 space-y-4">
                  <ArchiveBoxIcon className="w-16 h-16 opacity-20" />
                  <p className="text-sm">Listeden bir hesap seçin veya<br/>yeni veri ekleyin.</p>
                  <Button variant="secondary" onClick={() => setRightPanelMode(PanelMode.IMPORT)}>
                    Veri Ekle
                  </Button>
               </div>
            )
          )}
        </div>
      </aside>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { AccountEntry, PanelMode } from './types';
import { 
  TableCellsIcon, 
  DocumentArrowUpIcon, 
  MagnifyingGlassIcon, 
  FunnelIcon,
  ArchiveBoxIcon,
  ChevronRightIcon,
  TrashIcon,
  TagIcon,
  FolderIcon,
  PencilSquareIcon,
  IdentificationIcon
} from '@heroicons/react/24/outline';

// --- Helper Components ---

const Button: React.FC<{
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger-ghost';
  className?: string;
  fullWidth?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', fullWidth = false }) => {
  const baseStyle = "px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200 flex items-center justify-center gap-2";
  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-sm",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
    "danger-ghost": "text-red-600 hover:bg-red-50 hover:text-red-700"
  };

  return (
    <button 
      onClick={onClick} 
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

// --- Main Application ---

export default function App() {
  // State
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [rightPanelMode, setRightPanelMode] = useState<PanelMode>(PanelMode.IMPORT);
  const [rawInput, setRawInput] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState<string>("");

  // Derived State
  const selectedAccount = accounts.find(a => a.id === selectedId);
  const filteredAccounts = accounts.filter(acc => 
    acc.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    acc.code.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Parsing Logic
  const handleProcessData = useCallback(() => {
    if (!rawInput.trim()) return;

    const lines = rawInput.split('\n');
    const newEntries: AccountEntry[] = [];
    let currentCategory = "Genel";
    let lastHeader = "";

    lines.forEach((line) => {
      const trimmed = line.trim();
      if (!trimmed) return;

      // Regex to find Account Codes (e.g., 0005, 0100) or Ranges (KU 0600)
      // Looking for lines starting with 4 digits or "KU"
      const codeMatch = trimmed.match(/^(\d{4}|KU\s?[\d-]+|R\s?\d{4}[-]?\d{0,2})\s+(.*)/);

      if (codeMatch) {
        // It is an account line
        newEntries.push({
          id: crypto.randomUUID(),
          code: codeMatch[1],
          description: codeMatch[2],
          category: currentCategory,
          bilanzPosten: lastHeader
        });
      } else {
        // If it's not a code, it might be a category or header
        // Heuristic: If it's short, treat as Category, otherwise ignore or sub-header
        if (trimmed.length > 3 && !trimmed.includes(')')) {
          currentCategory = trimmed;
        }
        // Capture specific headers user mentioned
        if (trimmed.includes("Bilanz") || trimmed.includes("Posten")) {
            lastHeader = trimmed;
        }
      }
    });

    setAccounts(prev => [...prev, ...newEntries]);
    setRawInput(""); // Clear input
    setRightPanelMode(PanelMode.IMPORT); // Stay on import to show success or switch? Let's stay.

    // Auto select first if exists
    if (newEntries.length > 0) {
        setRightPanelMode(PanelMode.DETAILS);
        setSelectedId(newEntries[0].id);
    }
  }, [rawInput]);

  const handleClearData = () => {
    if (accounts.length > 0 && window.confirm("Tüm hesap listesini silmek istediğinize emin misiniz?")) {
      setAccounts([]);
      setSelectedId(null);
      setRightPanelMode(PanelMode.IMPORT);
    }
  };

  // --- Layout Render ---

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden">

      {/* 1. LEFT PANEL: Navigation (Fixed Width) */}
      <nav className="w-64 bg-slate-900 text-slate-300 flex flex-col border-r border-slate-800 flex-shrink-0">
        <div className="p-4 h-16 flex items-center border-b border-slate-800">
          <div className="flex items-center gap-2 text-white font-semibold text-lg">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <TableCellsIcon className="w-5 h-5" />
            </div>
            AccuParse
          </div>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-3 space-y-1">
            <p className="px-3 text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Veri Yönetimi</p>
            <button 
              onClick={() => setRightPanelMode(PanelMode.IMPORT)}
              className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${rightPanelMode === PanelMode.IMPORT ? 'bg-blue-600 text-white' : 'hover:bg-slate-800'}`}
            >
              <DocumentArrowUpIcon className="w-5 h-5" />
              <span>Veri Ekle / Import</span>
            </button>
            <button 
              onClick={() => setRightPanelMode(PanelMode.DETAILS)}
              className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${rightPanelMode === PanelMode.DETAILS ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}
            >
              <ArchiveBoxIcon className="w-5 h-5" />
              <span>Hesap Listesi</span>
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800 text-xs text-slate-500">
          v1.0.5 &copy; 2024
        </div>
      </nav>

      {/* 2. CENTER PANEL: Data Grid/List (Flexible Width) */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative border-r border-slate-200">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 flex-shrink-0">
          <h1 className="text-xl font-semibold text-slate-800">Hesap Planı</h1>
          <div className="flex items-center gap-2">
            <span className="text-sm text-slate-500 bg-slate-100 px-3 py-1 rounded-full">
              {accounts.length} Kayıt
            </span>
          </div>
        </header>

        {/* Toolbar */}
        <div className="p-4 bg-white border-b border-slate-200 flex items-center gap-4 flex-shrink-0">
          <div className="relative flex-1 max-w-md">
            <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input 
              type="text" 
              placeholder="Hesap kodu veya isim ara..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
            />
          </div>
          <Button variant="secondary">
            <FunnelIcon className="w-4 h-4" />
            Filtrele
          </Button>
          <Button variant="danger-ghost" onClick={handleClearData}>
            <TrashIcon className="w-5 h-5" />
            Temizle
          </Button>
        </div>

        {/* Data Grid */}
        <div className="flex-1 overflow-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-32">Kod</th>
                <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200">Açıklama (Posten)</th>
                <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 hidden md:table-cell">Kategori</th>
