import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from './supabaseClient';
import { AccountEntry, ViewMode } from './types';
import { 
  TableCellsIcon, 
  DocumentArrowUpIcon, 
  MagnifyingGlassIcon, 
  FunnelIcon,
  ArchiveBoxIcon,
  ChevronRightIcon,
  TagIcon,
  FolderIcon,
  PencilSquareIcon,
  IdentificationIcon,
  InformationCircleIcon,
  ArrowPathIcon,
  BookOpenIcon,
  AcademicCapIcon
} from '@heroicons/react/24/outline';

// --- Helper Components ---

const Button: React.FC<{
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger-ghost';
  className?: string;
  fullWidth?: boolean;
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', fullWidth = false, disabled = false }) => {
  const baseStyle = "px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-sm",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
    "danger-ghost": "text-red-600 hover:bg-red-50 hover:text-red-700"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

// --- Main Application ---

export default function App() {
  // State
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<ViewMode>('IMPORT');
  const [rawInput, setRawInput] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState<string>("");

  // Edit Form State
  const [editForm, setEditForm] = useState({
    programmverbindung: '',
    abschlusszweck: ''
  });

  // --- Supabase Integration ---

  // 1. Fetch Initial Data
  const fetchAccounts = async () => {
    try {
      const { data, error } = await supabase
        .from('accounts')
        .select('*')
        .order('code', { ascending: true });

      if (error) throw error;

      // Map DB snake_case to TS camelCase
      const mappedData: AccountEntry[] = (data || []).map(item => ({
        id: item.id,
        code: item.code,
        description: item.description,
        category: item.category,
        bilanzPosten: item.bilanz_posten,
        programmverbindung: item.programmverbindung,
        abschlusszweck: item.abschlusszweck
      }));

      setAccounts(mappedData);
    } catch (error) {
      console.error('Error fetching accounts:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAccounts();

    // 2. Realtime Subscription
    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: '*', // Listen to INSERT, UPDATE, DELETE
          schema: 'public',
          table: 'accounts',
        },
        (payload) => {
          // For simplicity and data consistency, we re-fetch sorted list. 
          // Optimization: Could manipulate state directly based on payload.eventType
          fetchAccounts();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // Sync Edit Form when selection changes
  useEffect(() => {
    if (selectedId) {
        const account = accounts.find(a => a.id === selectedId);
        if (account) {
            setEditForm({
                programmverbindung: account.programmverbindung || '',
                abschlusszweck: account.abschlusszweck || 'Seçiniz'
            });
        }
    }
  }, [selectedId, accounts]);


  // Derived State
  const selectedAccount = accounts.find(a => a.id === selectedId);
  const filteredAccounts = accounts.filter(acc => 
    acc.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    acc.code.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Parsing & Inserting Logic
  const handleProcessData = useCallback(async () => {
    if (!rawInput.trim()) return;
    setLoading(true);

    const lines = rawInput.split('\n');
    const newEntries = [];
    let currentCategory = "Genel";
    let lastHeader = "";

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;

      const codeMatch = trimmed.match(/^(\d{4}|KU\s?[\d-]+|R\s?\d{4}[-]?\d{0,2})\s+(.*)/);

      if (codeMatch) {
        newEntries.push({
          code: codeMatch[1],
          description: codeMatch[2],
          category: currentCategory,
          bilanz_posten: lastHeader // DB column name
        });
      } else {
        if (trimmed.length > 3 && !trimmed.includes(')')) {
          currentCategory = trimmed;
        }
        if (trimmed.includes("Bilanz") || trimmed.includes("Posten")) {
            lastHeader = trimmed;
        }
      }
    }

    if (newEntries.length > 0) {
        const { error } = await supabase.from('accounts').insert(newEntries);

        if (error) {
            alert("Veri yüklenirken hata oluştu: " + error.message);
        } else {
            setRawInput(""); 
            setActiveTab('DATABASE');
        }
    }
    setLoading(false);
  }, [rawInput]);

  // Update Logic
  const handleUpdate = async () => {
    if (!selectedId) return;

    const { error } = await supabase
        .from('accounts')
        .update({
            programmverbindung: editForm.programmverbindung,
            abschlusszweck: editForm.abschlusszweck === 'Seçiniz' ? null : editForm.abschlusszweck
        })
        .eq('id', selectedId);

    if (error) {
        alert("Güncelleme hatası: " + error.message);
    } else {
        // Optimistic UI update handled by realtime subscription usually, 
        // but for immediate feedback:
        // alert("Kayıt güncellendi.");
    }
  };

  // --- Layout Render ---

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden">

      {/* 1. LEFT PANEL: Navigation (Fixed Width) */}
      <nav className="w-64 bg-slate-900 text-slate-300 flex flex-col border-r border-slate-800 flex-shrink-0">
        <div className="p-4 h-16 flex items-center border-b border-slate-800">
          <div className="flex items-center gap-2 text-white font-semibold text-lg">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <TableCellsIcon className="w-5 h-5" />
            </div>
            AccuParse
          </div>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-3 space-y-1">
            <p className="px-3 text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Veri Yönetimi</p>
            <button 
              onClick={() => setActiveTab('IMPORT')}
              className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white' : 'hover:bg-slate-800'}`}
            >
              <DocumentArrowUpIcon className="w-5 h-5" />
              <span>Veri Ekle / Import</span>
            </button>
            <button 
              onClick={() => setActiveTab('DATABASE')}
              className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'DATABASE' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}
            >
              <ArchiveBoxIcon className="w-5 h-5" />
              <span>Bilgi Bankası</span>
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800 text-xs text-slate-500 flex justify-between items-center">
          <span>v1.2.0 (Cloud)</span>
          <div className={`w-2 h-2 rounded-full ${loading ? 'bg-yellow-500 animate-pulse' : 'bg-green-500'}`} title="Bağlantı Durumu"></div>
        </div>
      </nav>

      {/* 2. CENTER PANEL: Main Content Area (Flexible Width) */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative border-r border-slate-200">

        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 flex-shrink-0">
          <h1 className="text-xl font-semibold text-slate-800">
            {activeTab === 'IMPORT' ? 'Veri İçe Aktar' : 'Bilgi Bankası'}
          </h1>
          <div className="flex items-center gap-2">
            {activeTab === 'DATABASE' && (
              <span className="text-sm text-slate-500 bg-slate-100 px-3 py-1 rounded-full flex items-center gap-2">
                {loading && <ArrowPathIcon className="w-3 h-3 animate-spin" />}
                {accounts.length} Kayıt
              </span>
            )}
          </div>
        </header>

        {/* --- VIEW: DATABASE --- */}
        {activeTab === 'DATABASE' && (
