import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from './supabaseClient';
import { AccountEntry, ViewMode } from './types';
import { 
  TableCellsIcon, 
  DocumentArrowUpIcon, 
  MagnifyingGlassIcon, 
  FunnelIcon,
  ArchiveBoxIcon,
  ChevronRightIcon,
  TagIcon,
  FolderIcon,
  PencilSquareIcon,
  IdentificationIcon,
  InformationCircleIcon,
  ArrowPathIcon,
  BookOpenIcon,
  AcademicCapIcon,
  LightBulbIcon
} from '@heroicons/react/24/outline';

// --- Helper Components ---

const Button: React.FC<{
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger-ghost';
  className?: string;
  fullWidth?: boolean;
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', fullWidth = false, disabled = false }) => {
  const baseStyle = "px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-sm",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
    "danger-ghost": "text-red-600 hover:bg-red-50 hover:text-red-700"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

// --- Logic Helpers ---

const getAccountingInsight = (code: string): string => {
  // Extract the first meaningful digit to determine the account class (SKR03/04 logic approximation)
  const numericMatch = code.match(/\d+/);
  if (!numericMatch) return "Bu kayıt, bir hesap aralığı veya özel bir raporlama grubunu temsil eder. Mali tablolarda gruplama amacıyla kullanılır.";

  const numStr = numericMatch[0];
  const firstDigit = numStr[0];
  const num = parseInt(numStr);

  // Detailed logic based on Account Class
  if (firstDigit === '0') {
    return "Bu hesap, 'Duran Varlıklar' sınıfında yer alır. İşletmenin faaliyetlerini sürdürebilmesi için edindiği, bir yıldan uzun süre kullanılacak varlıkları (lisanslar, haklar, demirbaşlar, binalar) ifade eder. Genellikle amortismana tabidir ve bilançonun aktif tarafında uzun vadeli varlık olarak raporlanır.";
  }
  if (firstDigit === '1') {
    return "Bu hesap, 'Dönen Varlıklar' ve 'Finansal Hesaplar' sınıfındadır. İşletmenin nakit varlıklarını, banka hesaplarını, çeklerini ve kısa vadeli alacaklarını takip eder. Likiditesi en yüksek gruptur ve günlük nakit akışı yönetimi için kritiktir.";
  }
  if (firstDigit === '2') {
    return "Genellikle 'Özkaynaklar' veya 'Ara Hesaplar' grubunu temsil eder. İşletme sermayesi, yedek akçeler veya dönem ayırıcı hesaplar bu grupta izlenir. Pasif karakterlidir.";
  }
  if (firstDigit === '3') {
    return "Bu hesap, 'Yabancı Kaynaklar' (Borçlar) sınıfına dahildir. Mal ve hizmet alımlarından kaynaklanan ticari borçlar, krediler ve diğer kısa/uzun vadeli yükümlülükleri kapsar. Muhasebeciler için ödeme planlamasında önemlidir.";
  }
  if (firstDigit === '4') {
    return "Bu hesap bir 'Gelir' kalemidir. İşletmenin ana faaliyet konusundan (mal veya hizmet satışı) elde ettiği hasılatı gösterir. Gelir tablosunun temelini oluşturur ve kârlılık analizinde doğrudan kullanılır.";
  }
  if (firstDigit === '5' || firstDigit === '6') {
    return "Bu hesap bir 'Gider' kalemidir. Malzeme maliyetleri, personel ücretleri, kira ve enerji gibi işletme giderlerini kapsar. Dönem kârını azaltıcı etkisi vardır ve maliyet muhasebesinin konusudur.";
  }
  if (firstDigit === '7') {
    return "Yansıtma ve üretim maliyet hesaplarıdır. Özellikle üretim işletmelerinde maliyetlerin biriktirilip ilgili gider yerlerine dağıtılması amacıyla kullanılır.";
  }
  if (firstDigit === '8') {
    return "Finansman gelir/giderleri veya olağandışı kalemlerdir. Faiz gelirleri, kur farkları veya vergi karşılıkları bu grupta incelenir.";
  }
  if (firstDigit === '9') {
    return "Nazım Hesaplar (Bilgi Hesapları). İşletme varlıklarını doğrudan etkilemeyen ancak takip edilmesi gereken (teminat mektupları, kefaletler vb.) durumları kaydetmek için kullanılır. Bilanço toplamına dahil edilmez.";
  }

  return "Genel muhasebe hesabı. Standart mali tablo raporlamasında kullanılır.";
};

// --- Main Application ---

export default function App() {
  // State
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<ViewMode>('IMPORT');
  const [rawInput, setRawInput] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState<string>("");

  // Edit Form State
  const [editForm, setEditForm] = useState({
    programmverbindung: '',
    abschlusszweck: ''
  });

  // --- Supabase Integration ---

  // 1. Fetch Initial Data
  const fetchAccounts = async () => {
    try {
      const { data, error } = await supabase
        .from('accounts')
        .select('*')
        .order('code', { ascending: true });

      if (error) throw error;

      // Map DB snake_case to TS camelCase
      const mappedData: AccountEntry[] = (data || []).map(item => ({
        id: item.id,
        code: item.code,
        description: item.description,
        category: item.category,
        bilanzPosten: item.bilanz_posten,
        programmverbindung: item.programmverbindung,
        abschlusszweck: item.abschlusszweck
      }));

      setAccounts(mappedData);
    } catch (error) {
      console.error('Error fetching accounts:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAccounts();

    // 2. Realtime Subscription
    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: '*', // Listen to INSERT, UPDATE, DELETE
          schema: 'public',
          table: 'accounts',
        },
        (payload) => {
          // For simplicity and data consistency, we re-fetch sorted list. 
          // Optimization: Could manipulate state directly based on payload.eventType
          fetchAccounts();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // Sync Edit Form when selection changes
  useEffect(() => {
    if (selectedId) {
        const account = accounts.find(a => a.id === selectedId);
        if (account) {
            setEditForm({
                programmverbindung: account.programmverbindung || '',
                abschlusszweck: account.abschlusszweck || 'Seçiniz'
            });
        }
    }
  }, [selectedId, accounts]);


  // Derived State
  const selectedAccount = accounts.find(a => a.id === selectedId);
  const filteredAccounts = accounts.filter(acc => 
    acc.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    acc.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (acc.bilanzPosten && acc.bilanzPosten.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  // Parsing & Inserting Logic
  const handleProcessData = useCallback(async () => {
    if (!rawInput.trim()) return;
    setLoading(true);

    const lines = rawInput.split('\n');
    const newEntries = [];

    // State machine variables for parsing
    let currentClass = "Genel";
    let currentBilanzPosten = "";
    let buffer: string[] = [];
    let expectingClassName = false;
    let pendingClassDigit = "";

    // Regex patterns to ignore
    const ignorePatterns = [
        /^Bilanz-?$/i,
        /^Posten\d*\)?$/i,
        /^Programmverbindung\d*\)?$/i,
        /^Abschlusszweck\d*\)?$/i,
        /^\d+\)$/,
        /^Bilanz-$/
    ];

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;

      // 1. Skip ignored headers
      if (ignorePatterns.some(p => p.test(trimmed))) continue;

      // 2. Check for Class Header Start (single digit 0-9)
      if (/^\d$/.test(trimmed)) {
          pendingClassDigit = trimmed;
          expectingClassName = true;
          buffer = []; // Clear buffer to avoid carrying over previous text
          continue;
      }

      // 3. Check if we are waiting for the class name (line after digit)
      if (expectingClassName) {
          currentClass = `${pendingClassDigit} ${trimmed}`;
          expectingClassName = false;
          buffer = []; 
          currentBilanzPosten = ""; // Reset Bilanz Posten for new class
          continue;
      }

      // 4. Check for Code (4 digits or KU/R prefix)
      const codeMatch = trimmed.match(/^(\d{4}|KU\s?[\d-]+|R\s?\d{4}[-]?\d{0,2})\s+(.*)/);

      if (codeMatch) {
        // It is a code line.
        // If we have accumulated text in buffer, it is the new Bilanz Posten header.
        if (buffer.length > 0) {
            currentBilanzPosten = buffer.join(" ");
            buffer = [];
        }

        newEntries.push({
          code: codeMatch[1],
          description: codeMatch[2],
          category: currentClass,
          bilanz_posten: currentBilanzPosten // DB column name
        });
      } else {
        // It is a text line (potential Bilanz Posten header part)
        // Store in buffer to be used by the next code(s)
        if (trimmed.length > 1) { 
          buffer.push(trimmed);
        }
      }
    }

    if (newEntries.length > 0) {
        // --- DEDUPLICATION LOGIC ---

        // 1. Remove duplicates within the batch itself (based on code)
        const uniqueCodesInBatch = new Set();
        const deduplicatedEntries = [];
        for (const entry of newEntries) {
            if (!uniqueCodesInBatch.has(entry.code)) {
                uniqueCodesInBatch.add(entry.code);
                deduplicatedEntries.push(entry);
            }
        }

        // 2. Check existing codes in database
        const codesToCheck = deduplicatedEntries.map(e => e.code);

        try {
            const { data: existingData, error: checkError } = await supabase
                .from('accounts')
                .select('code')
                .in('code', codesToCheck);

            if (checkError) throw checkError;

            // 3. Filter out entries that already exist in DB
            const existingSet = new Set(existingData?.map(d => d.code));
            const finalEntriesToInsert = deduplicatedEntries.filter(e => !existingSet.has(e.code));

            if (finalEntriesToInsert.length > 0) {
                const { error: insertError } = await supabase.from('accounts').insert(finalEntriesToInsert);

                if (insertError) {
                    alert("Kayıt sırasında hata oluştu: " + insertError.message);
                } else {
                    const skippedCount = deduplicatedEntries.length - finalEntriesToInsert.length;
                    let message = `${finalEntriesToInsert.length} yeni kayıt başarıyla eklendi.`;
                    if (skippedCount > 0) {
                        message += `\n${skippedCount} adet mükerrer kayıt (zaten mevcut olduğu için) atlandı.`;
                    }
                    alert(message);
                    setRawInput(""); 
                    setActiveTab('DATABASE');
                }
            } else {
                alert("Eklenecek yeni kayıt bulunamadı. Girdiğiniz tüm kodlar veritabanında zaten mevcut.");
            }

        } catch (error: any) {
            alert("Veritabanı kontrolü sırasında hata: " + error.message);
        }
    }
    setLoading(false);
  }, [rawInput]);

  // Update Logic
  const handleUpdate = async () => {
    if (!selectedId) return;

    const { error } = await supabase
        .from('accounts')
        .update({
            programmverbindung: editForm.programmverbindung,
            abschlusszweck: editForm.abschlusszweck === 'Seçiniz' ? null : editForm.abschlusszweck
        })
        .eq('id', selectedId);

    if (error) {
        alert("Güncelleme hatası: " + error.message);
    } else {
        // Optimistic UI update handled by realtime subscription usually
    }
  };

  // --- Layout Render ---

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden">

      {/* 1. LEFT PANEL: Navigation (Fixed Width) */}
      <nav className="w-64 bg-slate-900 text-slate-300 flex flex-col border-r border-slate-800 flex-shrink-0">
        <div className="p-4 h-16 flex items-center border-b border-slate-800">
          <div className="flex items-center gap-2 text-white font-semibold text-lg">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <TableCellsIcon className="w-5 h-5" />
            </div>
            AccuParse
          </div>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-3 space-y-1">
            <p className="px-3 text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Veri Yönetimi</p>
            <button 
              onClick={() => setActiveTab('IMPORT')}
              className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white' : 'hover:bg-slate-800'}`}
            >
              <DocumentArrowUpIcon className="w-5 h-5" />
              <span>Veri Ekle / Import</span>
            </button>
            <button 
              onClick={() => setActiveTab('DATABASE')}
              className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'DATABASE' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}
            >
              <ArchiveBoxIcon className="w-5 h-5" />
              <span>Bilgi Bankası</span>
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800 text-xs text-slate-500 flex justify-between items-center">
          <span>v1.3.1 (Anti-Duplicate)</span>
          <div className={`w-2 h-2 rounded-full ${loading ? 'bg-yellow-500 animate-pulse' : 'bg-green-500'}`} title="Bağlantı Durumu"></div>
        </div>
      </nav>

      {/* 2. CENTER PANEL: Main Content Area (Flexible Width) */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative border-r border-slate-200">

        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 flex-shrink-0">
          <h1 className="text-xl font-semibold text-slate-800">
            {activeTab === 'IMPORT' ? 'Veri İçe Aktar' : 'Bilgi Bankası'}
          </h1>
          <div className="flex items-center gap-2">
            {activeTab === 'DATABASE' && (
              <span className="text-sm text-slate-500 bg-slate-100 px-3 py-1 rounded-full flex items-center gap-2">
                {loading && <ArrowPathIcon className="w-3 h-3 animate-spin" />}
                {accounts.length} Kayıt
              </span>
            )}
          </div>
        </header>

        {/* --- VIEW: DATABASE --- */}
        {activeTab === 'DATABASE' && (
          <>
            {/* Toolbar */}
            <div className="p-4 bg-white border-b border-slate-200 flex items-center gap-4 flex-shrink-0">
              <div className="relative flex-1 max-w-md">
                <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input 
                  type="text" 
                  placeholder="Hesap kodu, grup veya isim ara..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                />
              </div>
              <Button variant="secondary">
                <FunnelIcon className="w-4 h-4" />
                Filtrele
              </Button>
            </div>

            {/* Data Grid */}
            <div className="flex-1 overflow-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                  <tr>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-24">Kod</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200">Açıklama</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 hidden md:table-cell">Grup / Bilanz Posten</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 hidden lg:table-cell">Hesap Sınıfı</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-10"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 bg-white">
                  {filteredAccounts.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="py-12 text-center text-slate-400">
                        {loading 
                          ? "Veriler yükleniyor..." 
                          : (accounts.length === 0 
                             ? "Veritabanı boş. Lütfen 'Veri Ekle' menüsünden veri yükleyin." 
                             : "Arama kriterine uygun kayıt bulunamadı.")
                        }
                      </td>
                    </tr>
                  ) : (
                    filteredAccounts.map((account) => (
                      <tr 
                        key={account.id} 
                        onClick={() => setSelectedId(account.id)}
                        className={`cursor-pointer transition-colors group ${selectedId === account.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
                      >
                        <td className="py-3 px-4 text-sm font-medium text-slate-900 whitespace-nowrap">{account.code}</td>
                        <td className="py-3 px-4 text-sm text-slate-600 truncate max-w-xs">{account.description}</td>
                        <td className="py-3 px-4 text-xs text-slate-600 hidden md:table-cell truncate max-w-[200px]" title={account.bilanzPosten}>
                            {account.bilanzPosten || '-'}
                        </td>
                        <td className="py-3 px-4 text-xs text-slate-500 hidden lg:table-cell">
                            <span className="bg-slate-100 px-2 py-1 rounded text-slate-600 border border-slate-200 whitespace-nowrap">
                                {account.category}
                            </span>
                        </td>
                        <td className="py-3 px-4 text-slate-400 text-right">
                          <ChevronRightIcon className={`w-4 h-4 inline-block ${selectedId === account.id ? 'text-blue-500' : 'opacity-0 group-hover:opacity-100'}`} />
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </>
        )}

        {/* --- VIEW: IMPORT --- */}
        {activeTab === 'IMPORT' && (
          <div className="flex-1 overflow-y-auto p-6 md:p-12">
            <div className="max-w-4xl mx-auto space-y-8">

               <div className="text-center space-y-2 mb-8">
                  <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
                     <DocumentArrowUpIcon className="w-8 h-8" />
                  </div>
                  <h2 className="text-2xl font-semibold text-slate-800">Toplu Veri Ekleme Sihirbazı</h2>
                  <p className="text-slate-500">Muhasebe veya finansal verilerinizi ham metin olarak yapıştırın, sistem otomatik olarak Supabase veritabanına kaydetsin.</p>
               </div>

               <div className="space-y-4">
                  <label className="block text-sm font-medium text-slate-700">Veri Yapıştırma Alanı</label>
                  <div className="relative">
                    <textarea 
                      value={rawInput}
                      onChange={(e) => setRawInput(e.target.value)}
                      className="w-full h-96 p-6 text-sm font-mono border border-slate-300 rounded-xl focus:ring-4 focus:ring-blue-100 focus:border-blue-500 shadow-sm resize-none bg-white transition-all"
                      placeholder={`Örnek Format:
Posten2)
Programmverbindung4)
0005 Rückständige Fällige...
KU 0600-0800
...`}
                    ></textarea>
                    <div className="absolute bottom-4 right-4 text-xs text-slate-400">
                      {rawInput.split('\n').length} Satır
                    </div>
                  </div>
               </div>

               <div className="flex justify-end gap-4">
                  <Button variant="ghost" onClick={() => setRawInput("")}>Temizle</Button>
                  <Button 
                    onClick={handleProcessData} 
                    disabled={!rawInput.trim() || loading} 
                    className="px-8 py-3 text-base"
                  >
                    {loading ? 'İşleniyor...' : 'Verileri Analiz Et ve Yükle'}
                  </Button>
               </div>

            </div>
          </div>
        )}
      </main>

      {/* 3. RIGHT PANEL: Contextual Sidebar (Fixed Width) */}
      <aside className="w-96 bg-white flex flex-col border-l border-slate-200 shadow-xl flex-shrink-0 z-20">

        {/* Panel Header */}
        <div className="h-16 border-b border-slate-200 flex items-center justify-between px-6 bg-slate-50">
          <h2 className="font-semibold text-slate-800">
            {activeTab === 'DATABASE' ? 'Hesap Detayı' : 'Muhasebe Rehberi'}
          </h2>
        </div>

        {/* Panel Content */}
        <div className="flex-1 overflow-y-auto p-6">

          {/* CONTENT: When in IMPORT mode, show detailed accounting definitions */}
          {activeTab === 'IMPORT' && (
            <div className="space-y-8">

               {/* Introduction */}
               <div className="bg-indigo-50 border border-indigo-100 rounded-lg p-4">
                  <h3 className="flex items-center gap-2 font-semibold text-indigo-900 mb-2">
                     <BookOpenIcon className="w-5 h-5" />
                     Sistem Tanımı
                  </h3>
                  <p className="text-sm text-indigo-800 leading-relaxed">
                     Bu modül, standart hesap planı (SKR03/04 uyumlu) verilerini işler. Girilen veriler, bilançoda ve gelir tablosunda kullanılmak üzere kategorize edilir.
                  </p>
               </div>

               {/* Terminology Guide */}
               <div>
                 <h4 className="text-sm font-bold text-slate-800 flex items-center gap-2 mb-3 pb-2 border-b border-slate-100">
                    <AcademicCapIcon className="w-4 h-4 text-blue-500" />
                    Teknik Terimler Sözlüğü
                 </h4>
                 <ul className="space-y-4">
                    <li className="text-sm">
                        <span className="block font-semibold text-slate-700">Bilanz Posten (Bilanço Kalemi)</span>
                        <span className="text-slate-500 text-xs">Hesabın mali tabloda hangi ana başlık altında görüneceğini belirtir (Örn: Aktifler, Pasifler, Stoklar).</span>
                    </li>
                    <li className="text-sm">
                        <span className="block font-semibold text-slate-700">Programmverbindung</span>
                        <span className="text-slate-500 text-xs">Hesabın diğer muhasebe modülleriyle (Örn: Maliyet muhasebesi, Duran varlık yönetimi) olan teknik bağlantısını ifade eder.</span>
                    </li>
                    <li className="text-sm">
                        <span className="block font-semibold text-slate-700">KU (Kontenunterart)</span>
                        <span className="text-slate-500 text-xs">Hesap alt türü veya grup tanımlaması. Genellikle toplu hesap aralıklarını belirtmek için kullanılır.</span>
                    </li>
                 </ul>
               </div>

               {/* Account Classes Guide */}
               <div>
                 <h4 className="text-sm font-bold text-slate-800 flex items-center gap-2 mb-3 pb-2 border-b border-slate-100">
                    <FolderIcon className="w-4 h-4 text-blue-500" />
                    Hesap Sınıfları Referansı
                 </h4>
