                    filteredAccounts.map((account) => (
                      <tr key={account.id} onClick={() => setSelectedId(account.id)} className={`cursor-pointer transition-colors group active:bg-blue-100 ${selectedId === account.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}>
                        <td className="py-3 px-4 text-sm font-medium text-slate-900 whitespace-nowrap">{account.code}</td>
