               </div>

               {/* Expandable Filter Panel */}
               {showFilters && (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-4 bg-slate-50 border border-slate-200 rounded-lg animate-fade-in-down">
                     <div>
