                     <div>
                        <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">Bilanz Posten</label>
                        <select 
                           className="w-full border border-slate-300 rounded px-3 py-2 text-sm bg-white focus:ring-2 focus:ring-blue-500 outline-none"
                           value={filterBilanzPosten}
