// --- Helper Components ---

const Button: React.FC<{
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger-ghost';
  className?: string;
  fullWidth?: boolean;
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', fullWidth = false, disabled = false }) => {
  const baseStyle = "px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-sm",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
    "danger-ghost": "text-red-600 hover:bg-red-50 hover:text-red-700"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

// --- Logic Helpers ---

const getBasicAccountingInsight = (code: string): string => {
  const numericMatch = code.match(/\d+/);
  if (!numericMatch) return "Genel hesap.";
  const firstDigit = numericMatch[0][0];

  if (firstDigit === '0') return "Duran Varlıklar sınıfı.";
  if (firstDigit === '1') return "Dönen Varlıklar ve Finansal Hesaplar.";
  if (firstDigit === '2') return "Özkaynaklar veya Ara Hesaplar.";
  if (firstDigit === '3') return "Yabancı Kaynaklar (Borçlar).";
  if (firstDigit === '4') return "Gelir Hesapları.";
  if (firstDigit === '5' || firstDigit === '6') return "Gider Hesapları.";
  if (firstDigit === '9') return "Nazım Hesaplar.";
  return "Genel muhasebe hesabı.";
};

// --- Main Application ---

export default function App() {
  // State
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<ViewMode>('INVOICE'); 
  const [rawInput, setRawInput] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState<string>("");

  // Filtering State
  const [showFilters, setShowFilters] = useState(false);
  const [filterCategory, setFilterCategory] = useState<string>("");
  const [filterBilanzPosten, setFilterBilanzPosten] = useState<string>("");

  // AI & Image State (Chart of Accounts)
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analyzeStatus, setAnalyzeStatus] = useState<string>("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Invoice Entry State ---
  const [invoiceImage, setInvoiceImage] = useState<string | null>(null);
  const [invoiceData, setInvoiceData] = useState<InvoiceData | null>(null);
  const [isInvoiceProcessing, setIsInvoiceProcessing] = useState(false);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  // Insight AI State
  const [aiInsight, setAiInsight] = useState<string>("");
  const [isInsightLoading, setIsInsightLoading] = useState<boolean>(false);

  // Edit Form State
  const [editForm, setEditForm] = useState({
    programmverbindung: '',
    abschlusszweck: ''
  });

  // --- Common Error Handler ---
  const handleAIError = (error: any, context: 'Insight' | 'Invoice' | 'Upload') => {
    console.error(`AI Error (${context}):`, error);
    let userMessage = "İşlem sırasında bir hata oluştu.";

    const errStr = JSON.stringify(error);
    const msg = error.message || "";

    // Check for Quota/429
    if (
      msg.includes("429") || 
      msg.includes("Quota") ||
      msg.includes("RESOURCE_EXHAUSTED") ||
      errStr.includes("RESOURCE_EXHAUSTED") ||
      error.status === 429
    ) {
      userMessage = "⚠️ Servis Kotası Doldu (429).\nGoogle Gemini API kotası anlık olarak aşıldı. Lütfen 1 dakika bekleyip tekrar deneyin.";
    } else if (msg) {
      userMessage = `Hata: ${msg}`;
    }

    if (context === "Insight") {
      setAiInsight(userMessage);
    } else {
      alert(userMessage);
    }
  };

  // --- Supabase Integration ---

  const fetchAccounts = async (isBackground = false) => {
    if (!isBackground) setLoading(true);
    setErrorMsg(null);
    try {
      let allData: any[] = [];
      let page = 0;
      const pageSize = 1000;
      let hasMore = true;

      while (hasMore) {
        const from = page * pageSize;
        const to = from + pageSize - 1;

        const { data, error } = await supabase
          .from('accounts')
          .select('*')
          .range(from, to)
          .order('code', { ascending: true });

        if (error) throw error;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          if (data.length < pageSize) {
            hasMore = false;
          } else {
            page++;
          }
        } else {
          hasMore = false;
        }
        if (page > 20) hasMore = false;
      }

      const mappedData: AccountEntry[] = allData.map(item => ({
        id: item.id,
        code: item.code,
        description: item.description,
        category: item.category,
        bilanzPosten: item.bilanz_posten,
        programmverbindung: item.programmverbindung,
        abschlusszweck: item.abschlusszweck,
        ai_insight: item.ai_insight 
      }));

      setAccounts(mappedData);
    } catch (error: any) {
      console.error('Error fetching accounts:', error);
      setErrorMsg(error.message || "Veriler çekilemedi.");
    } finally {
      if (!isBackground) setLoading(false);
    }
  };

  useEffect(() => {
    fetchAccounts(false);

    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: '*', 
          schema: 'public',
          table: 'accounts',
        },
        () => {
          fetchAccounts(true);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // Sync Edit Form & Trigger AI Insight when selection changes
  useEffect(() => {
    let isMounted = true;
    if (selectedId) {
        const account = accounts.find(a => a.id === selectedId);
        if (account) {
            setEditForm({
                programmverbindung: account.programmverbindung || '',
                abschlusszweck: account.abschlusszweck || 'Seçiniz'
            });

            if (account.ai_insight && account.ai_insight.length > 10) {
                setAiInsight(account.ai_insight);
                setIsInsightLoading(false);
            } else {
                const generateInsight = async () => {
                  setIsInsightLoading(true);
                  setAiInsight(getBasicAccountingInsight(account.code)); 

                  try {
                    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                    const model = "gemini-3-flash-preview"; 

                    const prompt = `Sen uzman bir muhasebecisin (Alman Hesap Planı SKR03/04 uzmanı).
                    Şu hesabı analiz et:
                    Kod: ${account.code}
                    İsim: ${account.description}
                    Kategori: ${account.category}

                    Lütfen bu hesap için Türkçe, profesyonel ama anlaşılır bir "Hesap İçgörüsü" metni yaz.
                    Metin şu 3 maddeyi içermelidir (madde işaretleri kullanma, akıcı bir paragraf olsun):
                    1. Bu hesabın temel amacı nedir?
                    2. Mali tablolarda (Bilanço/Gelir Tablosu) nerede durur ve neyi etkiler?
                    3. Pratik bir kullanım örneği ver (Örn: "Şirket yeni bir makine aldığında bu hesaba borç kaydedilir" gibi).

                    Metni kısa tut (maksimum 3-4 cümle).`;

                    const result = await ai.models.generateContent({
                      model: model,
                      contents: prompt
                    });

                    if (isMounted && result.text) {
                      const generatedText = result.text;
                      setAiInsight(generatedText);
                      const { error } = await supabase
                        .from('accounts')
                        .update({ ai_insight: generatedText })
                        .eq('id', account.id);
                      if (error) console.error("Error saving insight:", error);
                      else {
                        setAccounts(prev => prev.map(a => 
                           a.id === account.id ? { ...a, ai_insight: generatedText } : a
                        ));
                      }
                    }
                  } catch (error) {
                    handleAIError(error, "Insight");
                  } finally {
                    if (isMounted) setIsInsightLoading(false);
                  }
                };
                generateInsight();
            }
        }
    } else {
      setAiInsight("");
    }
    return () => { isMounted = false; };
  }, [selectedId, accounts]);

  // Derived State & Filtering Logic
  const filteredAccounts = accounts.filter(acc => {
    const matchesSearch = 
      acc.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
      acc.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (acc.bilanzPosten && acc.bilanzPosten.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesCategory = filterCategory ? acc.category === filterCategory : true;
    const matchesBilanz = filterBilanzPosten ? acc.bilanzPosten === filterBilanzPosten : true;
    return matchesSearch && matchesCategory && matchesBilanz;
  });

  const selectedAccount = selectedId ? accounts.find(a => a.id === selectedId) : null;
  const uniqueCategories = Array.from(new Set(accounts.map(a => a.category).filter(c => c && c.trim() !== ""))).sort();
  const uniqueBilanzPosten = Array.from(new Set(accounts.map(a => a.bilanzPosten).filter(b => b && b.trim() !== ""))).sort();


  // --- Invoice Processing Logic ---

  // Handle Input Changes for Controlled Components
  const handleInvoiceChange = (field: keyof InvoiceData, value: string) => {
     if (invoiceData) {
        setInvoiceData({ ...invoiceData, [field]: value });
     }
  };

  const handleInvoiceUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;

    setIsInvoiceProcessing(true);
    setInvoiceImage(null);
    setInvoiceData(null);

    try {
      const base64 = await readFileAsBase64(file);
      const mimeType = file.type;

      if (mimeType.startsWith('image/')) {
        setInvoiceImage(`data:${mimeType};base64,${base64}`);
      } else {
        setInvoiceImage(null); 
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const model = "gemini-3-flash-preview"; 

      const prompt = `You are an expert invoice OCR agent. Analyze this image and extract data into strictly valid JSON.

      I need ALL individual line items (products/services) from the table in the invoice. Do not summarize them.

      Return this JSON structure:
      {
        "merchantName": "Name of the seller",
        "date": "Invoice date (DD.MM.YYYY)",
        "totalAmount": "Total Invoice Amount (with currency)",
        "taxAmount": "Total Tax/VAT Amount",
        "invoiceNumber": "Invoice Number",
        "items": [
          { 
            "description": "Full description of the item/service", 
            "quantity": "Quantity (e.g. 1, 5 kg, 10 hours)", 
            "unitPrice": "Price per unit",
            "total": "Total line amount"
          }
        ]
      }

      Rules:
      1. If a field is missing (like quantity), make a best guess or leave as empty string "".
      2. Extract ALL rows from the invoice table.
      3. Return ONLY the JSON string, no markdown formatting. Do not include \`\`\`json blocks.`;

      const result = await ai.models.generateContent({
        model: model,
        contents: {
          parts: [
            { inlineData: { mimeType: mimeType, data: base64 } },
            { text: prompt }
          ]
        },
        config: {
            responseMimeType: "application/json"
        }
      });

      if (result.text) {
        try {
            // Cleanup potential markdown fences if model outputs them
            let cleanText = result.text.trim();
            cleanText = cleanText.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/\s*```$/, '');

            const parsedData = JSON.parse(cleanText);
            setInvoiceData(parsedData);
        } catch (jsonErr) {
            console.error("JSON Parse Error", jsonErr);
            alert("Fatura verisi okunamadı. Yapay zeka geçerli bir JSON döndürmedi.");
        }
      }

    } catch (err: any) {
        handleAIError(err, "Invoice");
    } finally {
        setIsInvoiceProcessing(false);
        if (invoiceInputRef.current) invoiceInputRef.current.value = '';
    }
  };


  // --- General Parsing Logic ---
  const processAndInsertData = async (textInput: string) => {
    const lines = textInput.split('\n');
    const newEntries = [];
    const isMarkdownTable = lines.some(line => line.includes('|') && line.includes('---'));

    if (isMarkdownTable) {
        let currentCategory = "";
        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith('|-') || !trimmed.includes('|')) continue;
            const cols = trimmed.split('|').map(c => c.trim()).filter(c => c !== '');
            if (cols[0]?.toLowerCase().includes('category') || cols[0]?.toLowerCase().includes('bilanz')) continue;

            if (cols.length >= 2) {
                let category = cols[0];
                let code = "";
                let name = "";

                if (!category) {
                    category = currentCategory;
                } else {
                    currentCategory = category;
                }

                if (cols.length >= 3) {
                    code = cols[1];
                    name = cols[2];
                } else {
                    code = cols[1];
                    name = "İsimsiz Hesap"; 
                }

                if (code && code.match(/\d+/)) {
                    newEntries.push({
                        code: code,
                        description: name,
                        category: "Genel",
                        bilanz_posten: category,
                        ai_insight: null
                    });
                }
            }
        }
    } else {
        let currentClass = "Genel";
        let currentBilanzPosten = "";
        let buffer: string[] = [];
        let expectingClassName = false;
        let pendingClassDigit = "";
        const ignorePatterns = [/^Bilanz-?$/i, /^Posten\d*\)?$/i, /^Programmverbindung\d*\)?$/i, /^Abschlusszweck\d*\)?$/i, /^\d+\)$/, /^Bilanz-$/];

        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed) continue;
            if (ignorePatterns.some(p => p.test(trimmed))) continue;

            if (/^\d$/.test(trimmed)) {
                pendingClassDigit = trimmed;
                expectingClassName = true;
                buffer = []; 
                continue;
            }

            if (expectingClassName) {
                currentClass = `${pendingClassDigit} ${trimmed}`;
                expectingClassName = false;
                buffer = []; 
                currentBilanzPosten = ""; 
                continue;
            }

            const codeMatch = trimmed.match(/^(\d{4}|KU\s?[\d-]+|R\s?\d{4}[-]?\d{0,2})\s+(.*)/);

            if (codeMatch) {
                if (buffer.length > 0) {
                    currentBilanzPosten = buffer.join(" ");
                    buffer = [];
                }
                newEntries.push({ code: codeMatch[1], description: codeMatch[2], category: currentClass, bilanz_posten: currentBilanzPosten, ai_insight: null });
            } else {
                if (trimmed.length > 1) buffer.push(trimmed);
            }
        }
    }

    if (newEntries.length > 0) {
        const uniqueCodesInBatch = new Set();
        const deduplicatedEntries = [];
        for (const entry of newEntries) {
            if (!uniqueCodesInBatch.has(entry.code)) {
                uniqueCodesInBatch.add(entry.code);
                deduplicatedEntries.push(entry);
            }
        }
        const codesToCheck = deduplicatedEntries.map(e => e.code);
        const { data: existingData, error: checkError } = await supabase.from('accounts').select('code').in('code', codesToCheck);
        if (checkError) throw checkError;

        const existingSet = new Set(existingData?.map(d => d.code));
        const finalEntriesToInsert = deduplicatedEntries.filter(e => !existingSet.has(e.code));

        if (finalEntriesToInsert.length > 0) {
            const { error: insertError } = await supabase.from('accounts').insert(finalEntriesToInsert);
            if (insertError) throw new Error("Kayıt hatası: " + insertError.message);
            return { success: true, count: finalEntriesToInsert.length, skipped: deduplicatedEntries.length - finalEntriesToInsert.length };
        } else {
            return { success: true, count: 0, skipped: deduplicatedEntries.length };
        }
    }
    return { success: false, count: 0, skipped: 0 };
  };

  const handleProcessManualInput = useCallback(async () => {
    if (!rawInput.trim()) return;
    setLoading(true);
    try {
        const result = await processAndInsertData(rawInput);
        if (result.success) {
             if (result.count > 0) {
                alert(`${result.count} yeni kayıt eklendi.\n${result.skipped} mükerrer kayıt atlandı.`);
                setRawInput("");
                setActiveTab('DATABASE');
             } else {
                alert("Yeni kayıt bulunamadı (Tümü zaten mevcut).");
             }
        } else {
             alert("İşlenecek geçerli veri bulunamadı.");
        }
    } catch (e: any) {
        alert("Hata: " + e.message);
    } finally {
        setLoading(false);
    }
  }, [rawInput]);

  const handleUpdate = async () => {
    if (!selectedId) return;
    const { error } = await supabase.from('accounts').update({
            programmverbindung: editForm.programmverbindung,
            abschlusszweck: editForm.abschlusszweck === 'Seçiniz' ? null : editForm.abschlusszweck
        }).eq('id', selectedId);
    if (error) alert("Güncelleme hatası: " + error.message);
  };

  const readFileAsBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
            const result = reader.result as string;
            const base64 = result.split(',')[1];
            resolve(base64);
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  };

  const handleAutomaticFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setIsAnalyzing(true);
    setAnalyzeStatus("Dosya okunuyor...");
    try {
        const base64Data = await readFileAsBase64(file);
        setAnalyzeStatus("AI Analizi yapılıyor...");
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const model = "gemini-3-flash-preview"; 
        const prompt = `Act as an expert accountant and OCR specialist. Analyze the attached file (Image or PDF) which shows a German Chart of Accounts (Kontenrahmen).
Convert this document content into a structured Markdown Table.
Columns MUST be: | Category | Code | Name |
If Category is missing, use the previous one. Ensure Codes are 4 digits.
Output ONLY the markdown table.`;
        const response = await ai.models.generateContent({
            model: model,
            contents: {
                parts: [
                    { inlineData: { mimeType: file.type, data: base64Data } },
                    { text: prompt }
                ]
            }
        });
        const text = response.text;
        if (text) {
            setAnalyzeStatus("Veriler ayrıştırılıyor ve kaydediliyor...");
            const result = await processAndInsertData(text);
            setIsAnalyzing(false);
            setAnalyzeStatus("");
            if (result.success) {
                if (result.count > 0) {
                   alert(`Başarılı! ${result.count} yeni kayıt eklendi.`);
                   setActiveTab('DATABASE');
                } else {
                   alert("Dosya analiz edildi ancak eklenecek YENİ kayıt bulunamadı.");
                }
            } else {
                alert("Dosyadan anlamlı veri çıkarılamadı.");
            }
        } else {
            throw new Error("AI boş yanıt döndürdü.");
        }
    } catch (error: any) {
        handleAIError(error, "Upload");
        setIsAnalyzing(false);
        setAnalyzeStatus("");
    } finally {
        if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  return (
    <div className="flex h-[100dvh] w-full bg-white overflow-hidden flex-col md:flex-row">

      {/* 1. LEFT PANEL (Navigation) */}
      <nav className="hidden md:flex md:w-64 bg-slate-900 text-slate-300 flex-col border-r border-slate-800 flex-shrink-0">
        <div className="p-4 h-16 flex items-center border-b border-slate-800">
          <div className="flex items-center gap-2 text-white font-semibold text-lg">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <TableCellsIcon className="w-5 h-5" />
            </div>
            AccuParse
          </div>
        </div>
        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-3 space-y-1">
             <p className="px-3 text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Veri Yönetimi</p>
            {/* NEW INVOICE ENTRY BUTTON AT TOP */}
            <button onClick={() => setActiveTab('INVOICE')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'INVOICE' ? 'bg-blue-600 text-white' : 'hover:bg-slate-800'}`}>
              <ReceiptPercentIcon className="w-5 h-5" />
              <span>Fatura Girişi</span>
            </button>
            <button onClick={() => setActiveTab('IMPORT')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'IMPORT' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}>
              <DocumentArrowUpIcon className="w-5 h-5" />
              <span>Veri Ekle / Import</span>
            </button>
            <button onClick={() => setActiveTab('DATABASE')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'DATABASE' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}>
              <ArchiveBoxIcon className="w-5 h-5" />
              <span>Bilgi Bankası</span>
            </button>
          </div>
        </div>
        <div className="p-4 border-t border-slate-800 text-xs text-slate-500 flex justify-between items-center">
          <span>v1.9 (Invoice+)</span>
          <div className={`w-2 h-2 rounded-full ${loading ? 'bg-yellow-500 animate-pulse' : 'bg-green-500'}`} title="Bağlantı Durumu"></div>
        </div>
      </nav>

      {/* 2. CENTER PANEL (Main Content) */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative border-r border-slate-200 h-full overflow-hidden pb-16 md:pb-0">
