  // Mock data for accounts
  const accounts: AccountEntry[] = [
      { id: '1', code: '1200', description: 'Bank', category: 'Assets', bilanzPosten: 'B1' },
      { id: '2', code: '4400', description: 'Revenue', category: 'Income', bilanzPosten: 'B2' }
  ];

  // Derived state
  const uniqueCategories = useMemo(() => Array.from(new Set(accounts.map(a => a.category).filter(Boolean))), []);
  const uniqueBilanzPosten = useMemo(() => Array.from(new Set(accounts.map(a => a.bilanzPosten).filter(Boolean))), []);

  const filteredAccounts = useMemo(() => {
    return accounts.filter(acc => {
        const matchesSearch = acc.code.toLowerCase().includes(searchTerm.toLowerCase()) || acc.description.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = filterCategory ? acc.category === filterCategory : true;
        const matchesBilanz = filterBilanzPosten ? acc.bilanzPosten === filterBilanzPosten : true;
        return matchesSearch && matchesCategory && matchesBilanz;
    });
  }, [searchTerm, filterCategory, filterBilanzPosten]);

  // Handlers
  const loadHistoryItem = (item: InvoiceData) => {
      setInvoiceData(item);
      setInvoiceImage(item.imageData || null);
      setIsViewingHistory(true);
  };

  const deleteHistoryItem = (e: React.MouseEvent, id: string) => {
      e.stopPropagation();
      setInvoiceHistory(prev => prev.filter(item => item.id !== id));
      if (invoiceData?.id === id) {
          setInvoiceData(null);
          setInvoiceImage(null);
      }
  };

  const handleAutomaticFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
          // Mock upload logic
          setIsAnalyzing(true);
          setAnalyzeStatus("Uploading...");
          setTimeout(() => {
              setIsAnalyzing(false);
              setAnalyzeStatus("");
              // Mock result
              const newItem: InvoiceData = {
                  id: Date.now().toString(),
                  merchantName: "Demo Merchant",
                  date: new Date().toISOString().split('T')[0],
                  totalAmount: "123.45",
                  taxAmount: "23.45",
                  invoiceNumber: "INV-001",
                  items: [
                      { description: "Item 1", quantity: "1", unitPrice: "100.00", total: "100.00", accountCode: "4400" }
                  ],
                  imageData: URL.createObjectURL(file)
              };
              setInvoiceHistory(prev => [newItem, ...prev]);
              loadHistoryItem(newItem);
              setActiveTab('HISTORY');
          }, 2000);
      }
  };

  const handleProcessManualInput = () => {
      setLoading(true);
      setTimeout(() => {
          setLoading(false);
          // Mock processing
           const newItem: InvoiceData = {
                  id: Date.now().toString(),
                  merchantName: "Manual Entry",
                  date: new Date().toISOString().split('T')[0],
                  totalAmount: "0.00",
                  taxAmount: "0.00",
                  invoiceNumber: "MAN-001",
                  items: [],
                  imageData: null
              };
          setInvoiceHistory(prev => [newItem, ...prev]);
          loadHistoryItem(newItem);
          setActiveTab('HISTORY');
          setRawInput("");
      }, 1000);
  };

  const handlePrint = () => {
      window.print();
  };

  return (
    <div className="flex h-screen w-screen bg-slate-100 overflow-hidden font-sans text-slate-900">
      {/* 1. LEFT PANEL - Navigation */}
      <nav className="w-16 md:w-64 bg-slate-900 flex-shrink-0 flex flex-col justify-between text-slate-300">
        <div className="flex flex-col">
            <div className="h-16 flex items-center justify-center md:justify-start md:px-6 border-b border-slate-800">
                <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold">A</div>
                <span className="ml-3 font-semibold text-white hidden md:block">AccountingAI</span>
            </div>
            <div className="flex flex-col py-4 gap-1">
                <button 
                    onClick={() => setActiveTab('IMPORT')}
                    className={`h-12 flex items-center px-4 md:px-6 hover:bg-slate-800 transition-colors ${activeTab === 'IMPORT' ? 'text-white bg-slate-800 border-l-4 border-blue-500' : 'border-l-4 border-transparent'}`}
                >
                    <DocumentArrowUpIcon className="w-6 h-6" />
                    <span className="ml-3 hidden md:block">Import</span>
                </button>
                <button 
                    onClick={() => setActiveTab('DATABASE')}
                    className={`h-12 flex items-center px-4 md:px-6 hover:bg-slate-800 transition-colors ${activeTab === 'DATABASE' ? 'text-white bg-slate-800 border-l-4 border-blue-500' : 'border-l-4 border-transparent'}`}
                >
                    <ClipboardDocumentListIcon className="w-6 h-6" />
                    <span className="ml-3 hidden md:block">Database</span>
                </button>
                <button 
                    onClick={() => setActiveTab('HISTORY')}
                    className={`h-12 flex items-center px-4 md:px-6 hover:bg-slate-800 transition-colors ${activeTab === 'HISTORY' ? 'text-white bg-slate-800 border-l-4 border-blue-500' : 'border-l-4 border-transparent'}`}
                >
                    <div className="relative">
                        <ReceiptPercentIcon className="w-6 h-6" />
                        {invoiceHistory.length > 0 && <span className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-slate-900"></span>}
                    </div>
                    <span className="ml-3 hidden md:block">History</span>
                </button>
            </div>
        </div>
        <div className="p-4 border-t border-slate-800 hidden md:block">
            <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center">U</div>
                <div className="text-xs">
                    <p className="text-white font-medium">User</p>
                    <p className="text-slate-500">Free Plan</p>
                </div>
            </div>
        </div>
      </nav>

      {/* 2. MIDDLE PANEL - Main Content */}
      <main className="flex-1 flex flex-col min-w-0 bg-white border-r border-slate-200 relative">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 md:px-8 flex-shrink-0 z-20">
            <h1 className="text-lg font-bold text-slate-800 uppercase tracking-wide">
                {activeTab === 'DATABASE' ? 'Kontenrahmen' : activeTab === 'IMPORT' ? 'Invoice Import' : 'Invoice History'}
            </h1>
        </header>

        {activeTab === 'HISTORY' && (
            <div className="flex-1 overflow-auto bg-slate-50 p-4">
                <div className="max-w-4xl mx-auto">
                    {invoiceHistory.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                             <div className="p-4 bg-white rounded-full shadow-sm mb-4">
                                <ClipboardDocumentListIcon className="w-12 h-12 text-slate-300" />
                             </div>
                             <p>{t.ai_hint_history_empty}</p>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-2">
                            {/* Header Row */}
                            <div className="grid grid-cols-12 gap-2 px-4 py-2 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200">
                                <div className="col-span-1 text-center text-slate-400">#</div>
                                <div className="col-span-5">Firma / Satıcı</div>
                                <div className="col-span-3">Tarih / No</div>
                                <div className="col-span-2 text-right">Tutar</div>
                                <div className="col-span-1"></div>
                            </div>

                            {/* List Items */}
                            {invoiceHistory.map((inv, index) => (
                                <div 
                                    key={inv.id}
                                    onClick={() => loadHistoryItem(inv)}
                                    className={`bg-white rounded-lg shadow-sm border cursor-pointer transition-all hover:shadow-md ${invoiceData?.id === inv.id ? 'border-blue-500 ring-1 ring-blue-500' : 'border-slate-200'}`}
                                >
                                    <div className="grid grid-cols-12 gap-2 p-4 items-center">
                                        <div className="col-span-1 text-center text-slate-400 font-mono text-xs font-bold">
                                            {index + 1}
                                        </div>
                                        <div className="col-span-5 flex items-center gap-3">
                                            <div className="p-2 bg-blue-50 text-blue-600 rounded-lg flex-shrink-0 hidden sm:block">
                                                <ReceiptPercentIcon className="w-5 h-5" />
                                            </div>
                                            <div className="truncate font-semibold text-slate-800 text-sm">
                                                {inv.merchantName || 'Bilinmeyen Satıcı'}
                                            </div>
                                        </div>
                                        <div className="col-span-3 flex flex-col justify-center text-xs text-slate-500">
                                            <span className="flex items-center gap-1"><CalendarDaysIcon className="w-3 h-3" /> {inv.date || '-'}</span>
                                            <span className="flex items-center gap-1 text-slate-400 mt-0.5"><HashtagIcon className="w-3 h-3" /> {inv.invoiceNumber || '-'}</span>
                                        </div>
                                        <div className="col-span-2 text-right">
                                            <div className="font-mono font-bold text-slate-800 text-sm">{inv.totalAmount || '0.00'}</div>
                                            <div className="text-[10px] text-slate-400 uppercase">Toplam</div>
                                        </div>
                                        <div className="col-span-1 flex justify-end">
                                            {invoiceData?.id === inv.id ? <ChevronUpIcon className="w-4 h-4 text-blue-500" /> : <ChevronDownIcon className="w-4 h-4 text-slate-400" />}
                                        </div>
                                    </div>

                                    {/* EXPANDED DETAILS: ITEM LIST */}
                                    {invoiceData?.id === inv.id && inv.items && inv.items.length > 0 && (
                                        <div className="border-t border-slate-100 bg-slate-50/50 p-4 rounded-b-lg">
                                            <p className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider mb-2 flex items-center gap-1">
                                                <SparklesIcon className="w-3 h-3" /> {t.label_items}
                                            </p>
                                            <div className="space-y-2">
                                                {inv.items.map((item, idx) => (
                                                    <div key={idx} className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 text-sm bg-white border border-slate-100 p-2 rounded shadow-sm">
                                                        {/* ACCOUNT CODE (First Position) */}
                                                        <div className="flex-shrink-0">
                                                            <span className="font-mono font-bold text-blue-700 bg-blue-50 border border-blue-100 px-2 py-1 rounded text-xs min-w-[3.5rem] text-center inline-block shadow-sm">
                                                                {item.accountCode || '?'}
                                                            </span>
                                                        </div>
                                                        {/* DESCRIPTION */}
                                                        <div className="flex-1 min-w-0">
                                                            <p className="text-slate-700 truncate font-medium">{item.description}</p>
                                                        </div>
                                                        {/* TOTAL */}
                                                        <div className="flex-shrink-0 text-right">
                                                            <span className="font-mono text-slate-600 font-semibold">{item.total}</span>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>

                                            <div className="mt-3 flex justify-end">
                                                <button onClick={(e) => deleteHistoryItem(e, inv.id)} className="text-xs text-red-500 hover:text-red-700 hover:underline flex items-center gap-1">
                                                    <TrashIcon className="w-3 h-3" /> Sil
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        )}

        {activeTab === 'DATABASE' && (
          <>
            <div className="p-4 bg-white border-b border-slate-200 flex flex-col gap-3 flex-shrink-0">
               <div className="flex flex-col sm:flex-row items-center gap-3 w-full">
                  <div className="relative w-full sm:flex-1">
                     <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                     <input type="text" placeholder={t.label_search} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm" />
                  </div>
                  <Button variant={showFilters ? 'primary' : 'secondary'} onClick={() => setShowFilters(!showFilters)} className="whitespace-nowrap">
                     <FunnelIcon className="w-5 h-5" /> {t.btn_filter}
                  </Button>
               </div>

               {showFilters && (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-4 bg-slate-50 border border-slate-200 rounded-lg">
                     <div>
                        <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">{t.label_category}</label>
                        <select 
                           className="w-full border border-slate-300 rounded px-3 py-2 text-sm bg-white focus:ring-2 focus:ring-blue-500 outline-none"
                           value={filterCategory}
                           onChange={(e) => setFilterCategory(e.target.value)}
                        >
                           <option value="">All</option>
                           {uniqueCategories.map((cat, idx) => (
                              <option key={idx} value={cat}>{cat}</option>
                           ))}
                        </select>
                     </div>
                     <div>
                        <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">{t.label_bilanz}</label>
                        <select 
                           className="w-full border border-slate-300 rounded px-3 py-2 text-sm bg-white focus:ring-2 focus:ring-blue-500 outline-none"
                           value={filterBilanzPosten}
                           onChange={(e) => setFilterBilanzPosten(e.target.value)}
                        >
                           <option value="">All</option>
                           {uniqueBilanzPosten.map((bp, idx) => (
                              <option key={idx} value={bp}>{bp}</option>
                           ))}
                        </select>
                     </div>
                     <div className="sm:col-span-2 flex justify-end">
                        <button onClick={() => { setFilterCategory(""); setFilterBilanzPosten(""); }} className="text-xs text-blue-600 hover:underline">{t.btn_filter_clear}</button>
                     </div>
                  </div>
               )}
            </div>

            {errorMsg && (
              <div className="bg-red-50 border-b border-red-200 p-4 text-red-700 text-sm flex items-center gap-2">
                 <XMarkIcon className="w-5 h-5" />
                 {errorMsg}
              </div>
            )}

            <div className="flex-1 overflow-auto bg-white">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                  <tr>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-20 md:w-24">{t.label_code}</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200">{t.label_desc}</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 hidden md:table-cell">{t.label_category}</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-10"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 bg-white">
                  {filteredAccounts.length === 0 ? (
                    <tr><td colSpan={4} className="py-12 text-center text-slate-400">{loading ? "..." : "No data"}</td></tr>
                  ) : (
                    filteredAccounts.map((account) => (
                      <tr key={account.id} onClick={() => setSelectedId(account.id)} className={`cursor-pointer transition-colors group active:bg-blue-100 ${selectedId === account.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}>
                        <td className="py-3 px-4 text-sm font-medium text-slate-900 whitespace-nowrap">{account.code}</td>
                        <td className="py-3 px-4 text-sm text-slate-600 truncate max-w-[150px] md:max-w-xs">{account.description}</td>
                        <td className="py-3 px-4 text-xs text-slate-600 hidden md:table-cell truncate max-w-[200px]">{account.bilanzPosten || '-'}</td>
                        <td className="py-3 px-4 text-slate-400 text-right"><ChevronRightIcon className={`w-4 h-4 inline-block ${selectedId === account.id ? 'text-blue-500' : 'opacity-100 md:opacity-0 group-hover:opacity-100'}`} /></td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </>
        )}

        {activeTab === 'IMPORT' && (
          <div className="flex-1 overflow-y-auto p-4 md:p-12">
            <div className="max-w-4xl mx-auto space-y-6">
               <div className="text-center space-y-2 mb-6 md:mb-8">
                  <div className="w-12 h-12 md:w-16 md:h-16 bg-blue-100 text-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-4"><DocumentArrowUpIcon className="w-6 h-6 md:w-8 md:h-8" /></div>
                  <h2 className="text-xl md:text-2xl font-semibold text-slate-800">{t.empty_import_title}</h2>
                  <p className="text-sm md:text-base text-slate-500">
                    {t.empty_import_desc}
                  </p>
               </div>

               <div className={`bg-slate-50 border-2 border-dashed ${isAnalyzing ? 'border-blue-400 bg-blue-50' : isUploadModeEnabled ? 'border-slate-300' : 'border-slate-200 bg-slate-100'} rounded-xl p-6 md:p-8 transition-all relative`}>

                  {/* Lock Overlay when Upload is Disabled */}
                  {!isUploadModeEnabled && !isAnalyzing && (
                      <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-slate-100/50 rounded-xl cursor-not-allowed">
                          <div className="bg-white p-3 rounded-full shadow-sm mb-2">
                             <LockClosedIcon className="w-6 h-6 text-slate-400" />
                          </div>
                          <p className="text-sm font-medium text-slate-500">{t.btn_upload_lock_msg}</p>
                          <p className="text-xs text-slate-400 mt-1">{t.btn_upload_lock_sub}</p>
                      </div>
                  )}

                  {isAnalyzing && (
                    <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-10 flex flex-col items-center justify-center rounded-xl p-4 text-center">
                        <SparklesIcon className="w-10 h-10 text-blue-600 animate-spin mb-3" />
                        <p className="text-base font-semibold text-slate-800">{t.status_ai_working}</p>
                        <p className="text-xs text-slate-500 mt-1">{analyzeStatus}</p>
                    </div>
                  )}

                  <div className={`flex flex-col items-center justify-center space-y-4 ${!isUploadModeEnabled ? 'opacity-30 blur-[1px]' : ''}`}>
                     <div className="p-3 bg-white rounded-full shadow-sm"><PhotoIcon className="w-8 h-8 text-slate-400" /></div>
                     <div className="text-center">
                        <p className="text-sm font-medium text-slate-700">PDF / IMG</p>
                     </div>
                     <input type="file" ref={fileInputRef} accept="image/*,application/pdf" onChange={handleAutomaticFileUpload} className="hidden" />
                     <Button 
                       variant={isUploadModeEnabled ? 'primary' : 'secondary'} 
                       fullWidth 
                       onClick={() => isUploadModeEnabled && fileInputRef.current?.click()} 
                       disabled={isAnalyzing || !isUploadModeEnabled}
                     >
                        {isAnalyzing ? t.status_processing : t.btn_select_file}
                     </Button>
                  </div>
               </div>

               <div className="relative py-2">
                  <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
                  <div className="relative flex justify-center text-xs"><span className="px-2 bg-slate-50 text-slate-500">{t.manual_or}</span></div>
               </div>

               <div className="space-y-3">
                  <textarea value={rawInput} onChange={(e) => setRawInput(e.target.value)} className="w-full h-40 p-4 text-xs font-mono border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 shadow-sm resize-none bg-white" placeholder={t.manual_placeholder}></textarea>
               </div>
               <div className="flex justify-end gap-3">
                  <Button variant="ghost" onClick={() => setRawInput("")}>{t.btn_clear}</Button>
                  <Button onClick={handleProcessManualInput} disabled={!rawInput.trim() || loading}>{loading ? '...' : t.btn_process}</Button>
               </div>
            </div>
          </div>
        )}
      </main>

      {/* 3. RIGHT PANEL (Details or Invoice Image) */}
      <aside className={`
        fixed inset-0 z-50 bg-white flex flex-col transition-transform duration-300 ease-in-out
        md:static md:border-l md:border-slate-200 md:shadow-xl md:transform-none md:z-auto
        md:w-96
        ${selectedId || (activeTab === 'INVOICE' && selectedInvoiceItemIndex !== null) || (activeTab === 'HISTORY' && invoiceImage) ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
        ${!selectedId && activeTab === 'DATABASE' && 'hidden md:block'} 
        ${activeTab === 'INVOICE' && 'md:block'}
        ${activeTab === 'HISTORY' && 'md:block'}
      `}>
        <div className="h-16 border-b border-slate-200 flex items-center justify-between px-6 bg-slate-50 flex-shrink-0">
          <div className="flex items-center gap-2">
            {/* Mobile Back Button */}
            <button onClick={() => { setSelectedId(null); setSelectedInvoiceItemIndex(null); setIsViewingHistory(false); setInvoiceImage(null); }} className="md:hidden p-1 -ml-2 text-slate-500 hover:text-slate-800">
               <ArrowLeftIcon className="w-6 h-6" />
            </button>
            <h2 className="font-semibold text-slate-800">
               {activeTab === 'DATABASE' ? t.header_detail_account : 
                activeTab === 'INVOICE' && isViewingHistory ? t.header_detail_image :
                activeTab === 'HISTORY' ? t.header_detail_image :
                activeTab === 'INVOICE' && selectedInvoiceItemIndex !== null ? t.header_detail_item : t.header_detail_guide}
            </h2>
          </div>
          <div className="flex items-center gap-2">
            {/* Print Icon for History View */}
            {activeTab === 'HISTORY' && invoiceImage && (
                <button onClick={handlePrint} className="p-1 text-slate-500 hover:text-blue-600" title={t.btn_print}>
                    <PrinterIcon className="w-5 h-5" />
                </button>
            )}
             {/* Mobile Close Button */}
            <button onClick={() => { setSelectedId(null); setSelectedInvoiceItemIndex(null); setIsViewingHistory(false); setInvoiceImage(null); }} className="md:hidden text-slate-400 hover:text-red-500">
                <span className="text-sm font-medium">{t.btn_close}</span>
            </button>
          </div>
        </div>

        {/* Dynamic Container: Removes Padding only when showing an Invoice Image */}
        <div className={`flex-1 flex flex-col ${activeTab === 'HISTORY' && invoiceImage ? 'overflow-hidden bg-slate-100' : 'overflow-y-auto p-6 pb-24 md:pb-6'}`}>

          {/* SCENARIO 0: VIEWING HISTORY INVOICE IMAGE */}
          {activeTab === 'HISTORY' && (
              invoiceImage ? (
                <div className="w-full h-full flex items-center justify-center p-2">
                    {invoiceImage.startsWith('data:application/pdf') ? (
                        <embed src={invoiceImage} type="application/pdf" className="w-full h-full" />
                    ) : (
                        <img src={invoiceImage} alt="Invoice Scan" className="max-w-full max-h-full object-contain shadow-sm rounded border border-slate-200" />
                    )}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-center text-slate-400 space-y-4">
                  <div className="p-4 bg-slate-50 rounded-full"><PhotoIcon className="w-12 h-12 text-slate-300" /></div>
                  <p className="text-sm">{t.empty_history_select}</p>
               </div>
              )
          )}

          {/* Fallback for Database Details (when no logic provided in snippet) */}
          {activeTab === 'DATABASE' && selectedId && (
              <div>
                  <p className="text-slate-600">Details for account <span className="font-bold">{selectedId}</span></p>
                  {/* Placeholder for actual detail view content */}
              </div>
          )}

          {activeTab === 'DATABASE' && !selectedId && (
              <div className="flex flex-col items-center justify-center h-full text-slate-400">
                  <p>{t.header_detail_guide}</p>
              </div>
          )}

        </div>
      </aside>
    </div>
  );
}

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { 
  ClipboardDocumentListIcon, 
  ReceiptPercentIcon, 
  CalendarDaysIcon, 
  HashtagIcon, 
  ChevronUpIcon, 
  ChevronDownIcon, 
  SparklesIcon, 
  TrashIcon, 
