        <div className="h-16 flex items-center px-6 border-b border-slate-800 bg-[#0f172a]">
             <div className="flex items-center gap-2 text-white">
                <div className="w-8 h-8 bg-blue-600 rounded flex items-center justify-center font-bold text-lg">A</div>
                <span className="font-bold text-lg tracking-tight">{t.app_name}</span>
             </div>
        </div>

        {/* User Info (Small) */}
        <div className="px-6 py-4 border-b border-slate-800 flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center text-white font-bold">
                {user.role === 'admin' ? 'A' : user.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
                <div className="text-sm font-semibold text-white truncate">{user.name}</div>
                <div className="text-[10px] text-slate-500 uppercase">{user.role === 'admin' ? 'Administrator' : 'Company User'}</div>
            </div>
        </div>

        {/* Menu Items */}
        <div className="flex-col py-6 space-y-1 px-3">
            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider px-3 mb-2">VERİ YÖNETİMİ</div>

            <button className="w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 transition-colors">
                <PencilSquareIcon className="w-5 h-5 mr-3" />
                {t.nav_fatura_girisi}
            </button>

            <button 
                onClick={() => setActiveTab('HISTORY')}
                className={`w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'HISTORY' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            >
                <ClipboardDocumentListIcon className="w-5 h-5 mr-3" />
                {t.nav_fatura_listesi}
            </button>

            <button 
                onClick={() => setActiveTab('IMPORT')}
                className={`w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            >
                <DocumentArrowUpIcon className="w-5 h-5 mr-3" />
                {t.nav_import}
            </button>

            <button 
                onClick={() => setActiveTab('DATABASE')}
                className={`w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'DATABASE' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            >
                <ArchiveBoxIcon className="w-5 h-5 mr-3" />
                {t.nav_bilgi_bankasi}
            </button>

            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider px-3 mb-2 mt-4">İLETİŞİM</div>

            <button 
                onClick={() => setActiveTab('MESSAGES')}
                className={`w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'MESSAGES' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            >
                <ChatBubbleLeftRightIcon className="w-5 h-5 mr-3" />
                {t.nav_mesajlar}
                {user.role === 'admin' && <span className="ml-auto bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">2</span>}
            </button>

        </div>

        {/* Bottom Area */}
        <div className="mt-auto p-4 border-t border-slate-800">
            <button onClick={() => setUser(null)} className="w-full flex items-center px-3 py-2 rounded text-slate-400 hover:bg-slate-800 hover:text-white mb-4 transition-colors">
                <ArrowRightOnRectangleIcon className="w-4 h-4 mr-2" />
                <span className="text-xs">Çıkış Yap</span>
            </button>

            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2">AYARLAR</div>
            <div className="flex items-center justify-between p-2 rounded bg-slate-800/50 border border-slate-700/50">
                <span className="text-xs text-slate-400">Dil / Sprache</span>
                <div className="flex text-[10px] font-bold">
                    <span className="bg-blue-600 text-white px-1.5 py-0.5 rounded-l">TR</span>
                    <span className="bg-slate-700 text-slate-400 px-1.5 py-0.5 rounded-r">DE</span>
                </div>
            </div>
            <div className="mt-4 text-[10px] text-slate-600">v2.3 (Invoice List)</div>
        </div>
      </nav>

      {/* 2. MIDDLE PANEL (Dynamic Content) */}
      <main className="flex-1 flex flex-col min-w-0 bg-white border-r border-slate-200">

        {/* HEADER AREA */}
        <div className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 flex-shrink-0">
            <h1 className="text-xl font-bold text-slate-800">
                {activeTab === 'DATABASE' && t.nav_bilgi_bankasi}
                {activeTab === 'HISTORY' && t.nav_fatura_listesi}
                {activeTab === 'IMPORT' && t.nav_import}
                {activeTab === 'MESSAGES' && t.nav_mesajlar}
            </h1>
            {activeTab === 'HISTORY' && (
                <div className="flex items-center gap-2 text-sm text-slate-400">
                    <span>{invoiceHistory.length} Fatura</span>
                </div>
            )}
        </div>

        {/* --- CONTENT AREA --- */}

        {/* MESSAGES VIEW */}
        {activeTab === 'MESSAGES' && (
            <div className="flex-1 overflow-auto bg-slate-50 p-6">
                {user.role === 'admin' ? (
                    <div className="space-y-4">
                        {messages.map(msg => (
                            <div key={msg.id} className={`bg-white p-4 rounded-lg border shadow-sm cursor-pointer hover:shadow-md transition-all ${!msg.isRead ? 'border-l-4 border-l-blue-500' : 'border-slate-200'}`}>
                                <div className="flex justify-between items-start mb-2">
                                    <div className="flex items-center gap-2">
                                        <div className="font-bold text-slate-800">{msg.sender}</div>
                                        {!msg.isRead && <span className="bg-blue-100 text-blue-600 text-[10px] font-bold px-2 py-0.5 rounded">YENİ</span>}
                                    </div>
                                    <span className="text-xs text-slate-400">{msg.date}</span>
                                </div>
                                <div className="font-semibold text-sm text-slate-700 mb-1">{msg.subject}</div>
                                <p className="text-sm text-slate-500 line-clamp-2">{msg.preview}</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="flex flex-col h-full bg-white rounded-lg border border-slate-200 overflow-hidden">
                        <div className="bg-slate-100 p-4 border-b border-slate-200 flex items-center gap-2">
                            <div className="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center text-white font-bold">A</div>
                            <div>
                                <div className="font-bold text-sm text-slate-800">Admin Support</div>
                                <div className="text-xs text-green-600">● Çevrimiçi</div>
                            </div>
                        </div>
                        <div className="flex-1 p-4 overflow-y-auto space-y-4">
                            {userChatHistory.map((msg, idx) => (
                                <div key={idx} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`${msg.sender === 'user' ? 'bg-blue-600 text-white rounded-l-lg rounded-tr-lg' : 'bg-slate-100 text-slate-800 rounded-r-lg rounded-tl-lg'} p-3 max-w-[80%] text-sm`}>
                                        {msg.text}
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="p-4 border-t border-slate-200 bg-slate-50 flex gap-2">
                            <input 
                                type="text" 
                                placeholder="Mesajınızı yazın..." 
                                className="flex-1 border border-slate-300 rounded px-3 py-2 text-sm focus:outline-none focus:border-blue-500" 
                                value={messageInput}
                                onChange={(e) => setMessageInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                            />
                            <Button onClick={handleSendMessage}>Gönder</Button>
                        </div>
                    </div>
                )}
            </div>
        )}

        {/* DATABASE VIEW */}
        {activeTab === 'DATABASE' && (
           <>
             {/* Search & Filter Bar */}
             <div className="p-4 border-b border-slate-200 bg-slate-50">
                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                        <input 
                            type="text" 
                            className="w-full pl-10 pr-4 py-2.5 bg-slate-800 text-white placeholder-slate-400 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-slate-600"
                            placeholder={t.search_placeholder}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <Button variant="secondary" onClick={() => setShowFilters(!showFilters)}>
                        <FunnelIcon className="w-5 h-5 mr-2 inline" />
                        {t.btn_filter}
                    </Button>
                </div>
                {/* Filter Dropdown */}
                {showFilters && (
                    <div className="mt-3 p-3 bg-white border border-slate-200 rounded-md shadow-sm flex gap-3">
                        <select 
                            className="text-sm border-slate-300 rounded-md shadow-sm focus:border-blue-500 focus:ring-blue-500"
                            value={filterCategory}
                            onChange={(e) => setFilterCategory(e.target.value)}
                        >
                            <option value="">Tüm Kategoriler</option>
                            {uniqueCategories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                        <button onClick={() => setFilterCategory("")} className="text-xs text-red-500 hover:underline">{t.btn_clear}</button>
                    </div>
                )}
             </div>

             {/* Table */}
             <div className="flex-1 overflow-auto bg-white">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 sticky top-0 z-10">
                        <tr>
                            <th className="py-3 px-6 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-32">{t.col_code}</th>
                            <th className="py-3 px-6 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200">{t.col_desc}</th>
                            <th className="py-3 px-6 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-1/4">{t.col_category}</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {loading ? (
                            <tr><td colSpan={3} className="py-8 text-center text-slate-500">Yükleniyor...</td></tr>
                        ) : filteredAccounts.length === 0 ? (
                            <tr><td colSpan={3} className="py-8 text-center text-slate-400">Kayıt bulunamadı.</td></tr>
                        ) : (
                            filteredAccounts.map((acc) => (
                                <tr 
                                    key={acc.id} 
                                    onClick={() => setSelectedId(acc.id)}
                                    className={`cursor-pointer transition-colors hover:bg-slate-50 ${selectedId === acc.id ? 'bg-blue-50' : ''}`}
                                >
                                    <td className="py-3 px-6 text-sm font-semibold text-slate-900">{acc.code}</td>
                                    <td className="py-3 px-6 text-sm text-slate-600">{acc.description}</td>
                                    <td className="py-3 px-6 text-xs text-slate-500">{acc.category}</td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
             </div>
           </>
        )}

        {/* IMPORT VIEW */}
        {activeTab === 'IMPORT' && (
            <div className="flex-1 flex flex-col items-center justify-center p-8 bg-slate-50">
                <div className="bg-white p-12 rounded-2xl border border-dashed border-slate-300 flex flex-col items-center text-center max-w-lg w-full shadow-sm hover:border-blue-400 transition-colors">
                    <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mb-6">
                        {isAnalyzing ? <SparklesIcon className="w-8 h-8 animate-spin" /> : <DocumentArrowUpIcon className="w-8 h-8" />}
                    </div>
                    <h2 className="text-xl font-semibold text-slate-800 mb-2">{isAnalyzing ? "Analiz Ediliyor..." : t.import_title}</h2>
                    <p className="text-slate-500 mb-6">{t.import_desc}</p>
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleAutomaticFileUpload} accept="image/*,.pdf" />
                    <Button onClick={() => fileInputRef.current?.click()} disabled={isAnalyzing}>
                        Dosya Seç
                    </Button>
                </div>
            </div>
        )}

        {/* INVOICE HISTORY VIEW (MATCHING SCREENSHOT) */}
        {activeTab === 'HISTORY' && (
            <div className="flex-1 overflow-auto bg-slate-50 p-6">

                {/* List Header */}
                <div className="grid grid-cols-12 gap-4 px-4 py-2 text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                    <div className="col-span-5">FİRMA / SATICI</div>
                    <div className="col-span-4">TARİH / NO</div>
                    <div className="col-span-3 text-right">TUTAR</div>
                </div>

                <div className="space-y-3">
                    {invoiceHistory.map(inv => {
                        const isSelected = selectedInvoiceId === inv.id;
                        return (
                            <div 
                                key={inv.id} 
                                className={`bg-white rounded-lg border transition-all duration-200 overflow-hidden ${isSelected ? 'border-blue-500 ring-1 ring-blue-500 shadow-md' : 'border-slate-200 shadow-sm hover:border-blue-300'}`}
                            >
                                {/* Main Card Row */}
                                <div 
                                    onClick={() => handleInvoiceClick(inv)}
                                    className="grid grid-cols-12 gap-4 p-4 cursor-pointer items-center"
                                >
                                    {/* Column 1: Merchant */}
                                    <div className="col-span-5 flex items-center gap-3">
                                        <div className={`w-8 h-8 rounded-md flex items-center justify-center border ${isSelected ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-slate-50 border-slate-200 text-slate-500'}`}>
                                            <ReceiptPercentIcon className="w-5 h-5" />
                                        </div>
                                        <span className={`font-bold text-sm ${isSelected ? 'text-slate-900' : 'text-slate-700'}`}>
                                            {inv.merchantName}
                                        </span>
                                    </div>

                                    {/* Column 2: Date/No */}
                                    <div className="col-span-4 flex flex-col">
                                        <div className="flex items-center gap-1.5 text-slate-500 text-xs font-medium">
                                            <CalendarDaysIcon className="w-3.5 h-3.5" />
                                            {inv.date}
                                        </div>
                                        <div className="text-xs text-slate-400 mt-0.5">
                                            {inv.invoiceNumber}
                                        </div>
                                    </div>

                                    {/* Column 3: Amount */}
                                    <div className="col-span-3 flex items-center justify-end gap-3">
                                        <div className="text-right">
                                            <div className="font-bold text-slate-800 text-sm">{inv.totalAmount} {inv.currency}</div>
                                            <div className="text-[10px] text-slate-400 uppercase tracking-wide">TOPLAM</div>
                                        </div>
                                        {isSelected ? <ChevronUpIcon className="w-4 h-4 text-blue-500" /> : <ChevronDownIcon className="w-4 h-4 text-slate-300" />}
                                    </div>
                                </div>

                                {/* Expanded Content (Line Items) */}
                                {isSelected && (
                                    <div className="bg-slate-50 border-t border-slate-100 p-4 animate-fade-in">
                                        <div className="flex items-center gap-2 mb-3 text-xs font-bold text-slate-400 uppercase">
                                            <SparklesIcon className="w-4 h-4 text-blue-500" />
                                            KALEMLER (SATIRLAR)
                                        </div>

                                        {inv.items.length > 0 ? (
                                            <div className="space-y-2">
                                                {inv.items.map((item, idx) => (
                                                    <div key={idx} className="flex items-start gap-3 bg-white border border-slate-200 p-2.5 rounded hover:border-blue-300 transition-colors">
                                                        <div className="flex-shrink-0">
                                                            <span className="inline-block bg-blue-100 text-blue-700 text-xs font-bold px-2 py-0.5 rounded border border-blue-200">
                                                                {item.accountCode || '???'}
                                                            </span>
                                                        </div>
                                                        <div className="flex-1 min-w-0">
                                                            <p className="text-xs text-slate-700 font-medium truncate" title={item.description}>{item.description}</p>
                                                        </div>
                                                        <div className="text-xs font-bold text-slate-800 text-right w-20">
                                                            {item.total}
                                                        </div>
                                                    </div>
                                                ))}
                                                <div className="flex justify-end mt-2">
                                                    <button className="text-xs text-red-500 hover:underline flex items-center gap-1">
                                                        <TrashIcon className="w-3 h-3" /> Sil
                                                    </button>
                                                </div>
                                            </div>
                                        ) : (
                                            <div className="text-center py-4 text-slate-400 text-sm">
                                                Henüz kalem bilgisi ayrıştırılmadı.
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        )}

      </main>

      {/* 3. RIGHT PANEL (Details) */}
      <aside className="w-96 bg-white border-l border-slate-200 flex flex-col flex-shrink-0 z-10 shadow-[-4px_0_15px_-3px_rgba(0,0,0,0.05)]">

        {/* Database Details */}
        {activeTab === 'DATABASE' && (
            <>
                <div className="h-16 flex items-center px-6 border-b border-slate-200 flex-shrink-0">
                    <h2 className="font-semibold text-slate-800">{t.detail_header_account}</h2>
                </div>

                {selectedAccount ? (
                    <div className="flex-1 p-6 overflow-y-auto">
                      {/* Top Row: Code and Status */}
                      <div className="flex justify-between items-start mb-6">
                        <div className="text-3xl font-bold text-blue-600 tracking-tight">
                            {selectedAccount.code}
                        </div>
                        <span className="px-2 py-1 bg-green-100 text-green-700 text-[10px] font-bold uppercase rounded border border-green-200">
                            ● ACTIVE
                        </span>
                      </div>

                      {/* AI Analysis Box */}
                      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-6">
                          <div className="flex items-center gap-2 mb-2 text-yellow-700">
                              <SparklesIcon className="w-4 h-4" />
                              <span className="text-xs font-bold uppercase">Analiz & Gerekçe</span>
                          </div>
                          <div className="space-y-2">
                              {selectedAccount.ai_insight ? (
                                  <p className="text-xs text-yellow-800 leading-relaxed">{selectedAccount.ai_insight}</p>
                              ) : (
                                  // Skeleton for demo match
                                  <>
                                      <div className="h-2 bg-yellow-200/50 rounded w-3/4"></div>
                                      <div className="h-2 bg-yellow-200/50 rounded w-full"></div>
                                  </>
                              )}
                          </div>
                      </div>

                      {/* Description */}
                      <div className="mb-6">
                          <label className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase mb-1">
                              <TagIcon className="w-3 h-3" /> AÇIKLAMA
                          </label>
                          <div className="text-base font-medium text-slate-800 leading-snug">
                              {selectedAccount.description}
                          </div>
                      </div>

                      {/* Info Box */}
                      <div className="bg-slate-50 border border-slate-100 rounded-lg p-4 mb-6 space-y-4">
                          <div>
                              <label className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase mb-1">
                                  <FolderIcon className="w-3 h-3" /> KATEGORİ (SINIF)
                              </label>
                              <div className="text-sm font-medium text-slate-700">
                                  {selectedAccount.category || 'Genel'}
                              </div>
                          </div>
                          <div className="border-t border-slate-200 pt-3">
                              <label className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase mb-1">
                                   BILANZ POSTEN
                              </label>
                              <div className="text-sm font-medium text-slate-700">
                                  {selectedAccount.bilanzPosten || '-'}
                              </div>
                          </div>
                      </div>

                      {/* Edit Form Section */}
                      <div className="pt-2">
                          <div className="flex items-center gap-2 text-blue-600 mb-4">
                              <PencilSquareIcon className="w-4 h-4" />
                              <span className="text-sm font-bold">Edit</span>
                          </div>

                          <div className="space-y-4">
                              <div>
                                  <label className="block text-xs font-medium text-slate-600 mb-1">Programmverbindung</label>
                                  <input 
                                      type="text" 
                                      className="w-full bg-[#333] text-white text-sm px-3 py-2 rounded border border-slate-700 focus:outline-none focus:ring-1 focus:ring-blue-500"
                                      defaultValue={selectedAccount.programmverbindung || '-'} 
                                  />
                              </div>
                              <div>
                                  <label className="block text-xs font-medium text-slate-600 mb-1">Abschlusszweck</label>
                                  <select className="w-full bg-white text-slate-700 text-sm px-3 py-2 rounded border border-slate-300 focus:outline-none focus:ring-1 focus:ring-blue-500">
                                      <option>Select</option>
                                      <option>HGB</option>
                                      <option>IFRS</option>
                                      <option>Steuerbilanz</option>
                                  </select>
                              </div>

                              <button className="w-full bg-blue-600 text-white font-medium py-2 rounded hover:bg-blue-700 transition-colors mt-2">
                                  Kaydet
                              </button>
                          </div>
                      </div>
                    </div>
                ) : (
                    <div className="flex-1 p-8 flex flex-col items-center justify-center text-center text-slate-300">
                        <ArchiveBoxIcon className="w-16 h-16 mx-auto mb-4 opacity-50" />
                        <p>{t.detail_empty_select}</p>
                    </div>
                )}
            </>
        )}

        {/* Invoice Details/Image */}
        {(activeTab === 'HISTORY' || activeTab === 'IMPORT' || activeTab === 'MESSAGES') && (
            <>
                <div className="h-16 flex items-center justify-between px-6 border-b border-slate-200 flex-shrink-0 bg-white">
                    <h2 className="font-semibold text-slate-800">
                        {activeTab === 'MESSAGES' ? 'Detaylar' : 'Fatura Görseli'}
                    </h2>
                    {invoiceImage && activeTab !== 'MESSAGES' && <PrinterIcon className="w-5 h-5 text-slate-400 cursor-pointer hover:text-blue-600" />}
                </div>

                {activeTab === 'MESSAGES' ? (
                    <div className="flex-1 p-6 bg-slate-50 flex flex-col items-center justify-center text-center text-slate-400">
                        <ChatBubbleLeftRightIcon className="w-12 h-12 opacity-50 mb-2" />
                        <p className="text-sm">Bir mesaj seçiniz.</p>
                    </div>
                ) : (
                    <div className="flex-1 bg-slate-900 relative overflow-hidden flex items-center justify-center">
                        {invoiceImage ? (
                            invoiceImage.startsWith('data:application/pdf') ? (
                                <embed src={invoiceImage} type="application/pdf" className="w-full h-full" />
                            ) : (
                                <img src={invoiceImage} alt="Invoice" className="max-w-full max-h-full object-contain" />
                            )
                        ) : (
                            <div className="text-center text-slate-500 p-8">
                                <PhotoIcon className="w-12 h-12 mx-auto mb-2 opacity-50" />
                                <p className="text-sm">Görüntülenecek belge yok</p>
                            </div>
                        )}
                    </div>
                )}
            </>
        )}
      </aside>

    </div>
  );
}

