                            placeholder={t.search_placeholder}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <Button variant="secondary" onClick={() => setShowFilters(!showFilters)}>
                        <FunnelIcon className="w-5 h-5 mr-2 inline" />
