              setInvoiceHistory(prev => [newItem, ...prev]);
              setSelectedInvoiceId(newItem.id);
              setInvoiceImage(newItem.imageData || null);
              setActiveTab('HISTORY');
          }, 1500);
      }
  };

  const handleSendMessage = async () => {
    if (!messageInput.trim() || !user) return;

    // Do not set created_at or id here, let Supabase handle it for consistency
    const newMessagePayload = {
        sender: user.name,
        recipient: user.role === 'user' ? 'Admin Support' : 'User',
        content: messageInput,
        subject: 'Destek Talebi',
        is_read: false
    };

    // Clear input immediately
    setMessageInput("");

    // Optimistic Update (Temporary ID)
    const tempId = Date.now();
    setRawMessages(prev => [...prev, { ...newMessagePayload, id: tempId, created_at: new Date().toISOString() }]);

    try {
        const { data, error } = await supabase.from('messages').insert(newMessagePayload).select();

        if (error) {
            console.error('Error sending message (Supabase):', error);
            // Alert user but keep optimistic update? No, usually rollback.
            // But for this simplified demo, we just log.
            // Rollback optimistic update
            setRawMessages(prev => prev.filter(msg => msg.id !== tempId));
        } else if (data) {
             // Replace optimistic message with real one from DB to get correct ID
             setRawMessages(prev => prev.map(msg => msg.id === tempId ? data[0] : msg));
        }
    } catch (e) {
        console.error('Exception sending message:', e);
        // Rollback
        setRawMessages(prev => prev.filter(msg => msg.id !== tempId));
    }
  };

  const handleAdminReply = async () => {
      if (!adminMessageInput.trim() || !selectedThreadSender) return;

      const replyMessagePayload = {
          sender: 'Admin Support',
          recipient: selectedThreadSender,
          content: adminMessageInput,
          subject: 'Re: Destek',
          is_read: false
      };

      setAdminMessageInput("");

      // Optimistic Update
      const tempId = Date.now();
      setRawMessages(prev => [...prev, { ...replyMessagePayload, id: tempId, created_at: new Date().toISOString() }]);

      try {
          const { data, error } = await supabase.from('messages').insert(replyMessagePayload).select();

          if (error) {
              console.error('Error sending reply (Supabase):', error);
              setRawMessages(prev => prev.filter(msg => msg.id !== tempId));
          } else if (data) {
              setRawMessages(prev => prev.map(msg => msg.id === tempId ? data[0] : msg));
          }
      } catch (e) {
          console.error('Exception sending reply:', e);
          setRawMessages(prev => prev.filter(msg => msg.id !== tempId));
      }
  };

  // Helper: Copy Prompt
  const handleCopyPrompt = (text: string) => {
      navigator.clipboard.writeText(text);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
