                                            <div className="absolute top-2 right-2">
                                                <button 
                                                    onClick={() => handleCopyPrompt(getGeneratedPrompt(selectedThreadSender, selectedThreadMessages))}
                                                    className={`p-2 rounded-md transition-all ${isCopied ? 'bg-green-600 text-white' : 'bg-slate-700 text-slate-300 hover:bg-slate-600 hover:text-white'}`}
                                                    title="Kopyala"
                                                >
                                                    {isCopied ? <ClipboardDocumentCheckIcon className="w-4 h-4" /> : <ClipboardDocumentIcon className="w-4 h-4" />}
                                                </button>
                                            </div>
                                        </div>
                                        <div className="mt-2 text-right">
                                            {isCopied && <span className="text-xs text-green-600 font-bold animate-pulse">Kopyalandı!</span>}
                                        </div>
                                    </div>

                                    {/* Quick Reply (Optional - kept small at bottom) */}
                                    <div className="mt-8 border-t border-slate-200 pt-4 opacity-50 hover:opacity-100 transition-opacity">
                                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Hızlı Cevap (Manuel)</label>
                                        <div className="flex gap-2">
                                            <input 
                                                type="text" 
                                                placeholder="Kısa cevap yaz..." 
                                                className="flex-1 bg-white border border-slate-300 rounded px-2 py-1 text-xs focus:outline-none focus:border-blue-500"
                                                value={adminMessageInput}
                                                onChange={(e) => setAdminMessageInput(e.target.value)}
                                                onKeyDown={(e) => e.key === 'Enter' && handleAdminReply()}
                                            />
                                            <button onClick={handleAdminReply} className="bg-slate-200 text-slate-600 hover:bg-slate-300 px-2 rounded text-xs">OK</button>
                                        </div>
                                    </div>

                                </div>
                            </div>
                        ) : (
                             <div className="flex-1 p-6 bg-slate-50 flex flex-col items-center justify-center text-center text-slate-400">
                                <ChatBubbleLeftRightIcon className="w-12 h-12 opacity-50 mb-2" />
                                <p className="text-sm">Analiz için bir mesaj seçiniz.</p>
                            </div>
                        )
                    ) : (
                        <div className="flex-1 p-6 bg-slate-50 flex flex-col items-center justify-center text-center text-slate-400">
                            <ChatBubbleLeftRightIcon className="w-12 h-12 opacity-50 mb-2" />
                            <p className="text-sm">Detaylar için sol paneli kullanın.</p>
                        </div>
                    )
                ) : (
                    <div className="flex-1 bg-slate-900 relative overflow-hidden flex items-center justify-center">
                        {invoiceImage ? (
                            invoiceImage.startsWith('data:application/pdf') ? (
                                <embed src={invoiceImage} type="application/pdf" className="w-full h-full" />
                            ) : (
                                <img src={invoiceImage} alt="Invoice" className="max-w-full max-h-full object-contain" />
                            )
                        ) : (
                            <div className="text-center text-slate-500 p-8">
                                <PhotoIcon className="w-12 h-12 mx-auto mb-2 opacity-50" />
                                <p className="text-sm">Görüntülenecek belge yok</p>
                            </div>
                        )}
                    </div>
                )}
            </>
        )}
      </aside>

    </div>
  );
}

