        {/* Invoice Details/Image/Messaging Details */}
        {(activeTab === 'HISTORY' || activeTab === 'IMPORT' || activeTab === 'MESSAGES') && (
            <>
                <div className="h-16 flex items-center justify-between px-6 border-b border-slate-200 flex-shrink-0 bg-white">
                    <h2 className="font-semibold text-slate-800">
                        {activeTab === 'MESSAGES' ? (selectedThreadSender ? 'Mesaj Analizi' : 'Mesaj Detayı') : 'Fatura Görseli'}
                    </h2>
                    {invoiceImage && activeTab !== 'MESSAGES' && <PrinterIcon className="w-5 h-5 text-slate-400 cursor-pointer hover:text-blue-600" />}
                </div>

                {activeTab === 'MESSAGES' ? (
                    user?.role === 'admin' ? (
                        selectedThreadSender ? (
                            <div className="flex flex-col h-full bg-white overflow-hidden">
                                <div className="flex-1 p-6 bg-slate-50 overflow-y-auto">

                                    {/* User Message Display */}
                                    <div className="mb-6">
                                        <div className="flex items-center gap-2 mb-2">
                                            <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center">
                                                <BuildingOfficeIcon className="w-3 h-3 text-slate-500" />
                                            </div>
                                            <span className="text-xs font-bold text-slate-500 uppercase">KULLANICI MESAJI</span>
                                        </div>
                                        <div className="bg-white border border-slate-200 rounded-lg p-3 text-sm text-slate-800 shadow-sm">
                                            {[...selectedThreadMessages].reverse().find(m => m.sender !== 'Admin Support')?.content || "İçerik yok."}
                                        </div>
                                    </div>

                                    {/* Generated Prompt Box */}
                                    <div>
                                        <div className="flex items-center gap-2 mb-2 text-blue-600">
