                                                value={adminMessageInput}
                                                onChange={(e) => setAdminMessageInput(e.target.value)}
                                                onKeyDown={(e) => e.key === 'Enter' && handleAdminReply()}
                                            />
                                            <button onClick={handleAdminReply} className="bg-slate-200 text-slate-600 hover:bg-slate-300 px-2 rounded text-xs">OK</button>
