        if(error) throw error;
        setTimeLogs(prev => prev.map(log => log.id === logId ? { ...log, status: newStatus } : log));
    } catch (err: any) {
        // Fallback for status change
        setTimeLogs(prev => prev.map(log => log.id === logId ? { ...log, status: newStatus } : log));
    }
  };

