      } else {
          setDashboardEmployees(MOCK_EMPLOYEES.filter(e => e.role !== Role.ADMIN));
      }

      checkTransfers();

      // 3. Fetch Recent Transfers (ONLY ACTIVE/FUTURE)
      const today = new Date().toISOString().split('T')[0];

      const { data: transferData } = await supabase
          .from('calendar_events')
          .select('*')
          .eq('type', 'Şube Transferi')
          .gte('end_date', today) // Sadece bitiş tarihi bugün veya ileride olanları çek (Görünmezlik mantığı)
          .order('date', { ascending: true }) // En yakını önce göster
