  const getTypeColor = (type: string, isTask?: boolean) => {
      if (isTask) {
          // Görevler için özel renk (Mor/Mavi karışımı - Dikkat çekici)
          return 'bg-gradient-to-r from-blue-900/60 to-indigo-900/60 border-indigo-500/40 text-blue-100 hover:brightness-125';
      }

      switch(type) {
          case 'Toplantı': return 'bg-indigo-900/40 border-indigo-500/30 text-indigo-200 hover:bg-indigo-900/60';
          case 'Montaj': return 'bg-amber-900/40 border-amber-500/30 text-amber-200 hover:bg-amber-900/60';
          case 'Teslim Tarihi': return 'bg-red-900/40 border-red-500/30 text-red-200 hover:bg-red-900/60';
          case 'Şube Transferi': return 'bg-gradient-to-r from-orange-600/80 to-red-600/80 text-white border-orange-500/50 shadow-[0_0_10px_rgba(234,88,12,0.3)] animate-pulse';
          default: return 'bg-zinc-800 border-zinc-700 text-zinc-300 hover:bg-zinc-700';
      }
