                                        const emp = MOCK_EMPLOYEES.find(e => e.id === empId);
                                        return emp ? (
                                            <div key={empId} className="flex items-center gap-3 p-2 rounded-lg hover:bg-zinc-900/50 transition-colors border border-transparent hover:border-zinc-800">
                                                <img src={emp.avatarUrl} alt={emp.name} className="w-8 h-8 rounded-full border border-zinc-800" />
                                                <div>
                                                    <p className="text-sm font-medium text-zinc-200">{emp.name}</p>
                                                    <p className="text-[10px] text-zinc-500">{emp.branch} • {emp.role}</p>
                                                </div>
                                            </div>
                                        ) : null;
                                    })
                                ) : (
                                    <p className="text-sm text-zinc-600 italic">--</p>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Footer Actions */}
                    <div className="p-4 border-t border-zinc-800 bg-zinc-900/20 pb-safe">
                        {selectedEvent.isTask ? (
                            <div className="text-center text-xs text-zinc-500">
                                {language === 'de' ? 'Aufgaben können hier nicht gelöscht werden.' : 'Görevler takvimden silinemez.'}
                            </div>
                        ) : (
                            <button 
                                onClick={handleDeleteEvent}
                                className="w-full flex items-center justify-center gap-2 py-3 border border-red-900/30 text-red-400 hover:bg-red-900/10 rounded-xl text-sm font-medium transition-colors"
                            >
                                <Trash2 size={16} /> {t('cal.deleteEvent')}
                            </button>
                        )}
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

