                  <button onClick={() => navigateTo('calendar')} className="mt-4 w-full py-2 text-xs font-medium text-zinc-500 hover:text-white hover:bg-zinc-800/50 rounded-lg transition-colors border border-dashed border-zinc-800">
                      {t('dash.viewAll')}
