                    <div className="flex items-center bg-zinc-900 rounded-lg border border-zinc-800">
                        <button onClick={() => changeWeek('prev')} className="p-2 hover:bg-zinc-800 text-zinc-400 hover:text-white transition-colors rounded-l-lg"><ChevronLeft size={18}/></button>
                        <div className="w-px h-6 bg-zinc-800"></div>
                        <button onClick={() => changeWeek('next')} className="p-2 hover:bg-zinc-800 text-zinc-400 hover:text-white transition-colors rounded-r-lg"><ChevronRight size={18}/></button>
                    </div>
                    <div>
                        <h2 className="text-lg font-bold text-white flex items-center gap-2">
                            <CalendarRange size={18} className="text-indigo-500"/>
                            {formatDate(weekDays[0], {day: 'numeric', month: 'short'})} - {formatDate(weekDays[6], {day: 'numeric', month: 'short', year: 'numeric'})}
                        </h2>
                    </div>
                </div>

                {/* Mobile Add Button */}
                <button 
                    onClick={() => { setNewEventForm(p => ({...p, date: new Date().toISOString().split('T')[0]})); setShowAddModal(true); }}
                    className="md:hidden w-8 h-8 flex items-center justify-center bg-indigo-600 rounded-lg text-white shadow-lg"
                >
                    <Plus size={18} />
                </button>
            </div>

            {/* HYBRID LAYOUT: VERTICAL LIST (MOBILE) / SWIMLANE (DESKTOP) */}
