const ShiftSchedule: React.FC = () => {
  const { t } = useLanguage();

  // State
  const [activeBranch, setActiveBranch] = useState<Branch>(Branch.MULHEIM);
  const [scheduleData, setScheduleData] = useState<Record<string, ShiftRow[]>>({
      [Branch.MULHEIM]: INITIAL_DATA
  });

  // Current active rows based on branch
  const currentRows = scheduleData[activeBranch] || [];

  // Handlers
  const handleAddRow = () => {
      const newRow: ShiftRow = {
          id: `row-${Date.now()}`,
          time: '',
          days: Array(7).fill('')
      };

      setScheduleData(prev => ({
          ...prev,
          [activeBranch]: [...(prev[activeBranch] || []), newRow]
      }));
  };

  const handleUpdateCell = (rowId: string, dayIndex: number | 'time', value: string) => {
      setScheduleData(prev => ({
          ...prev,
          [activeBranch]: prev[activeBranch].map(row => {
              if (row.id !== rowId) return row;

              if (dayIndex === 'time') {
                  return { ...row, time: value };
              } else {
                  const newDays = [...row.days];
                  newDays[dayIndex as number] = value;
                  return { ...row, days: newDays };
              }
          })
      }));
  };

  const handleRemoveRow = (rowId: string) => {
      if(!confirm('Bu satırı silmek istediğinize emin misiniz?')) return;
      setScheduleData(prev => ({
          ...prev,
          [activeBranch]: prev[activeBranch].filter(row => row.id !== rowId)
      }));
  };

  return (
    <div className="h-full w-full flex flex-col bg-[#09090b] relative overflow-hidden">

      {/* --- HEADER & CONTROLS --- */}
      <div className="p-6 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-md sticky top-0 z-20 shrink-0">
          <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">

              {/* BRANCH TABS */}
              <div className="flex items-center gap-2 overflow-x-auto max-w-full pb-2 xl:pb-0 custom-scrollbar">
                  {Object.values(Branch).map(branch => (
                      <button
                          key={branch}
                          onClick={() => setActiveBranch(branch)}
