                                                    {branchEmployees.map(emp => (
                                                        <option key={emp.id} value={emp.id} className="bg-zinc-900 text-white">
                                                            {emp.name}
                                                        </option>
                                                    ))}
                                                </select>
                                                {/* Dropdown arrow hider hack or custom overlay could go here */}
                                            </div>
                                        </td>
                                    ))}

                                    {/* Delete Row Action */}
                                    <td className="p-2 text-center">
                                        <button 
                                            onClick={() => row.id && deleteRow(row.id)}
                                            className="text-zinc-600 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                                        >
                                            <Trash2 size={16} />
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Quick Status Bar */}
            <div className="mt-4 flex items-center justify-end px-2 text-xs text-zinc-500">
                <span className="flex items-center gap-1"><Clock size={12}/> Otomatik Kayıt Aktif</span>
            </div>
        </div>
      </div>
    </div>
  );
};

