import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../lib/i18n';
import { Branch, Employee, Role } from '../types';
import { Save, Clock, ChevronLeft, ChevronRight, Copy, Plus, Trash2, User, Loader2, Lock, ArrowRightLeft } from 'lucide-react';
import { supabase } from '../lib/supabase';

const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];

interface RosterRow {
    id?: string;
    timeLabel: string; // Örn: "09:00 - 17:00"
    assignments: string[]; // 7 günlük personel ID'leri
}

interface ShiftScheduleProps {
    currentUser: Employee;
}

const getMonday = (d: Date) => {
  const date = new Date(d);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
  return new Date(date.setDate(diff));
};

const ShiftSchedule: React.FC<ShiftScheduleProps> = ({ currentUser }) => {
  const { t, formatDate } = useLanguage();
  const isAdmin = currentUser.role === Role.ADMIN;

  // State
  // Personel ise kendi şubesini zorunlu kılıyoruz, Admin ise Mulheim varsayılan
  const [activeBranch, setActiveBranch] = useState<Branch>(isAdmin ? Branch.MULHEIM : currentUser.branch);

  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getMonday(new Date()));
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data States
  const [rosterData, setRosterData] = useState<RosterRow[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);
  const [transferredEmpIds, setTransferredEmpIds] = useState<string[]>([]); // O hafta transfer olanların ID'si

  const weekKey = `${currentWeekStart.getFullYear()}-${String(currentWeekStart.getMonth() + 1).padStart(2, '0')}-${String(currentWeekStart.getDate()).padStart(2, '0')}`;
  const currentWeekEnd = new Date(currentWeekStart);
  currentWeekEnd.setDate(currentWeekEnd.getDate() + 6);

  // Personel şube değiştiremesin diye zorla
  useEffect(() => {
      if (!isAdmin) {
          setActiveBranch(currentUser.branch);
      }
  }, [currentUser, isAdmin]);

  // Şube veya Hafta değişince verileri çek
  useEffect(() => {
      fetchWeekData();
      fetchEmployeesAndTransfers(); // Personel ve Transfer verilerini çek

      const channel = supabase.channel('shift-realtime')
          .on('postgres_changes', { event: '*', schema: 'public', table: 'shift_schedules' }, (payload) => {
                  const newData = payload.new as any;
                  if ((newData && newData.branch === activeBranch && newData.week_start_date === weekKey) || payload.eventType === 'DELETE') {
                      if (!debounceTimeout.current) fetchWeekData();
                  }
              }
          )
          .subscribe();

      return () => { supabase.removeChannel(channel); };
  }, [currentWeekStart, activeBranch, weekKey]);

  // 1. Personel Listesini ve Transfer Durumlarını Çek
  const fetchEmployeesAndTransfers = async () => {
      try {
          // A. Tüm personelleri çek (Canlı veritabanından)
          const { data: empData } = await supabase.from('profiles').select('*');

          if (empData) {
              // Frontend formatına çevir
              const formattedEmps: Employee[] = empData.map((e: any) => ({
                  id: e.id,
                  name: e.full_name,
                  email: e.email,
                  role: e.role,
                  branch: e.branch,
                  hourlyRate: e.hourly_rate,
                  taxClass: e.tax_class,
                  avatarUrl: e.avatar_url,
                  advances: 0,
                  metrics: e.metrics
              }));

              // Sadece seçili şubedeki personelleri filtrele
              // Transfer olan personelin DB'deki branch değeri zaten güncellendiği için burada otomatik çıkar.
              const branchEmps = formattedEmps.filter(e => e.branch === activeBranch);
              setAvailableEmployees(branchEmps);
          }

          // B. Bu hafta için "Şube Transferi" olaylarını kontrol et
          const startStr = currentWeekStart.toISOString().split('T')[0];
          const endStr = currentWeekEnd.toISOString().split('T')[0];

          const { data: transferData } = await supabase
              .from('calendar_events')
              .select('attendees')
              .eq('type', 'Şube Transferi')
              .lte('date', endStr)      // Etkinlik başlangıcı hafta bitişinden önce
              .gte('end_date', startStr); // Etkinlik bitişi hafta başlangıcından sonra

          if (transferData) {
              // Transfer olanların ID listesini oluştur
              const ids = transferData.flatMap((t: any) => t.attendees || []);
              setTransferredEmpIds(ids);
          } else {
              setTransferredEmpIds([]);
          }

      } catch (err) {
          console.error("Personel verisi hatası:", err);
      }
  };

  const fetchWeekData = async () => {
      if (!debounceTimeout.current) setIsLoading(true);

      try {
          const { data, error } = await supabase
              .from('shift_schedules')
              .select('*')
              .eq('week_start_date', weekKey)
              .eq('branch', activeBranch)
              .order('created_at', { ascending: true });

          if (error) throw error;

          if (data && data.length > 0) {
              const rows: RosterRow[] = data.map((r: any) => ({
                  id: r.id,
                  timeLabel: r.time_slot || '',
                  assignments: r.days || Array(7).fill('')
              }));
              setRosterData(rows);
          } else {
              setRosterData([]);
          }

      } catch (err: any) {
          console.error("Vardiya verisi çekilemedi:", err);
      } finally {
          setIsLoading(false);
      }
  };

  const handleWeekChange = (direction: 'prev' | 'next') => {
      const newDate = new Date(currentWeekStart);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setCurrentWeekStart(newDate);
  };

  const debounceTimeout = useRef<any>(null);

  const saveRowToDb = async (row: RosterRow) => {
      if (!isAdmin) return; // Güvenlik kontrolü
      setIsSaving(true);
      try {
          const payload = {
              week_start_date: weekKey,
              branch: String(activeBranch),
              time_slot: row.timeLabel,
              days: row.assignments
          };

          if (row.id && !row.id.startsWith('temp_')) {
              await supabase.from('shift_schedules').update(payload).eq('id', row.id);
          } else {
              const { data, error } = await supabase.from('shift_schedules').insert([payload]).select().single();
              if(!error && data) {
                  setRosterData(prev => prev.map(r => r.id === row.id ? { ...r, id: data.id } : r));
              }
          }
      } catch (err) {
          console.error("Otomatik kayıt hatası:", err);
      } finally {
          setIsSaving(false);
      }
  };

  const handleManualSave = async () => {
      if (!isAdmin) return;
      setIsSaving(true);
      try {
          const promises = rosterData.map(row => saveRowToDb(row));
          await Promise.all(promises);
          alert("Tüm veriler başarıyla kaydedildi ve yayınlandı.");
      } catch (err) {
          console.error(err);
          alert("Kayıt sırasında bir hata oluştu.");
      } finally {
          setIsSaving(false);
      }
  };

  const handleAssignmentChange = (rowId: string | undefined, dayIndex: number, employeeId: string) => {
      if (!isAdmin) return;
      const updatedRows = rosterData.map(row => {
          if (row.id !== rowId) return row;
          const newAssignments = [...row.assignments];
          newAssignments[dayIndex] = employeeId;
          return { ...row, assignments: newAssignments };
      });
      setRosterData(updatedRows);

      const rowToSave = updatedRows.find(r => r.id === rowId);
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
          debounceTimeout.current = setTimeout(() => {
              saveRowToDb(rowToSave);
          }, 800); 
      }
  };

  const handleTimeLabelChange = (rowId: string | undefined, newLabel: string) => {
      if (!isAdmin) return;
      const updatedRows = rosterData.map(row => {
          if (row.id !== rowId) return row;
          return { ...row, timeLabel: newLabel };
      });
      setRosterData(updatedRows);

      const rowToSave = updatedRows.find(r => r.id === rowId);
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
          debounceTimeout.current = setTimeout(() => {
              saveRowToDb(rowToSave);
          }, 1000); 
      }
  };

  const addNewRow = async () => {
      if (!isAdmin) return;
      const newRow: RosterRow = {
          id: `temp_${Date.now()}`,
          timeLabel: '', 
          assignments: Array(7).fill('')
      };
      setRosterData([...rosterData, newRow]);
      await saveRowToDb(newRow);
  };

  const deleteRow = async (rowId: string) => {
      if (!isAdmin) return;
      if(!confirm("Bu satırı silmek istediğinize emin misiniz?")) return;

      setRosterData(prev => prev.filter(r => r.id !== rowId));

      if (rowId && !rowId.startsWith('temp_')) {
          await supabase.from('shift_schedules').delete().eq('id', rowId);
      }
  };

  const handleCopyNextWeek = async () => {
      if (!isAdmin) return;
      if (rosterData.length === 0) return alert("Kopyalanacak veri yok.");

      const nextWeekDate = new Date(currentWeekStart);
      nextWeekDate.setDate(nextWeekDate.getDate() + 7);
      const nextWeekKey = `${nextWeekDate.getFullYear()}-${String(nextWeekDate.getMonth() + 1).padStart(2, '0')}-${String(nextWeekDate.getDate()).padStart(2, '0')}`;

      // Onay mesajı
      if (confirm(`${activeBranch} şubesi için bu planı ${formatDate(nextWeekDate)} haftasına kopyalamak istiyor musunuz? (Hedef haftadaki eski veriler temizlenecektir)`)) {
          setIsLoading(true);
          try {
              // 1. ADIM: Hedef haftadaki, bu şubeye ait eski verileri sil (Temiz Kopya)
              const { error: deleteError } = await supabase
                  .from('shift_schedules')
                  .delete()
                  .eq('week_start_date', nextWeekKey)
                  .eq('branch', String(activeBranch));

              if (deleteError) throw deleteError;

              // 2. ADIM: Mevcut veriyi yeni tarihe uyarla
              const payload = rosterData.map(row => ({
                  week_start_date: nextWeekKey,
                  branch: String(activeBranch),
                  time_slot: row.timeLabel,
                  days: row.assignments
              }));

              // 3. ADIM: Veriyi ekle
              if(payload.length > 0) {
                  const { error } = await supabase.from('shift_schedules').insert(payload);
                  if (error) throw error;

                  alert("Başarıyla kopyalandı.");
                  // Kullanıcıyı yeni haftaya götür
                  setCurrentWeekStart(nextWeekDate);
              }
          } catch (err: any) {
              console.error(err);
              alert(`Hata: ${err.message}`);
          } finally {
              setIsLoading(false);
          }
      }
  };

  // --- FILTRELEME MANTIĞI ---
  // Admin: Hepsini görür.
  // Personel: Sadece 'days' array'inde kendi ID'sinin olduğu satırları görür.
  const displayedRows = isAdmin 
      ? rosterData 
      : rosterData.filter(row => row.assignments.includes(currentUser.id));

  // Helper to find employee name by ID (Available listesinden)
  const getEmployeeName = (id: string) => {
      const emp = availableEmployees.find(e => e.id === id);
      return emp ? emp.name : '-';
  }

  return (
    <div className="h-full w-full flex flex-col bg-[#09090b] relative overflow-hidden">

      {/* HEADER CONTROLS */}
      <div className="p-4 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-md sticky top-0 z-30 shrink-0">
          <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">

              {/* Branch Selector (Sadece Admin Görebilir) */}
              <div className="flex items-center gap-2 overflow-x-auto max-w-full pb-1 xl:pb-0 custom-scrollbar">
                  {isAdmin ? (
                      Object.values(Branch).map(branch => (
                          <button
                              key={branch}
                              onClick={() => setActiveBranch(branch)}
                              className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all whitespace-nowrap border ${
                                  activeBranch === branch 
                                  ? 'bg-zinc-100 text-black border-white shadow-[0_0_15px_rgba(255,255,255,0.2)]' 
                                  : 'bg-zinc-900 text-zinc-500 border-zinc-800 hover:text-zinc-300 hover:border-zinc-700'
                              }`}
                          >
                              {branch}
                          </button>
                      ))
                  ) : (
                      // Personel için sadece aktif şube adı (Transfer olmuşsa yeni şube görünür)
                      <div className="flex items-center gap-2 px-4 py-2 bg-zinc-900 border border-zinc-800 rounded-xl">
                          <span className="text-sm font-bold text-white">{activeBranch}</span>
                          <span className="text-xs text-zinc-500">(Aktif Şubeniz)</span>
                      </div>
                  )}
              </div>

              {/* Actions */}
              <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto justify-between xl:justify-end">

                  {/* Week Nav */}
                  <div className="flex items-center bg-zinc-900 rounded-xl border border-zinc-800 p-1 shadow-sm">
                        <button onClick={() => handleWeekChange('prev')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronLeft size={20}/></button>
                        <div className="px-4 text-center min-w-[140px]">
                            <span className="block text-[10px] text-zinc-500 uppercase font-bold tracking-wider">Hafta</span>
                            <span className="block text-sm font-bold text-white whitespace-nowrap">
                                {formatDate(currentWeekStart, { day: 'numeric', month: 'short' })} - {formatDate(currentWeekEnd, { day: 'numeric', month: 'short' })}
                            </span>
                        </div>
                        <button onClick={() => handleWeekChange('next')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronRight size={20}/></button>
                  </div>

                  {/* ADMIN ONLY ACTIONS */}
                  {isAdmin && (
                      <div className="flex items-center gap-3 w-full md:w-auto">
                            <button onClick={handleCopyNextWeek} title="Kopyala" className="flex items-center gap-2 px-4 py-3 bg-zinc-900 hover:bg-zinc-800 text-zinc-400 hover:text-white rounded-xl font-bold transition-all border border-zinc-800">
                                <Copy size={18} />
                                <span className="hidden md:inline">Kopyala</span>
                            </button>

                            <button 
                                onClick={handleManualSave}
                                disabled={isSaving}
                                className="flex items-center justify-center gap-2 px-6 py-3 bg-green-600 hover:bg-green-500 text-white rounded-xl font-bold transition-all border border-green-500 shadow-lg shadow-green-900/20 active:scale-95 min-w-[120px]"
                            >
                                {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                                <span>Kaydet</span>
                            </button>

                            <button 
                                onClick={addNewRow}
                                className="flex items-center justify-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold transition-all border border-indigo-500 shadow-lg shadow-indigo-900/20 active:scale-95 min-w-[120px]"
                            >
                                <Plus size={18} />
                                <span>Saat Ekle</span>
                            </button>
                      </div>
                  )}
              </div>
          </div>
      </div>

      {/* ROSTER TABLE */}
      <div className="flex-1 overflow-auto custom-scrollbar bg-zinc-950 p-0 md:p-4">
        <div className="min-w-[1200px] h-full pb-20"> 
            <div className="rounded-xl border border-zinc-800 bg-zinc-900 overflow-hidden shadow-2xl relative">

                {isLoading && (
                    <div className="absolute inset-0 z-50 bg-zinc-950/80 backdrop-blur-sm flex items-center justify-center">
                        <Loader2 size={40} className="text-blue-500 animate-spin" />
                    </div>
                )}

                <table className="w-full border-collapse table-fixed">
                    <thead>
                        <tr>
                            {/* Time Slot Header - Purple */}
                            <th className="w-32 p-4 bg-indigo-900/20 text-center text-indigo-300 font-bold text-sm border-b border-r border-zinc-800 sticky left-0 z-20 shadow-[4px_0_10px_rgba(0,0,0,0.3)] uppercase tracking-wider">
                                <div className="flex items-center justify-center gap-2">
                                    <Clock size={16} /> Uhrzeit
                                </div>
                            </th>

                            {/* Days Headers - Red */}
                            {DAYS.map((day, idx) => {
                                const d = new Date(currentWeekStart);
                                d.setDate(d.getDate() + idx);
                                const isToday = new Date().toDateString() === d.toDateString();

                                return (
                                    <th key={day} className={`p-4 text-center border-b border-r border-zinc-800/50 last:border-r-0 ${isToday ? 'bg-red-900/40 text-red-200' : 'bg-red-900/10 text-red-400'}`}>
                                        <div className="flex flex-col items-center">
                                            <span className="text-xs font-bold uppercase tracking-wider mb-1">{day}</span>
                                        </div>
                                    </th>
                                );
                            })}

                            {/* Action Header (Sadece Admin) */}
                            {isAdmin && <th className="w-16 bg-zinc-900 border-b border-zinc-800"></th>}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-800/50">
                        {displayedRows.length === 0 ? (
                            <tr>
                                <td colSpan={isAdmin ? 9 : 8} className="p-12 text-center text-zinc-500 italic bg-zinc-950">
                                    {isAdmin 
                                        ? 'Henüz vardiya saati eklenmemiş. "+ Saat Ekle" butonunu kullanın.' 
                                        : 'Bu hafta için atanmış vardiyanız bulunmamaktadır.'}
                                </td>
                            </tr>
                        ) : (
                            displayedRows.map((row) => (
                                <tr key={row.id} className="group hover:bg-zinc-800/30 transition-colors">

                                    {/* Time Label (Admin: Input, Staff: Text) */}
                                    <td className="p-2 bg-zinc-950 border-r border-zinc-800 sticky left-0 z-10 shadow-[4px_0_10px_rgba(0,0,0,0.3)]">
                                        {isAdmin ? (
                                            <input
                                                type="text"
                                                value={row.timeLabel}
                                                onChange={(e) => handleTimeLabelChange(row.id, e.target.value)}
                                                className="w-full bg-transparent text-center font-bold text-zinc-300 focus:text-white outline-none placeholder:text-zinc-700"
                                                placeholder="00-00"
                                            />
                                        ) : (
                                            <div className="text-center font-bold text-white">{row.timeLabel}</div>
                                        )}
                                    </td>

                                    {/* Employee Selectors */}
                                    {row.assignments.map((empId, dayIdx) => (
                                        <td key={dayIdx} className="p-2 border-r border-zinc-800/30 last:border-r-0 relative">
                                            <div className="relative flex justify-center items-center h-10">
                                                {isAdmin ? (
                                                    <select
                                                        value={empId}
                                                        onChange={(e) => handleAssignmentChange(row.id, dayIdx, e.target.value)}
                                                        className={`w-full bg-transparent appearance-none outline-none text-sm text-center cursor-pointer transition-colors ${
                                                            empId ? 'text-white font-medium' : 'text-zinc-600'
                                                        } ${transferredEmpIds.includes(empId) ? 'font-bold text-orange-400' : ''}`}
                                                    >
                                                        <option value="" className="bg-zinc-900 text-zinc-500">-</option>
                                                        {availableEmployees.map(emp => {
                                                            const isTransferred = transferredEmpIds.includes(emp.id);
                                                            return (
                                                                <option 
                                                                    key={emp.id} 
                                                                    value={emp.id} 
                                                                    className={`bg-zinc-900 ${isTransferred ? 'text-orange-400 font-bold' : 'text-white'}`}
                                                                >
                                                                    {emp.name} {isTransferred ? '(T)' : ''}
                                                                </option>
                                                            );
                                                        })}
                                                    </select>
                                                ) : (
                                                    // Personel Görünümü (Salt Okunur)
                                                    // Sadece KENDİ adını görür, başkası varsa "-" görür.
                                                    <span className={`text-sm ${empId === currentUser.id ? 'text-green-400 font-bold' : 'text-zinc-700'}`}>
                                                        {empId === currentUser.id ? currentUser.name : '-'}
                                                    </span>
                                                )}

                                                {/* Admin için Transfer İkonu (Görsel İpucu) */}
                                                {isAdmin && empId && transferredEmpIds.includes(empId) && (
                                                    <ArrowRightLeft size={12} className="absolute right-1 text-orange-500 pointer-events-none" />
                                                )}
                                            </div>
                                        </td>
                                    ))}

                                    {/* Delete Row Action (Sadece Admin) */}
                                    {isAdmin && (
                                        <td className="p-2 text-center">
                                            <button 
                                                onClick={() => row.id && deleteRow(row.id)}
                                                className="text-zinc-600 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </td>
                                    )}
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Quick Status Bar */}
            <div className="mt-4 flex items-center justify-end px-2 text-xs text-zinc-500 gap-4">
                {isAdmin && <span className="flex items-center gap-1 text-orange-400 font-bold"><ArrowRightLeft size={12}/> (T) Transfer Personel</span>}
                {!isAdmin && <span className="flex items-center gap-1 text-zinc-400"><Lock size={12}/> Salt Okunur Mod</span>}
                <span className="flex items-center gap-1"><Clock size={12}/> {isAdmin ? 'Otomatik Kayıt Aktif' : 'Canlı Veri'}</span>
            </div>
        </div>
      </div>
    </div>
  );
};

export default ShiftSchedule;

