-- Storage Politikalarını Temizle (Yeniden oluşturmak için)
DO $$
BEGIN
    DROP POLICY IF EXISTS "Public Read Access" ON storage.objects;
    DROP POLICY IF EXISTS "Authenticated Insert Access" ON storage.objects;
    DROP POLICY IF EXISTS "Authenticated Update Access" ON storage.objects;
    DROP POLICY IF EXISTS "Authenticated Delete Access" ON storage.objects;
END $$;

-- POLICY 1: Herkes (Giriş yapmamışlar dahil) dosyaları görebilir (Logo vb. için şart)
CREATE POLICY "Public Read Access"
ON storage.objects FOR SELECT
USING ( bucket_id = 'app-assets' );

-- POLICY 2: Sadece giriş yapmış kullanıcılar (Authenticated) dosya yükleyebilir
CREATE POLICY "Authenticated Insert Access"
ON storage.objects FOR INSERT
WITH CHECK ( bucket_id = 'app-assets' AND auth.role() = 'authenticated' );

-- POLICY 3: Sadece giriş yapmış kullanıcılar dosyaları güncelleyebilir
CREATE POLICY "Authenticated Update Access"
ON storage.objects FOR UPDATE
USING ( bucket_id = 'app-assets' AND auth.role() = 'authenticated' );

-- POLICY 4: Sadece giriş yapmış kullanıcılar silebilir
CREATE POLICY "Authenticated Delete Access"
ON storage.objects FOR DELETE
USING ( bucket_id = 'app-assets' AND auth.role() = 'authenticated' );


-- =========================================================
-- 5. REALTIME (GÜVENLİ VE KAPSAMLI EKLEME)
-- =========================================================
-- Bu blok, uygulamanın canlı çalışması gereken tüm tablolarını yayına açar.
DO $$
DECLARE
    -- Realtime'a eklenecek tabloların listesi (app_settings eklendi)
    tables text[] := ARRAY['profiles', 'time_logs', 'tasks', 'messages', 'calendar_events', 'shift_schedules', 'app_settings'];
    tbl text;
BEGIN
    FOR tbl IN SELECT unnest(tables) LOOP
        -- Tablo zaten yayında mı kontrol et
        IF NOT EXISTS (
            SELECT 1
            FROM pg_publication_tables
            WHERE pubname = 'supabase_realtime'
            AND schemaname = 'public'
            AND tablename = tbl
        ) THEN
            -- Değilse ekle
            EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', tbl);
        END IF;
    END LOOP;
END $$;

