        MOCK_EMPLOYEES.find(e => e.branch === Branch.RINGE), // Ringe
        MOCK_EMPLOYEES.find(e => e.branch === Branch.MULHEIM), // Mülheim
        MOCK_EMPLOYEES.find(e => e.branch === Branch.TOBACGO), // Tobacgo
    ].filter(Boolean) as Employee[];

    const handleQuickLogin = (user: Employee) => {
        // Hızlı giriş için direkt onLogin çağır (Mock veri kullanır)
        // Normalde form doldurup submit yapmak daha doğru ama bu bir "Quick Access"
        onLogin(user);
    };

    return (
        <div className="min-h-screen w-full flex items-center justify-center bg-zinc-950 relative overflow-hidden overflow-y-auto">
