          { name: t('tasks.statusDone'), value: myTotalTasks.filter(t => t.status === 'done').length, color: STATUS_COLORS.done },
      ].filter(item => item.value > 0);
  }, [myTotalTasks, t]);

  // 3. Staff: Priority Breakdown (Bar Chart)
  const taskPriorityData = useMemo(() => {
    return [
        { name: t('priority.Düşük'), adet: myTotalTasks.filter(t => t.priority === 'Düşük').length },
        { name: t('priority.Orta'), adet: myTotalTasks.filter(t => t.priority === 'Orta').length },
        { name: t('priority.Yüksek'), adet: myTotalTasks.filter(t => t.priority === 'Yüksek').length },
    ];
