                        <div className="text-center mb-10">
                            <div className="inline-flex items-center justify-center w-24 h-24 rounded-2xl bg-zinc-900 border border-zinc-800 mb-6 shadow-xl shadow-indigo-900/20 overflow-hidden">
                                 {/* Image with Error Handling */}
                                 <img 
                                    src={appLogo} 
                                    alt="Logo" 
                                    className="w-full h-full object-cover" 
                                    onError={(e) => {
                                        const target = e.target as HTMLImageElement;
                                        target.onerror = null; // Prevent infinite loop
                                        target.src = DEFAULT_LOGO_URL;
                                    }}
                                />
                            </div>
                            <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">{t('login.title')}</h1>
                            <p className="text-zinc-500">{t('login.subtitle')}</p>
                        </div>

                        <div className="glass-panel p-8 rounded-2xl border border-zinc-800 shadow-2xl bg-zinc-900/50 backdrop-blur-md">
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-xs font-medium text-zinc-400 ml-1">{t('login.email')}</label>
                                    <div className="relative">
                                        <Mail className="absolute left-3 top-3 text-zinc-500 w-5 h-5" />
                                        <input 
                                            type="email" 
                                            value={email}
                                            onChange={(e) => setEmail(e.target.value)}
                                            className="w-full bg-zinc-900/50 border border-zinc-800 rounded-xl py-3 pl-10 pr-4 text-white placeholder:text-zinc-600 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                                            placeholder="ornek@mail.com"
                                        />
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-xs font-medium text-zinc-400 ml-1">{t('login.password')}</label>
                                    <div className="relative">
                                        <Lock className="absolute left-3 top-3 text-zinc-500 w-5 h-5" />
                                        <input 
                                            type="password" 
                                            value={password}
                                            onChange={(e) => setPassword(e.target.value)}
                                            className="w-full bg-zinc-900/50 border border-zinc-800 rounded-xl py-3 pl-10 pr-4 text-white placeholder:text-zinc-600 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                                            placeholder="••••••••"
                                        />
                                    </div>
                                </div>

                                <button 
                                    type="submit" 
                                    disabled={loading}
                                    className="w-full py-4 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-900/20 flex items-center justify-center gap-2 group transition-all active:scale-95"
                                >
                                    {loading ? <Loader2 className="animate-spin" size={20} /> : <span className="flex items-center gap-2">{t('login.btn')} <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" /></span>}
                                </button>
                            </form>
                        </div>

                        {/* --- QUICK LOGIN (HIZLI GİRİŞ) GRID --- */}
                        <div className="mt-8">
                            <div className="flex items-center gap-2 mb-4 justify-center opacity-60">
                                <div className="h-px bg-zinc-800 w-12"></div>
                                <span className="text-[10px] uppercase font-bold text-zinc-500 flex items-center gap-1"><Zap size={10}/> {t('login.quick')}</span>
                                <div className="h-px bg-zinc-800 w-12"></div>
                            </div>

                            <div className="grid grid-cols-3 gap-3">
                                {quickAccessUsers.map((user, idx) => (
                                    <button
                                        key={user.id}
                                        onClick={() => handleQuickLogin(user)}
                                        className="flex flex-col items-center justify-center p-3 rounded-xl bg-zinc-900/40 border border-zinc-800 hover:bg-zinc-800 hover:border-zinc-700 transition-all active:scale-95 group"
                                        title={`${user.name} (${user.role})`}
                                    >
                                        <div className="relative mb-2">
                                            <img src={user.avatarUrl} className="w-10 h-10 rounded-full border-2 border-zinc-900 group-hover:border-zinc-600 transition-colors object-cover" />
                                            {user.role === Role.ADMIN && <div className="absolute -top-1 -right-1 w-4 h-4 bg-indigo-600 rounded-full border-2 border-zinc-950 flex items-center justify-center text-[8px] font-bold text-white">A</div>}
                                        </div>
                                        <span className="text-[10px] font-bold text-zinc-300 truncate w-full text-center">{user.name.split(' ')[0]}</span>
                                        <span className="text-[8px] text-zinc-500 truncate w-full text-center">{user.branch}</span>
                                    </button>
                                ))}
                            </div>
                        </div>

                        <p className="text-center text-xs text-zinc-600 mt-8">
