import React, { useState } from 'react';
import { Lock, Mail, ArrowRight, Loader2, Zap, Building2 } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { MOCK_EMPLOYEES } from '../constants';
import { Employee, Role, Branch } from '../types';
import { useLanguage } from '../lib/i18n';

interface LoginProps {
    onLogin: (user: Employee) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
    const [email, setEmail] = useState('cevikademm@gmail.com');
    const [password, setPassword] = useState('123');
    const [loading, setLoading] = useState(false);

    const { t } = useLanguage();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            // 1. Supabase üzerinden kullanıcıyı sorgula
            // Try/Catch bloğu ile veritabanı hatalarını (örn: tablo silinmişse) yakala
            let dbUser = null;
            try {
                const { data, error } = await supabase
                    .from('profiles')
                    .select('*')
                    .eq('email', email)
                    .eq('password', password) // Basit güvenlik: Şifreyi direkt kontrol et
                    .single();

                if (!error && data) {
                    dbUser = data;
                }
            } catch (dbErr) {
                console.warn("Veritabanı sorgu hatası:", dbErr);
            }

            if (dbUser) {
                // DB'den gelen veriyi frontend formatına çevir
                // GÜVENLİK GÜNCELLEMESİ: Veritabanında alanlar NULL olsa bile varsayılan değerler ata.
                const user: Employee = {
                    id: dbUser.id,
                    name: dbUser.full_name || 'İsimsiz Kullanıcı',
                    email: dbUser.email,
                    role: (dbUser.role as Role) || Role.STAFF, // Rol yoksa Personel yap
                    branch: (dbUser.branch as Branch) || Branch.DOM, // Şube yoksa Dom yap
                    hourlyRate: dbUser.hourly_rate || 15.00,
                    taxClass: dbUser.tax_class || 1,
                    avatarUrl: dbUser.avatar_url || `https://ui-avatars.com/api/?name=${dbUser.full_name}`,
                    advances: dbUser.advances || 0,
                    phone: dbUser.phone || '',
                    bio: dbUser.bio || '',
                    badges: dbUser.badges || [],
                    tags: dbUser.tags || [],
                    metrics: dbUser.metrics || { speed: 50, satisfaction: 50, attendance: 50 }
                };
                onLogin(user);
            } else {
                // 2. Veritabanı başarısızsa veya kayıt yoksa, MOCK veriyle dene (Yedek)
                const mockUser = MOCK_EMPLOYEES.find(e => e.email === email);
                if (mockUser && password === '123') {
                     console.warn("Veritabanında kullanıcı bulunamadı, Mock veri ile giriş yapılıyor.");
                     onLogin(mockUser);
                } else {
                     alert("Hatalı e-posta veya şifre.");
                }
            }
        } catch (err) {
            console.error("Giriş işlemi hatası:", err);
            // Fallback (Son çare)
             const mockUser = MOCK_EMPLOYEES.find(e => e.email === email);
             if (mockUser && password === '123') {
                  onLogin(mockUser);
             } else {
                  alert("Bir hata oluştu.");
             }
        } finally {
            setLoading(false);
        }
    };

    // Hızlı Giriş (Demo) İçin Seçili Kullanıcılar
    const quickAccessUsers = [
