GRANT ALL ON TABLE public.shift_schedules TO service_role;

-- =========================================================
-- 4. REALTIME (CANLI VERİ AKIŞI)
-- =========================================================
-- Tabloları Realtime yayınına ekle
DO $$
DECLARE
    tables text[] := ARRAY['profiles', 'time_logs', 'tasks', 'messages', 'calendar_events', 'shift_schedules', 'app_settings'];
    tbl text;
BEGIN
    FOR tbl IN SELECT unnest(tables) LOOP
        IF NOT EXISTS (
            SELECT 1 FROM pg_publication_tables 
            WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = tbl
        ) THEN
            EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', tbl);
        END IF;
    END LOOP;
