**Hızlı Giriş (Demo) Bölümü:** Kontrol ettim, Login ekranı kodlarınızda bu bölüm zaten temizlenmiş durumda.

**Supabase Bağlantı Kontrolü:**
`lib/supabase.ts` dosyanızdaki `SUPABASE_ANON_KEY` değeri (`sb_publishable_...`) standart bir Supabase API anahtarı formatında görünmüyor. Supabase API anahtarları genellikle `eyJ...` ile başlayan uzun JWT stringleridir.
*   Lütfen Supabase Dashboard > Project Settings > API bölümünden `anon` / `public` anahtarını kopyalayıp `lib/supabase.ts` dosyasına yapıştırdığınızdan emin olun.

**SQL Kodları:**
Supabase SQL Editor'de çalıştırmanız gereken, uygulamanın tüm tablolarını, sütunlarını ve güvenlik politikalarını (RLS) içeren **tam ve güncel SQL kodunu** aşağıda hazırladım. Bu kodu kopyalayıp Supabase SQL Editor'de çalıştırarak veritabanınızı onarabilir veya sıfırdan oluşturabilirsiniz.

### Supabase SQL Kodu (Kopyala ve Çalıştır)

```sql
-- 1. Eklentileri Aktif Et
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. Tabloları Oluştur

-- Personel Profilleri
CREATE TABLE IF NOT EXISTS public.profiles (
  id TEXT PRIMARY KEY DEFAULT uuid_generate_v4()::text,
  email TEXT NOT NULL UNIQUE,
  password TEXT DEFAULT '123',
  full_name TEXT NOT NULL,
  role TEXT DEFAULT 'Personel', -- 'Admin' veya 'Personel'
  branch TEXT, -- 'Dom', 'Backaffee' vb.
  hourly_rate DECIMAL(10, 2) DEFAULT 15.00,
  tax_class INTEGER DEFAULT 1,
  avatar_url TEXT,
  phone TEXT,
  bio TEXT,
  badges TEXT[],
  tags TEXT[],
  metrics JSONB DEFAULT '{"speed": 50, "satisfaction": 50, "attendance": 50}'::jsonb,
  advances DECIMAL(10, 2) DEFAULT 0.00,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Mesai Kayıtları
CREATE TABLE IF NOT EXISTS public.time_logs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id TEXT REFERENCES public.profiles(id) ON DELETE CASCADE,
  date DATE NOT NULL,
  start_time TEXT NOT NULL,
  end_time TEXT NOT NULL,
  break_duration INTEGER DEFAULT 60,
  total_hours DECIMAL(5, 2),
  status TEXT DEFAULT 'Bekliyor',
  branch TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Görevler
CREATE TABLE IF NOT EXISTS public.tasks (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  assigned_to TEXT[] DEFAULT '{}',
  due_date DATE,
  priority TEXT,
  status TEXT DEFAULT 'todo',
  progress INTEGER DEFAULT 0,
  checklist JSONB DEFAULT '[]'::jsonb,
  completed_at TIMESTAMP WITH TIME ZONE,
  completed_by TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Mesajlar
CREATE TABLE IF NOT EXISTS public.messages (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  sender_id TEXT REFERENCES public.profiles(id) ON DELETE SET NULL,
  receiver_id TEXT NOT NULL,
  subject TEXT,
  content TEXT,
  timestamp TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  read BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Takvim Etkinlikleri & Transferler
CREATE TABLE IF NOT EXISTS public.calendar_events (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  type TEXT,
  date DATE NOT NULL,
  end_date DATE,
  start_time TEXT,
  end_time TEXT,
  description TEXT,
  attendees TEXT[],
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Vardiya Planı
CREATE TABLE IF NOT EXISTS public.shift_schedules (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  week_start_date TEXT NOT NULL,
  branch TEXT NOT NULL,
  time_slot TEXT DEFAULT '',
  days TEXT[] DEFAULT ARRAY['', '', '', '', '', '', '']::TEXT[],
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Uygulama Ayarları
CREATE TABLE IF NOT EXISTS public.app_settings (
    setting_key TEXT PRIMARY KEY,
    setting_value TEXT NOT NULL,
    description TEXT,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. Güvenlik Politikaları (RLS - Geliştirme Modu: Herkese Açık)
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.time_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.calendar_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shift_schedules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;

-- Mevcut politikaları temizle
DO $$ 
BEGIN 
    DROP POLICY IF EXISTS "Public Profiles Access" ON public.profiles;
    DROP POLICY IF EXISTS "Public TimeLogs Access" ON public.time_logs;
    DROP POLICY IF EXISTS "Public Tasks Access" ON public.tasks;
    DROP POLICY IF EXISTS "Public Messages Access" ON public.messages;
    DROP POLICY IF EXISTS "Public Calendar Access" ON public.calendar_events;
    DROP POLICY IF EXISTS "Public Shift Access" ON public.shift_schedules;
    DROP POLICY IF EXISTS "Public Settings Access" ON public.app_settings;
END $$;

-- İzinleri tanımla
CREATE POLICY "Public Profiles Access" ON public.profiles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public TimeLogs Access" ON public.time_logs FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public Tasks Access" ON public.tasks FOR ALL USING (true) WITH CHECK (true);
