  const handleSelectEmployee = (id: string) => {
    if(isEditing && selectedEmployeeId !== id) {
        if (!window.confirm("Kaydedilmemiş değişiklikler var. Devam et?")) return;
    }
    setIsEditing(false);
    setEditForm({});
    setSelectedEmployeeId(id);
  };

  const handleAddNew = () => {
