      setEditForm({ ...editForm, [field]: current.filter((_, i) => i !== idx) });
  };
  const handleMetricChange = (key: keyof NonNullable<Employee['metrics']>, val: number) => {
      setEditForm({
          ...editForm,
          metrics: { ...(editForm.metrics || { speed: 0, satisfaction: 0, attendance: 0 }), [key]: val }
      });
