          // Başarılı olursa state'den sil
          setEmployees(employees.filter(e => e.id !== selectedEmployeeId));
          setSelectedEmployeeId(null);
          setIsEditing(false);
      } catch (err: any) {
          console.warn("Silme hatası, yerel modda devam ediliyor:", err);

