import React, { useState, useEffect } from 'react';
import { Lock, Mail, ArrowRight, Loader2, Check } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Employee, Role, Branch } from '../types';
import { useLanguage } from '../lib/i18n';

interface LoginProps {
    onLogin: (user: Employee) => void;
}

const BAC_LOGO_URL = "https://xbbzwitvlrdwnoushgpf.supabase.co/storage/v1/object/public/Bac_Logo/bac.jpeg";

const Login: React.FC<LoginProps> = ({ onLogin }) => {
    // Varsayılan değerler boşaltıldı
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [rememberMe, setRememberMe] = useState(false);
    const [loading, setLoading] = useState(false);

    const { t } = useLanguage();

    // Sayfa yüklendiğinde LocalStorage kontrolü
    useEffect(() => {
        const savedEmail = localStorage.getItem('bac_remember_email');
        if (savedEmail) {
            setEmail(savedEmail);
            setRememberMe(true);
        }
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            let dbUser = null;
            try {
                const { data, error } = await supabase
                    .from('profiles')
                    .select('*')
                    .eq('email', email)
                    .eq('password', password)
                    .single();

                if (!error && data) {
                    dbUser = data;
                }
            } catch (dbErr) {
                console.warn("Veritabanı sorgu hatası:", dbErr);
            }

            if (dbUser) {
                const user: Employee = {
                    id: dbUser.id,
                    name: dbUser.full_name || 'İsimsiz Kullanıcı',
                    email: dbUser.email,
                    role: (dbUser.role as Role) || Role.STAFF,
                    branch: (dbUser.branch as Branch) || Branch.DOM,
                    hourlyRate: dbUser.hourly_rate || 15.00,
                    taxClass: dbUser.tax_class || 1,
                    avatarUrl: dbUser.avatar_url || `https://ui-avatars.com/api/?name=${dbUser.full_name}`,
                    advances: dbUser.advances || 0,
                    phone: dbUser.phone || '',
                    bio: dbUser.bio || '',
                    badges: dbUser.badges || [],
                    tags: dbUser.tags || [],
                    metrics: dbUser.metrics || { speed: 50, satisfaction: 50, attendance: 50 }
                };

                // Başarılı girişte Beni Hatırla mantığı
                if (rememberMe) {
                    localStorage.setItem('bac_remember_email', email);
                } else {
                    localStorage.removeItem('bac_remember_email');
                }

                onLogin(user);
            } else {
                 alert("Hatalı e-posta veya şifre.");
            }
        } catch (err) {
            console.error("Giriş işlemi hatası:", err);
            alert("Bir hata oluştu.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 w-full h-full bg-zinc-950 overflow-hidden z-[9999]">
             <div className="absolute top-[-20%] left-[-10%] w-[600px] h-[600px] bg-indigo-900/10 rounded-full blur-3xl pointer-events-none"></div>
             <div className="absolute bottom-[-20%] right-[-10%] w-[600px] h-[600px] bg-blue-900/10 rounded-full blur-3xl pointer-events-none"></div>

             <div className="absolute inset-0 w-full h-full overflow-y-auto custom-scrollbar">
                 <div className="min-h-full w-full flex items-center justify-center p-4">
                     <div className="w-full max-w-md relative z-10 my-8">
                        <div className="text-center mb-10">
                            <div className="inline-flex items-center justify-center w-24 h-24 rounded-2xl bg-zinc-900 border border-zinc-800 mb-6 shadow-xl shadow-indigo-900/20 overflow-hidden">
                                 <img 
                                    src={BAC_LOGO_URL} 
                                    alt="BAC Logo" 
                                    className="w-full h-full object-cover"
                                 />
                            </div>
                            <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">{t('login.title')}</h1>
                            <p className="text-zinc-500">{t('login.subtitle')}</p>
                        </div>

                        <div className="glass-panel p-8 rounded-2xl border border-zinc-800 shadow-2xl bg-zinc-900/50 backdrop-blur-md">
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-xs font-medium text-zinc-400 ml-1">{t('login.email')}</label>
                                    <div className="relative">
                                        <Mail className="absolute left-3 top-3 text-zinc-500 w-5 h-5" />
                                        <input 
                                            type="email" 
                                            value={email}
                                            onChange={(e) => setEmail(e.target.value)}
                                            className="w-full bg-zinc-900/50 border border-zinc-800 rounded-xl py-3 pl-10 pr-4 text-white placeholder:text-zinc-600 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                                            placeholder="ornek@mail.com"
                                        />
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-xs font-medium text-zinc-400 ml-1">{t('login.password')}</label>
                                    <div className="relative">
                                        <Lock className="absolute left-3 top-3 text-zinc-500 w-5 h-5" />
                                        <input 
                                            type="password" 
                                            value={password}
                                            onChange={(e) => setPassword(e.target.value)}
                                            className="w-full bg-zinc-900/50 border border-zinc-800 rounded-xl py-3 pl-10 pr-4 text-white placeholder:text-zinc-600 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                                            placeholder="••••••••"
                                        />
                                    </div>
                                </div>

                                {/* Beni Hatırla Alanı */}
                                <div 
                                    className="flex items-center gap-2 cursor-pointer group w-fit"
                                    onClick={() => setRememberMe(!rememberMe)}
                                >
                                    <div className={`w-5 h-5 rounded border flex items-center justify-center transition-all ${rememberMe ? 'bg-indigo-600 border-indigo-500' : 'bg-zinc-900 border-zinc-700 group-hover:border-zinc-500'}`}>
                                        {rememberMe && <Check size={14} className="text-white" />}
                                    </div>
                                    <span className={`text-sm select-none transition-colors ${rememberMe ? 'text-indigo-400' : 'text-zinc-500 group-hover:text-zinc-400'}`}>
                                        Beni Hatırla
                                    </span>
                                </div>

                                <button 
                                    type="submit" 
                                    disabled={loading}
                                    className="w-full py-4 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-900/20 flex items-center justify-center gap-2 group transition-all active:scale-95"
                                >
                                    {loading ? <Loader2 className="animate-spin" size={20} /> : <span className="flex items-center gap-2">{t('login.btn')} <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" /></span>}
                                </button>
                            </form>
                        </div>

                        <p className="text-center text-xs text-zinc-600 mt-8">
                            &copy; 2024 BAC Handels Management System
                        </p>
                     </div>
                 </div>
             </div>
        </div>
    );
};

export default Login;

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
    };
  }

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen w-full bg-zinc-950 flex flex-col items-center justify-center p-4 text-center">
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center">
                <div className="w-16 h-16 bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mb-4 border border-red-500/20">
                    <AlertTriangle size={32} />
                </div>
                <h1 className="text-xl font-bold text-white mb-2">Bir Sorun Oluştu</h1>
                <p className="text-zinc-400 text-sm mb-6">
                    Sistem beklenmeyen bir veri durumuyla karşılaştı. Bu genellikle veritabanı bağlantısı veya eksik veriden kaynaklanır.
                </p>

                <div className="bg-black/30 p-3 rounded-lg border border-zinc-800 w-full mb-6 text-left overflow-hidden">
                    <p className="text-[10px] text-red-400 font-mono break-all">
                        {this.state.error?.message || 'Unknown Error'}
                    </p>
                </div>

                <button 
                    onClick={() => {
                        this.setState({ hasError: false, error: null });
                        window.location.href = '/'; // Hard reload to clear state
                    }}
                    className="flex items-center gap-2 px-6 py-3 bg-white text-black hover:bg-zinc-200 font-bold rounded-xl transition-colors w-full justify-center"
                >
                    <RefreshCw size={18} /> Sistemi Yenile
                </button>
            </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

-- 1. Eklentileri Aktif Et
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. Tabloları Oluştur

-- Personel Profilleri
CREATE TABLE IF NOT EXISTS public.profiles (
  id TEXT PRIMARY KEY DEFAULT uuid_generate_v4()::text,
  email TEXT NOT NULL UNIQUE,
  password TEXT DEFAULT '123',
  full_name TEXT NOT NULL,
  role TEXT DEFAULT 'Personel', -- 'Admin' veya 'Personel'
  branch TEXT, -- 'Dom', 'Backaffee' vb.
  hourly_rate DECIMAL(10, 2) DEFAULT 15.00,
  tax_class INTEGER DEFAULT 1,
  avatar_url TEXT,
  phone TEXT,
  bio TEXT,
  badges TEXT[],
  tags TEXT[],
  metrics JSONB DEFAULT '{"speed": 50, "satisfaction": 50, "attendance": 50}'::jsonb,
  advances DECIMAL(10, 2) DEFAULT 0.00,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Mesai Kayıtları
CREATE TABLE IF NOT EXISTS public.time_logs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id TEXT REFERENCES public.profiles(id) ON DELETE CASCADE,
  date DATE NOT NULL,
  start_time TEXT NOT NULL,
  end_time TEXT NOT NULL,
  break_duration INTEGER DEFAULT 60,
  total_hours DECIMAL(5, 2),
  status TEXT DEFAULT 'Bekliyor',
  branch TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Görevler
CREATE TABLE IF NOT EXISTS public.tasks (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  assigned_to TEXT[] DEFAULT '{}',
  due_date DATE,
  priority TEXT,
  status TEXT DEFAULT 'todo',
  progress INTEGER DEFAULT 0,
  checklist JSONB DEFAULT '[]'::jsonb,
  completed_at TIMESTAMP WITH TIME ZONE,
  completed_by TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Mesajlar
CREATE TABLE IF NOT EXISTS public.messages (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  sender_id TEXT REFERENCES public.profiles(id) ON DELETE SET NULL,
  receiver_id TEXT NOT NULL,
  subject TEXT,
  content TEXT,
  timestamp TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  read BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Takvim Etkinlikleri & Transferler
CREATE TABLE IF NOT EXISTS public.calendar_events (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  type TEXT,
  date DATE NOT NULL,
  end_date DATE,
  start_time TEXT,
  end_time TEXT,
  description TEXT,
  attendees TEXT[],
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Vardiya Planı
CREATE TABLE IF NOT EXISTS public.shift_schedules (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  week_start_date TEXT NOT NULL,
  branch TEXT NOT NULL,
  time_slot TEXT DEFAULT '',
  days TEXT[] DEFAULT ARRAY['', '', '', '', '', '', '']::TEXT[],
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Uygulama Ayarları
CREATE TABLE IF NOT EXISTS public.app_settings (
    setting_key TEXT PRIMARY KEY,
    setting_value TEXT NOT NULL,
    description TEXT,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

