export enum Branch {
  DOM = 'Dom',
  BACKAFFEE = 'Backaffee',
  RINGE = 'Ringe',
  MULHEIM = 'Mülheim',
  TOBACGO = 'Tobacgo'
}

export enum Role {
  ADMIN = 'Admin',
  STAFF = 'Personel'
}

export interface Employee {
  id: string;
  name: string;
  email: string;
  role: Role;
  branch: Branch;
  hourlyRate: number;
  taxClass: number; // Vergi sınıfı
  avatarUrl: string;
  advances: number; // Toplam alınan avans
  phone?: string;
  bio?: string;
  badges?: string[];
  tags?: string[];
  metrics?: {
    speed: number;
    satisfaction: number;
    attendance: number;
  };
}

export interface TimeLog {
  id: string;
  employeeId: string;
  date: string;
  startTime: string; // HH:mm
  endTime: string; // HH:mm
  breakDuration: number; // minutes
  totalHours: number;
  branch?: string; // Çalışılan şube
  status: 'Bekliyor' | 'Onaylandı' | 'Reddedildi';
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  assignedTo: string[]; // Changed to Array for Multiple Assignees
  dueDate: string;
  priority: 'Düşük' | 'Orta' | 'Yüksek';
  status: 'todo' | 'in_progress' | 'done'; // Kanban columns
  progress: number; // 0-100 (still useful for logic)
  checklist: { 
    id: string; 
    text: string; 
    completed: boolean; 
    completedBy?: string; // ID of the employee who completed this item
  }[];
  completedAt?: string; // Görevin tamamlandığı tarih (ISO format)
  completedBy?: string; // Görevi komple bitiren kişi
}

export interface Message {
  id: string;
  senderId: string;
  receiverId: string | 'ALL'; // 'ALL' for broadcasts
  subject: string;
  content: string;
  timestamp: string;
  read: boolean;
}

export interface CalendarEvent {
  id: string;
  title: string;
  type: 'Toplantı' | 'Montaj' | 'Teslim Tarihi' | 'Diğer' | 'Şube Transferi';
  date: string; // Başlangıç Tarihi
  endDate?: string; // Bitiş Tarihi (Opsiyonel, transferler için zorunlu)
  startTime: string;
  endTime: string;
  attendees: string[]; // Employee IDs
  description?: string;
}

export interface PayrollEntry {
  id: string;
  employeeId: string;
  month: string; // YYYY-MM
  approvedHours: number;
  officialHours: number; // Resmi bordro saati
  hourlyRate: number;
  advancesDeducted: number;
  netPayable: number; // Hakediş
}

export interface AppNotification {
    id: string;
    type: 'TRANSFER' | 'INFO' | 'ALERT';
    title: string;
    message: string;
    timestamp: string;
    recipientId?: string; // Sadece bu ID'ye sahip kullanıcı görür. Boş veya 'ALL' ise herkes görür.
}

export interface SalesLog {
    id: string;
    employeeId: string;
    branch: Branch;
    productName: string;
    quantity: number;
    saleDate: string;
    createdAt: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../lib/i18n';
import { Branch, Employee, Role, SalesLog } from '../types';
import { Save, Clock, ChevronLeft, ChevronRight, Copy, Plus, Trash2, User, Loader2, Lock, ArrowRightLeft, ShoppingBag, Tag, List } from 'lucide-react';
import { supabase } from '../lib/supabase';

const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
const AKTION_PRODUCTS = [
    "Ploom",
    "Vuse",
    "İqos iluma prime",
    "İqos iluma",
    "İqos one",
    "Veev"
];

interface RosterRow {
    id?: string;
    timeLabel: string; // Örn: "09:00 - 17:00"
    assignments: string[]; // 7 günlük personel ID'leri
}

interface ShiftScheduleProps {
    currentUser: Employee;
}

const getMonday = (d: Date) => {
  const date = new Date(d);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
  return new Date(date.setDate(diff));
};

const ShiftSchedule: React.FC<ShiftScheduleProps> = ({ currentUser }) => {
  const { t, formatDate } = useLanguage();
  const isAdmin = currentUser.role === Role.ADMIN;

  // State
  // Personel ise kendi şubesini varsayılan yap, Admin ise Mulheim
  const [activeBranch, setActiveBranch] = useState<Branch>(isAdmin ? Branch.MULHEIM : currentUser.branch);
  const [viewMode, setViewMode] = useState<'ROSTER' | 'AKTION'>('ROSTER');

  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getMonday(new Date()));
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data States
  const [rosterData, setRosterData] = useState<RosterRow[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);
  const [transferredEmpIds, setTransferredEmpIds] = useState<string[]>([]); // O hafta transfer olanların ID'si

  // Aktion States
  const [salesLogs, setSalesLogs] = useState<SalesLog[]>([]);
  const [salesForm, setSalesForm] = useState({
      product: AKTION_PRODUCTS[0],
      quantity: 1,
      date: new Date().toISOString().split('T')[0]
  });

  const weekKey = `${currentWeekStart.getFullYear()}-${String(currentWeekStart.getMonth() + 1).padStart(2, '0')}-${String(currentWeekStart.getDate()).padStart(2, '0')}`;
  const currentWeekEnd = new Date(currentWeekStart);
  currentWeekEnd.setDate(currentWeekEnd.getDate() + 6);

  // isMounted Ref to prevent state updates on unmounted component
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; };
  }, []);

  // --- EFFECT 1: Personel Listesi ve Transfer Kontrolü ---
  // Bu effect SADECE hafta değiştiğinde veya mount olduğunda çalışır. 
  useEffect(() => {
      fetchEmployeesAndTransfers();

      // Profil veya Transfer değişikliklerini dinle
      const channelId = `shift-profiles-${Date.now()}`;
      const channel = supabase.channel(channelId)
          .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles' }, () => {
             if (isMounted.current) fetchEmployeesAndTransfers();
          })
          .on('postgres_changes', { event: '*', schema: 'public', table: 'calendar_events' }, () => {
             if (isMounted.current) fetchEmployeesAndTransfers();
          })
          .subscribe();

      return () => { supabase.removeChannel(channel); };
  }, [currentWeekStart]); 

  // --- EFFECT 2: Vardiya Çizelgesi & Sales Logs Verisi ---
  // Bu effect Şube, Hafta veya ViewMode değiştiğinde çalışır.
  useEffect(() => {
      if (viewMode === 'ROSTER') {
          fetchWeekData();
      } else {
          fetchSalesLogs();
      }

      const channelId = `shift-data-${Date.now()}`;
      const channel = supabase.channel(channelId)
          .on('postgres_changes', { event: '*', schema: 'public', table: 'shift_schedules' }, (payload) => {
                  const newData = payload.new as any;
                  if (viewMode === 'ROSTER' && (newData && newData.branch === activeBranch && newData.week_start_date === weekKey) || payload.eventType === 'DELETE') {
                      if (!debounceTimeout.current && isMounted.current) fetchWeekData();
                  }
              }
          )
          .on('postgres_changes', { event: '*', schema: 'public', table: 'sales_logs' }, () => {
              if (viewMode === 'AKTION' && isMounted.current) fetchSalesLogs();
          })
          .subscribe();

      return () => { supabase.removeChannel(channel); };
  }, [activeBranch, weekKey, viewMode]); 


  // 1. Personel Listesini ve Transfer Durumlarını Çek
  const fetchEmployeesAndTransfers = async () => {
      try {
          // A. Tüm personelleri çek
          // Filtre: Admin kullanıcısı vardiya planında personel olarak listelenmemeli
          const { data: empData } = await supabase.from('profiles').select('*').neq('role', 'Admin');

          if (!isMounted.current) return;

          let currentEmployees: Employee[] = [];

          if (empData) {
              currentEmployees = empData.map((e: any) => ({
                  id: e.id,
                  name: e.full_name,
                  email: e.email,
                  role: e.role,
                  branch: e.branch,
                  hourlyRate: e.hourly_rate,
                  taxClass: e.tax_class,
                  avatarUrl: e.avatar_url,
                  advances: 0,
                  metrics: e.metrics
              }));

              // FIX: Personel (Admin olmayan) için otomatik şube kontrolü
              // Sonsuz döngüden kaçınmak için activeBranch state'iyle karşılaştırıyoruz
              if (!isAdmin) {
                  const myProfile = currentEmployees.find(e => e.id === currentUser.id);
                  if (myProfile && myProfile.branch) {
                      setActiveBranch(prevBranch => {
                          if (prevBranch !== myProfile.branch) {
                              return myProfile.branch as Branch;
                          }
                          return prevBranch;
                      });
                  }
              }
          }

          // B. Bu hafta için "Şube Transferi" olaylarını kontrol et
          const startStr = currentWeekStart.toISOString().split('T')[0];
          const endStr = currentWeekEnd.toISOString().split('T')[0];

          const { data: transferData } = await supabase
              .from('calendar_events')
              .select('attendees')
              .eq('type', 'Şube Transferi')
              .lte('date', endStr)
              .gte('end_date', startStr);

          if (!isMounted.current) return;

          if (transferData) {
              const ids = transferData.flatMap((t: any) => t.attendees || []);
              setTransferredEmpIds(ids);
          } else {
              setTransferredEmpIds([]);
          }

          setAvailableEmployees(currentEmployees);

      } catch (err) {
          console.error("Personel verisi hatası:", err);
      }
  };

  const fetchWeekData = async () => {
      if (!debounceTimeout.current) setIsLoading(true);

      try {
          const { data, error } = await supabase
              .from('shift_schedules')
              .select('*')
              .eq('week_start_date', weekKey)
              .eq('branch', activeBranch)
              .order('created_at', { ascending: true });

          if (!isMounted.current) return;

          if (error) throw error;

          if (data && data.length > 0) {
              const rows: RosterRow[] = data.map((r: any) => ({
                  id: r.id,
                  timeLabel: r.time_slot || '',
                  assignments: r.days || Array(7).fill('')
              }));
              setRosterData(rows);
          } else {
              setRosterData([]);
          }

      } catch (err: any) {
          console.error("Vardiya verisi çekilemedi:", err);
      } finally {
          if (isMounted.current) setIsLoading(false);
      }
  };

  const fetchSalesLogs = async () => {
      setIsLoading(true);
      try {
          // Admin tüm satışları görebilir (şube filtresiyle)
          // Personel sadece kendi satışlarını veya şubesindeki satışları görebilir.
          // Basitlik için: O şubeye ait tüm satışları gösterelim.
          let query = supabase.from('sales_logs').select('*')
              .eq('branch', activeBranch)
              .order('sale_date', { ascending: false })
              .order('created_at', { ascending: false });

          const { data, error } = await query;
          if (error) throw error;

          if (data) {
              const formattedLogs: SalesLog[] = data.map((l: any) => ({
                  id: l.id,
                  employeeId: l.employee_id,
                  branch: l.branch,
                  productName: l.product_name,
                  quantity: l.quantity,
                  saleDate: l.sale_date,
                  createdAt: l.created_at
              }));
              setSalesLogs(formattedLogs);
          } else {
              setSalesLogs([]);
          }
      } catch (err) {
          console.error("Satış verisi hatası:", err);
      } finally {
          setIsLoading(false);
      }
  };

  const handleWeekChange = (direction: 'prev' | 'next') => {
      const newDate = new Date(currentWeekStart);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setCurrentWeekStart(newDate);
  };

  const debounceTimeout = useRef<any>(null);

  const saveRowToDb = async (row: RosterRow) => {
      if (!isAdmin) return;
      setIsSaving(true);
      try {
          const payload = {
              week_start_date: weekKey,
              branch: String(activeBranch),
              time_slot: row.timeLabel,
              days: row.assignments
          };

          if (row.id && !row.id.startsWith('temp_')) {
              await supabase.from('shift_schedules').update(payload).eq('id', row.id);
          } else {
              const { data, error } = await supabase.from('shift_schedules').insert([payload]).select().single();
              if(!error && data) {
                  if (isMounted.current) {
                      setRosterData(prev => prev.map(r => r.id === row.id ? { ...r, id: data.id } : r));
                  }
              }
          }
      } catch (err) {
          console.error("Otomatik kayıt hatası:", err);
      } finally {
          if (isMounted.current) setIsSaving(false);
      }
  };

  const handleManualSave = async () => {
      if (!isAdmin) return;
      setIsSaving(true);
      try {
          const promises = rosterData.map(row => saveRowToDb(row));
          await Promise.all(promises);
          alert("Tüm veriler başarıyla kaydedildi ve yayınlandı.");
      } catch (err) {
          console.error(err);
          alert("Kayıt sırasında bir hata oluştu.");
      } finally {
          if (isMounted.current) setIsSaving(false);
      }
  };

  const handleAssignmentChange = (rowId: string | undefined, dayIndex: number, employeeId: string) => {
      if (!isAdmin) return;
      const updatedRows = rosterData.map(row => {
          if (row.id !== rowId) return row;
          const newAssignments = [...row.assignments];
          newAssignments[dayIndex] = employeeId;
          return { ...row, assignments: newAssignments };
      });
      setRosterData(updatedRows);

      const rowToSave = updatedRows.find(r => r.id === rowId);
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
          debounceTimeout.current = setTimeout(() => {
              if (isMounted.current) saveRowToDb(rowToSave);
          }, 800); 
      }
  };

  const handleTimeLabelChange = (rowId: string | undefined, newLabel: string) => {
      if (!isAdmin) return;
      const updatedRows = rosterData.map(row => {
          if (row.id !== rowId) return row;
          return { ...row, timeLabel: newLabel };
      });
      setRosterData(updatedRows);

      const rowToSave = updatedRows.find(r => r.id === rowId);
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
          debounceTimeout.current = setTimeout(() => {
              if (isMounted.current) saveRowToDb(rowToSave);
          }, 1000); 
      }
  };

  const addNewRow = async () => {
      if (!isAdmin) return;
      const newRow: RosterRow = {
          id: `temp_${Date.now()}`,
          timeLabel: '', 
          assignments: Array(7).fill('')
      };
      setRosterData([...rosterData, newRow]);
      await saveRowToDb(newRow);
