              </div>

              {/* Card 2: Total Tasks -> GÜNCELLENDİ: SADECE AKTİF GÖREVLER */}
              <div className="rounded-3xl border border-zinc-800 bg-zinc-900/40 p-6 flex flex-col justify-between hover:bg-zinc-900/60 transition-all cursor-pointer group" onClick={() => navigateTo('tasks')}>
                   <div className="flex justify-between items-start">
                      <div className="p-3 bg-indigo-500/10 rounded-2xl text-indigo-400 group-hover:scale-110 transition-transform shadow-lg shadow-indigo-900/10">
                          <CheckSquare size={24} />
