                  <div className="mt-6 flex -space-x-3">
                      {dashboardEmployees.slice(0,3).map(e => (
                          <img key={e.id} src={e.avatarUrl} className="w-8 h-8 rounded-full border-2 border-zinc-950 opacity-80 grayscale group-hover:grayscale-0 transition-all" />
                      ))}
