import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen w-full bg-zinc-950 flex flex-col items-center justify-center p-4 text-center">
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center">
                <div className="w-16 h-16 bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mb-4 border border-red-500/20">
                    <AlertTriangle size={32} />
                </div>
                <h1 className="text-xl font-bold text-white mb-2">Bir Sorun Oluştu</h1>
                <p className="text-zinc-400 text-sm mb-6">
                    Sistem beklenmeyen bir veri durumuyla karşılaştı. Bu genellikle veritabanı bağlantısı veya eksik veriden kaynaklanır.
                </p>

                <div className="bg-black/30 p-3 rounded-lg border border-zinc-800 w-full mb-6 text-left overflow-hidden">
                    <p className="text-[10px] text-red-400 font-mono break-all">
                        {this.state.error?.message || 'Unknown Error'}
                    </p>
                </div>

                <button 
                    onClick={() => {
                        this.setState({ hasError: false, error: null });
                        window.location.href = '/'; // Hard reload to clear state
                    }}
                    className="flex items-center gap-2 px-6 py-3 bg-white text-black hover:bg-zinc-200 font-bold rounded-xl transition-colors w-full justify-center"
                >
                    <RefreshCw size={18} /> Sistemi Yenile
                </button>
            </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useLanguage } from '../lib/i18n';
import { Branch, Employee, Role, SalesLog } from '../types';
import { Save, Clock, ChevronLeft, ChevronRight, Copy, Plus, Trash2, User, Loader2, Lock, ArrowRightLeft, ShoppingBag, Tag, List, CheckCircle2, XCircle, Filter, Calendar, History } from 'lucide-react';
import { supabase } from '../lib/supabase';

const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
const AKTION_PRODUCTS = [
    "Ploom",
    "Vuse",
    "İqos iluma prime",
    "İqos iluma",
    "İqos one",
    "Veev"
];

const YEARS = [2024, 2025, 2026, 2027];
const MONTHS = [
    { val: 1, label: 'Ocak' }, { val: 2, label: 'Şubat' }, { val: 3, label: 'Mart' },
    { val: 4, label: 'Nisan' }, { val: 5, label: 'Mayıs' }, { val: 6, label: 'Haziran' },
    { val: 7, label: 'Temmuz' }, { val: 8, label: 'Ağustos' }, { val: 9, label: 'Eylül' },
    { val: 10, label: 'Ekim' }, { val: 11, label: 'Kasım' }, { val: 12, label: 'Aralık' }
];

interface RosterRow {
    id?: string;
    timeLabel: string; // Örn: "09:00 - 17:00"
    assignments: string[]; // 7 günlük personel ID'leri
}

interface ShiftScheduleProps {
    currentUser: Employee;
}

const getMonday = (d: Date) => {
  const date = new Date(d);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
  return new Date(date.setDate(diff));
};

const ShiftSchedule: React.FC<ShiftScheduleProps> = ({ currentUser }) => {
  const { t, formatDate } = useLanguage();
  const isAdmin = currentUser.role === Role.ADMIN;

  // State
  const [activeBranch, setActiveBranch] = useState<Branch>(isAdmin ? Branch.MULHEIM : currentUser.branch);
  const [viewMode, setViewMode] = useState<'ROSTER' | 'AKTION'>('ROSTER');

  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getMonday(new Date()));
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Roster Data States
  const [rosterData, setRosterData] = useState<RosterRow[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);
  const [transferredEmpIds, setTransferredEmpIds] = useState<string[]>([]); 

  // Aktion States
  const [salesLogs, setSalesLogs] = useState<SalesLog[]>([]);
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);

  const [salesForm, setSalesForm] = useState({
      product: AKTION_PRODUCTS[0],
      quantity: 1,
      date: new Date().toISOString().split('T')[0]
  });

  const weekKey = `${currentWeekStart.getFullYear()}-${String(currentWeekStart.getMonth() + 1).padStart(2, '0')}-${String(currentWeekStart.getDate()).padStart(2, '0')}`;
  const currentWeekEnd = new Date(currentWeekStart);
  currentWeekEnd.setDate(currentWeekEnd.getDate() + 6);

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; };
  }, []);

  // --- EFFECT 1: Personel Listesi ve Transfer ---
  useEffect(() => {
      fetchEmployeesAndTransfers();
      const channel = supabase.channel(`shift-profiles-${Date.now()}`)
          .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles' }, () => { if (isMounted.current) fetchEmployeesAndTransfers(); })
          .on('postgres_changes', { event: '*', schema: 'public', table: 'calendar_events' }, () => { if (isMounted.current) fetchEmployeesAndTransfers(); })
          .subscribe();
      return () => { supabase.removeChannel(channel); };
  }, [currentWeekStart]); 

  // --- EFFECT 2: Vardiya ve Satış Verileri ---
  useEffect(() => {
      if (viewMode === 'ROSTER') {
          fetchWeekData();
      } else {
          fetchSalesLogs();
      }

      const channel = supabase.channel(`shift-data-${Date.now()}`)
          .on('postgres_changes', { event: '*', schema: 'public', table: 'shift_schedules' }, (payload) => {
                  const newData = payload.new as any;
                  if (viewMode === 'ROSTER' && (newData && newData.branch === activeBranch && newData.week_start_date === weekKey) || payload.eventType === 'DELETE') {
                      if (!debounceTimeout.current && isMounted.current) fetchWeekData();
                  }
              }
          )
          .on('postgres_changes', { event: '*', schema: 'public', table: 'sales_logs' }, () => {
              if (viewMode === 'AKTION' && isMounted.current) fetchSalesLogs();
          })
          .subscribe();

      return () => { supabase.removeChannel(channel); };
  }, [activeBranch, weekKey, viewMode, selectedYear, selectedMonth]); 


  const fetchEmployeesAndTransfers = async () => {
      try {
          const { data: empData } = await supabase.from('profiles').select('*').neq('role', 'Admin');
          if (!isMounted.current) return;

          let currentEmployees: Employee[] = [];
          if (empData) {
              currentEmployees = empData.map((e: any) => ({
                  id: e.id, name: e.full_name, email: e.email, role: e.role, branch: e.branch,
                  hourlyRate: e.hourly_rate, taxClass: e.tax_class, avatarUrl: e.avatar_url, advances: 0, metrics: e.metrics
              }));
              if (!isAdmin) {
                  const myProfile = currentEmployees.find(e => e.id === currentUser.id);
                  if (myProfile && myProfile.branch) {
                      setActiveBranch(prevBranch => prevBranch !== myProfile.branch ? myProfile.branch as Branch : prevBranch);
                  }
              }
          }

          const startStr = currentWeekStart.toISOString().split('T')[0];
          const endStr = currentWeekEnd.toISOString().split('T')[0];
          const { data: transferData } = await supabase.from('calendar_events').select('attendees').eq('type', 'Şube Transferi').lte('date', endStr).gte('end_date', startStr);

          if (!isMounted.current) return;
          if (transferData) {
              setTransferredEmpIds(transferData.flatMap((t: any) => t.attendees || []));
          } else {
              setTransferredEmpIds([]);
          }
          setAvailableEmployees(currentEmployees);
      } catch (err) { console.error(err); }
  };

  const fetchWeekData = async () => {
      if (!debounceTimeout.current) setIsLoading(true);
      try {
          const { data, error } = await supabase.from('shift_schedules').select('*').eq('week_start_date', weekKey).eq('branch', activeBranch).order('created_at', { ascending: true });
          if (!isMounted.current) return;
          if (error) throw error;
          if (data && data.length > 0) {
              setRosterData(data.map((r: any) => ({ id: r.id, timeLabel: r.time_slot || '', assignments: r.days || Array(7).fill('') })));
          } else {
              setRosterData([]);
          }
      } catch (err: any) { console.error(err); } finally { if (isMounted.current) setIsLoading(false); }
  };

  const fetchSalesLogs = async () => {
      setIsLoading(true);
      try {
          // Tarih aralığını belirle (Ay başı ve sonu)
          const startDate = new Date(selectedYear, selectedMonth - 1, 1).toISOString().split('T')[0];
          const endDate = new Date(selectedYear, selectedMonth, 0).toISOString().split('T')[0];

          let query = supabase.from('sales_logs').select('*')
              .gte('sale_date', startDate)
              .lte('sale_date', endDate)
              .order('sale_date', { ascending: false })
              .order('created_at', { ascending: false });

          // Eğer personel ise sadece kendi kayıtlarını görsün
          if (!isAdmin) {
              query = query.eq('employee_id', currentUser.id);
          } else {
              // Admin ise seçili şubeye göre filtrelesin (Opsiyonel, tüm şubeler istenirse kaldırılabilir)
              if (activeBranch !== 'ALL' as any) { // Branch type doesn't have ALL but for filters logic we might assume
                  query = query.eq('branch', activeBranch);
              }
          }

          const { data, error } = await query;
          if (error) throw error;

          if (data) {
              setSalesLogs(data.map((l: any) => ({
                  id: l.id, employeeId: l.employee_id, branch: l.branch, productName: l.product_name,
                  quantity: l.quantity, saleDate: l.sale_date, status: l.status, createdAt: l.created_at
              })));
          } else {
              setSalesLogs([]);
          }
      } catch (err) { console.error(err); } finally { setIsLoading(false); }
  };

  const handleWeekChange = (direction: 'prev' | 'next') => {
      const newDate = new Date(currentWeekStart);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setCurrentWeekStart(newDate);
  };

  const debounceTimeout = useRef<any>(null);

  const saveRowToDb = async (row: RosterRow) => {
      if (!isAdmin) return;
      setIsSaving(true);
      try {
          const payload = { week_start_date: weekKey, branch: String(activeBranch), time_slot: row.timeLabel, days: row.assignments };
          if (row.id && !row.id.startsWith('temp_')) {
              await supabase.from('shift_schedules').update(payload).eq('id', row.id);
          } else {
              const { data, error } = await supabase.from('shift_schedules').insert([payload]).select().single();
              if(!error && data && isMounted.current) setRosterData(prev => prev.map(r => r.id === row.id ? { ...r, id: data.id } : r));
          }
      } catch (err) { console.error(err); } finally { if (isMounted.current) setIsSaving(false); }
  };

  const handleManualSave = async () => {
      if (!isAdmin) return;
      setIsSaving(true);
      try {
          await Promise.all(rosterData.map(row => saveRowToDb(row)));
          alert("Tüm veriler kaydedildi.");
      } catch (err) { console.error(err); } finally { if (isMounted.current) setIsSaving(false); }
  };

  const handleAssignmentChange = (rowId: string | undefined, dayIndex: number, employeeId: string) => {
      if (!isAdmin) return;
      const updatedRows = rosterData.map(row => {
          if (row.id !== rowId) return row;
          const newAssignments = [...row.assignments];
          newAssignments[dayIndex] = employeeId;
          return { ...row, assignments: newAssignments };
      });
      setRosterData(updatedRows);
      const rowToSave = updatedRows.find(r => r.id === rowId);
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
          debounceTimeout.current = setTimeout(() => { if (isMounted.current) saveRowToDb(rowToSave); }, 800); 
      }
  };

  const handleTimeLabelChange = (rowId: string | undefined, newLabel: string) => {
      if (!isAdmin) return;
      const updatedRows = rosterData.map(row => row.id === rowId ? { ...row, timeLabel: newLabel } : row);
      setRosterData(updatedRows);
      const rowToSave = updatedRows.find(r => r.id === rowId);
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
          debounceTimeout.current = setTimeout(() => { if (isMounted.current) saveRowToDb(rowToSave); }, 1000); 
      }
  };

  const addNewRow = async () => {
      if (!isAdmin) return;
      const newRow: RosterRow = { id: `temp_${Date.now()}`, timeLabel: '', assignments: Array(7).fill('') };
      setRosterData([...rosterData, newRow]);
      await saveRowToDb(newRow);
  };

  const deleteRow = async (rowId: string) => {
      if (!isAdmin) return;
      if(!confirm("Silmek istediğinize emin misiniz?")) return;
      setRosterData(prev => prev.filter(r => r.id !== rowId));
      if (rowId && !rowId.startsWith('temp_')) await supabase.from('shift_schedules').delete().eq('id', rowId);
  };

  const handleCopyNextWeek = async () => {
      if (!isAdmin) return;
      if (rosterData.length === 0) return alert("Kopyalanacak veri yok.");
      const nextWeekDate = new Date(currentWeekStart); nextWeekDate.setDate(nextWeekDate.getDate() + 7);
      const nextWeekKey = `${nextWeekDate.getFullYear()}-${String(nextWeekDate.getMonth() + 1).padStart(2, '0')}-${String(nextWeekDate.getDate()).padStart(2, '0')}`;
      if (confirm(`Bu planı ${formatDate(nextWeekDate)} haftasına kopyalamak istiyor musunuz?`)) {
          setIsLoading(true);
          try {
              await supabase.from('shift_schedules').delete().eq('week_start_date', nextWeekKey).eq('branch', String(activeBranch));
              const payload = rosterData.map(row => ({ week_start_date: nextWeekKey, branch: String(activeBranch), time_slot: row.timeLabel, days: row.assignments }));
              if(payload.length > 0) {
                  await supabase.from('shift_schedules').insert(payload);
                  alert("Kopyalandı.");
                  if (isMounted.current) setCurrentWeekStart(nextWeekDate);
              }
          } catch (err: any) { alert(`Hata: ${err.message}`); } finally { if (isMounted.current) setIsLoading(false); }
      }
  };

  // --- SALES HANDLERS ---
  const handleSaveSale = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsSaving(true);
      try {
          const payload = {
              employee_id: currentUser.id,
              branch: activeBranch,
              product_name: salesForm.product,
              quantity: salesForm.quantity,
              sale_date: salesForm.date,
              status: 'Bekliyor'
          };

          const { data, error } = await supabase.from('sales_logs').insert([payload]).select();
          if (error) throw error;

          if (data) {
              const newLog: SalesLog = {
                  id: data[0].id, employeeId: data[0].employee_id, branch: data[0].branch,
                  productName: data[0].product_name, quantity: data[0].quantity, saleDate: data[0].sale_date,
                  status: 'Bekliyor', createdAt: data[0].created_at
              };
              setSalesLogs([newLog, ...salesLogs]);
              alert("Satış kaydı onaya gönderildi.");
          }
      } catch (err: any) { alert("Kaydedilemedi: " + err.message); } finally { setIsSaving(false); }
  };

  const handleUpdateStatus = async (id: string, newStatus: 'Onaylandı' | 'Reddedildi') => {
      if(!isAdmin) return;
      try {
          const { error } = await supabase.from('sales_logs').update({ status: newStatus }).eq('id', id);
          if (error) throw error;
          setSalesLogs(prev => prev.map(l => l.id === id ? { ...l, status: newStatus } : l));
      } catch (err) { console.error(err); }
  };

  const handleDeleteSale = async (id: string) => {
      if(!confirm("Silmek istediğinize emin misiniz?")) return;
      try {
          const { error } = await supabase.from('sales_logs').delete().eq('id', id);
          if (error) throw error;
          setSalesLogs(prev => prev.filter(l => l.id !== id));
      } catch (err) { console.error("Delete error:", err); }
  };

  // --- STATS CALCULATION FOR ADMIN VIEW ---
  const employeePerformance = useMemo(() => {
      const stats: Record<string, { total: number, products: Record<string, number> }> = {};

      // Sadece onaylanmış satışları hesaba kat
      salesLogs.filter(l => l.status === 'Onaylandı').forEach(log => {
          if (!stats[log.employeeId]) {
              stats[log.employeeId] = { total: 0, products: {} };
          }
          stats[log.employeeId].total += log.quantity;
          stats[log.employeeId].products[log.productName] = (stats[log.employeeId].products[log.productName] || 0) + log.quantity;
      });

      return Object.entries(stats).map(([empId, data]) => ({
          empId,
          total: data.total,
          products: data.products
      })).sort((a, b) => b.total - a.total);
  }, [salesLogs]);

  const pendingSales = salesLogs.filter(l => l.status === 'Bekliyor');

  // --- RENDER HELPERS ---
  const filteredEmployees = availableEmployees.filter(e => e.branch === activeBranch);
  const displayedRows = isAdmin ? rosterData : rosterData.filter(row => row.assignments.includes(currentUser.id));

  return (
    <div className="h-full w-full flex flex-col bg-[#09090b] relative overflow-hidden">

      {/* HEADER CONTROLS */}
      <div className="p-4 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-md sticky top-0 z-30 shrink-0">
          <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">

              <div className="flex items-center gap-2 overflow-x-auto max-w-full pb-1 xl:pb-0 custom-scrollbar">
                  {isAdmin ? (
                      Object.values(Branch).map(branch => (
                          <button key={branch} onClick={() => setActiveBranch(branch)} className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all whitespace-nowrap border ${activeBranch === branch ? 'bg-zinc-100 text-black border-white shadow-[0_0_15px_rgba(255,255,255,0.2)]' : 'bg-zinc-900 text-zinc-500 border-zinc-800 hover:text-zinc-300 hover:border-zinc-700'}`}>{branch}</button>
                      ))
                  ) : (
                      <div className="flex items-center gap-2 px-4 py-2 bg-zinc-900 border border-zinc-800 rounded-xl"><span className="text-sm font-bold text-white">{activeBranch}</span><span className="text-xs text-zinc-500">({t('shift.activeBranch')})</span></div>
                  )}
              </div>

              <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto justify-between xl:justify-end">
                  <div className="flex bg-zinc-900 rounded-xl p-1 border border-zinc-800">
                      <button onClick={() => setViewMode('ROSTER')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${viewMode === 'ROSTER' ? 'bg-zinc-800 text-white shadow' : 'text-zinc-500 hover:text-zinc-300'}`}>Vardiya</button>
                      <button onClick={() => setViewMode('AKTION')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'AKTION' ? 'bg-orange-600 text-white shadow' : 'text-zinc-500 hover:text-zinc-300'}`}><ShoppingBag size={14}/> Aktion</button>
                  </div>

                  {viewMode === 'ROSTER' && (
                      <div className="flex items-center bg-zinc-900 rounded-xl border border-zinc-800 p-1 shadow-sm">
                            <button onClick={() => handleWeekChange('prev')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronLeft size={20}/></button>
                            <div className="px-4 text-center min-w-[140px]"><span className="block text-[10px] text-zinc-500 uppercase font-bold tracking-wider">{t('cal.week')}</span><span className="block text-sm font-bold text-white whitespace-nowrap">{formatDate(currentWeekStart, { day: 'numeric', month: 'short' })} - {formatDate(currentWeekEnd, { day: 'numeric', month: 'short' })}</span></div>
                            <button onClick={() => handleWeekChange('next')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronRight size={20}/></button>
                      </div>
                  )}

                  {isAdmin && viewMode === 'ROSTER' && (
                      <div className="flex items-center gap-3 w-full md:w-auto">
                            <button onClick={handleCopyNextWeek} title="Kopyala" className="flex items-center gap-2 px-4 py-3 bg-zinc-900 hover:bg-zinc-800 text-zinc-400 hover:text-white rounded-xl font-bold transition-all border border-zinc-800"><Copy size={18} /><span className="hidden md:inline">{t('shift.copy')}</span></button>
                            <button onClick={handleManualSave} disabled={isSaving} className="flex items-center justify-center gap-2 px-6 py-3 bg-green-600 hover:bg-green-500 text-white rounded-xl font-bold transition-all border border-green-500 shadow-lg shadow-green-900/20 active:scale-95 min-w-[120px]">{isSaving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}<span>{t('shift.save')}</span></button>
                            <button onClick={addNewRow} className="flex items-center justify-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold transition-all border border-indigo-500 shadow-lg shadow-indigo-900/20 active:scale-95 min-w-[120px]"><Plus size={18} /><span>{t('shift.addTime')}</span></button>
                      </div>
                  )}
              </div>
          </div>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar bg-zinc-950 p-0 md:p-4">
        {viewMode === 'ROSTER' ? (
            <div className="min-w-[1200px] h-full pb-20"> 
                <div className="rounded-xl border border-zinc-800 bg-zinc-900 overflow-hidden shadow-2xl relative">
                    {isLoading && (<div className="absolute inset-0 z-50 bg-zinc-950/80 backdrop-blur-sm flex items-center justify-center"><Loader2 size={40} className="text-blue-500 animate-spin" /></div>)}
                    <table className="w-full border-collapse table-fixed">
                        <thead>
                            <tr>
                                <th className="w-32 p-4 bg-indigo-900/20 text-center text-indigo-300 font-bold text-sm border-b border-r border-zinc-800 sticky left-0 z-20 shadow-[4px_0_10px_rgba(0,0,0,0.3)] uppercase tracking-wider"><div className="flex items-center justify-center gap-2"><Clock size={16} /> Uhrzeit</div></th>
                                {DAYS.map((day, idx) => {
                                    const d = new Date(currentWeekStart); d.setDate(d.getDate() + idx);
                                    const isToday = new Date().toDateString() === d.toDateString();
                                    return (<th key={day} className={`p-4 text-center border-b border-r border-zinc-800/50 last:border-r-0 ${isToday ? 'bg-red-900/40 text-red-200' : 'bg-red-900/10 text-red-400'}`}><div className="flex flex-col items-center"><span className="text-xs font-bold uppercase tracking-wider mb-1">{day}</span></div></th>);
                                })}
                                {isAdmin && <th className="w-16 bg-zinc-900 border-b border-zinc-800"></th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-zinc-800/50">
                            {displayedRows.length === 0 ? (
                                <tr><td colSpan={isAdmin ? 9 : 8} className="p-12 text-center text-zinc-500 italic bg-zinc-950">{isAdmin ? t('shift.noDataAdmin') : t('shift.noData')}</td></tr>
                            ) : (
                                displayedRows.map((row) => (
                                    <tr key={row.id} className="group hover:bg-zinc-800/30 transition-colors">
                                        <td className="p-2 bg-zinc-950 border-r border-zinc-800 sticky left-0 z-10 shadow-[4px_0_10px_rgba(0,0,0,0.3)]">
                                            {isAdmin ? (<input type="text" value={row.timeLabel} onChange={(e) => handleTimeLabelChange(row.id, e.target.value)} className="w-full bg-transparent text-center font-bold text-zinc-300 focus:text-white outline-none placeholder:text-zinc-700" placeholder="00-00"/>) : (<div className="text-center font-bold text-white">{row.timeLabel}</div>)}
                                        </td>
                                        {row.assignments.map((empId, dayIdx) => (
                                            <td key={dayIdx} className="p-2 border-r border-zinc-800/30 last:border-r-0 relative">
                                                <div className="relative flex justify-center items-center h-10">
                                                    {isAdmin ? (
                                                        <select value={empId} onChange={(e) => handleAssignmentChange(row.id, dayIdx, e.target.value)} className={`w-full bg-transparent appearance-none outline-none text-sm text-center cursor-pointer transition-colors ${empId ? 'text-white font-medium' : 'text-zinc-600'} ${transferredEmpIds.includes(empId) ? 'font-bold text-orange-400' : ''}`}>
                                                            <option value="" className="bg-zinc-900 text-zinc-500">-</option>
                                                            {filteredEmployees.map(emp => (<option key={emp.id} value={emp.id} className={`bg-zinc-900 ${transferredEmpIds.includes(emp.id) ? 'text-orange-400 font-bold' : 'text-white'}`}>{emp.name} {transferredEmpIds.includes(emp.id) ? '(T)' : ''}</option>))}
                                                        </select>
                                                    ) : (<span className={`text-sm ${empId === currentUser.id ? 'text-green-400 font-bold' : 'text-zinc-700'}`}>{empId === currentUser.id ? currentUser.name : '-'}</span>)}
