                        )}
                    </div>
                </div>
            </div>

            {/* Detailed Table */}
            <div className="mt-8 bg-zinc-900/30 border border-zinc-800 rounded-3xl overflow-hidden">
                <div className="p-6 border-b border-zinc-800 flex items-center justify-between">
                    <h3 className="text-lg font-bold text-white flex items-center gap-2">
                        <ListTodo className="text-blue-500" size={20}/>
                        {t('sales.tableTitle')}
                    </h3>
                    <span className="text-xs text-zinc-500">{filteredData.length} Kayıt</span>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead>
                            <tr className="text-left text-xs font-bold text-zinc-500 uppercase bg-zinc-950/50 border-b border-zinc-800">
                                <th className="p-4">{t('sales.date')}</th>
                                <th className="p-4">{t('sales.personnel')}</th>
                                <th className="p-4">{t('sales.branch')}</th>
                                <th className="p-4">{t('sales.product')}</th>
                                <th className="p-4 text-center">{t('sales.quantity')}</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-zinc-800">
                            {filteredData.slice(0, 20).map((log) => {
                                const emp = employees.find(e => e.id === log.employeeId);
                                return (
                                    <tr key={log.id} className="text-sm text-zinc-300 hover:bg-zinc-800/30 transition-colors">
                                        <td className="p-4 font-mono text-zinc-500">{formatDate(log.saleDate)}</td>
                                        <td className="p-4 font-bold text-white flex items-center gap-2">
                                            <div className="w-6 h-6 rounded-full bg-zinc-800 flex items-center justify-center text-[10px] overflow-hidden border border-zinc-700">
                                                {emp?.avatarUrl ? (
                                                    <img src={emp.avatarUrl} className="w-full h-full object-cover"/>
                                                ) : (
                                                    log.employeeId ? log.employeeId.slice(0,1).toUpperCase() : '?'
                                                )}
                                            </div>
                                            {emp?.name || <span className="text-zinc-500 italic">Silinmiş</span>}
                                        </td>
                                        <td className="p-4 text-orange-400">{log.branch}</td>
                                        <td className="p-4 text-white font-medium">{log.productName}</td>
                                        <td className="p-4 text-center font-mono font-bold">{log.quantity}</td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

