import React, { useState, useEffect, useMemo } from 'react';
import { SalesLog, Employee, Role } from '../types';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Trophy, TrendingUp, ShoppingBag, MapPin, Award, Medal, Calendar, Package, Activity, BarChart3, ListTodo, User, Lock, EyeOff } from 'lucide-react';

interface SalesDashboardProps {
    currentUser: Employee;
}

type TimeFilter = 'WEEKLY' | 'MONTHLY' | 'YEARLY';

const SalesDashboard: React.FC<SalesDashboardProps> = ({ currentUser }) => {
    const { t, formatDate } = useLanguage();
    const [salesData, setSalesData] = useState<SalesLog[]>([]);
    const [employees, setEmployees] = useState<Employee[]>([]);
    const [timeFilter, setTimeFilter] = useState<TimeFilter>('MONTHLY');
    const [isLoading, setIsLoading] = useState(true);

    const isAdmin = currentUser.role === Role.ADMIN;

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            // 1. Fetch Sales (Global Fetch - Filtering happens in memory for privacy)
            const { data: sales } = await supabase.from('sales_logs').select('*');
            if (sales) {
                const formattedSales = sales.map((l: any) => ({
                    id: l.id,
                    employeeId: l.employee_id, // Can be null
                    branch: l.branch,
                    productName: l.product_name,
                    quantity: l.quantity,
                    saleDate: l.sale_date,
                    status: l.status,
                    createdAt: l.created_at
                }));
                setSalesData(formattedSales);
            }

            // 2. Fetch Profiles for Names
            const { data: profiles } = await supabase.from('profiles').select('*');
            if (profiles) {
                const formattedEmps = profiles.map((p: any) => ({
                    id: p.id,
                    name: p.full_name,
                    avatarUrl: p.avatar_url || `https://ui-avatars.com/api/?name=${p.full_name}`,
                    branch: p.branch
                }));
                setEmployees(formattedEmps as Employee[]);
            }
        } catch (err) {
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    // Calculate GLOBAL stats for Leaderboard (must be calculated before filtering for user)
    const leaderboardData = useMemo(() => {
        const now = new Date();
        let startDate = new Date();

        if (timeFilter === 'WEEKLY') {
            const day = now.getDay() || 7;
            if (day !== 1) startDate.setHours(-24 * (day - 1));
            startDate.setHours(0, 0, 0, 0);
        } else if (timeFilter === 'MONTHLY') {
            startDate.setDate(1);
            startDate.setHours(0, 0, 0, 0);
        } else {
            startDate.setMonth(0, 1);
            startDate.setHours(0, 0, 0, 0);
        }

        // Global Approved Sales in Timeframe
        const globalFiltered = salesData.filter(s => {
            const saleDate = new Date(s.saleDate);
            return saleDate >= startDate && s.status === 'Onaylandı';
        });

        const personnelMap: Record<string, number> = {};
        globalFiltered.forEach(s => {
            const empId = s.employeeId || 'unknown';
            personnelMap[empId] = (personnelMap[empId] || 0) + s.quantity;
        });

        return Object.entries(personnelMap)
            .map(([id, count]) => {
                if (id === 'unknown') return null;
                const emp = employees.find(e => e.id === id);
                return { 
                    id, 
                    name: emp?.name || 'Bilinmeyen Personel', 
                    avatar: emp?.avatarUrl, 
                    count, 
                    branch: emp?.branch || '-' 
                };
            })
            .filter(Boolean)
            .sort((a, b) => (b?.count || 0) - (a?.count || 0))
            .slice(0, 5); // Top 5
    }, [salesData, timeFilter, employees]);


    // Filter Data for Charts/Cards (Private View)
    // If Admin: See ALL. If Staff: See ONLY OWN data.
    const filteredData = useMemo(() => {
        const now = new Date();
        let startDate = new Date();

        if (timeFilter === 'WEEKLY') {
            const day = now.getDay() || 7;
            if (day !== 1) startDate.setHours(-24 * (day - 1));
            startDate.setHours(0, 0, 0, 0);
        } else if (timeFilter === 'MONTHLY') {
            startDate.setDate(1);
            startDate.setHours(0, 0, 0, 0);
        } else {
            startDate.setMonth(0, 1);
            startDate.setHours(0, 0, 0, 0);
        }

        return salesData.filter(s => {
            // DATE CHECK
            const saleDate = new Date(s.saleDate);
            const inTime = saleDate >= startDate;

            // STATUS CHECK
            const isApproved = s.status === 'Onaylandı';

            // PRIVACY CHECK
            const isMine = s.employeeId === currentUser.id;

            // Return logic:
            // Must be in time range AND approved.
            // AND (User is Admin OR Record belongs to User)
            return inTime && isApproved && (isAdmin || isMine);
        });
    }, [salesData, timeFilter, isAdmin, currentUser]);


    // Statistics based on filtered data (Private View)
    const stats = useMemo(() => {
        const totalSales = filteredData.reduce((acc, curr) => acc + curr.quantity, 0);

        // Group by Branch (If staff, likely just their branch, if Admin, all branches)
        const branchMap: Record<string, number> = {};
        filteredData.forEach(s => {
            const branchName = s.branch || 'Bilinmiyor';
            branchMap[branchName] = (branchMap[branchName] || 0) + s.quantity;
        });
        const topBranchName = Object.keys(branchMap).sort((a, b) => branchMap[b] - branchMap[a])[0];

        // Group by Product
        const productMap: Record<string, number> = {};
        filteredData.forEach(s => {
            const prodName = s.productName || 'Bilinmiyor';
            productMap[prodName] = (productMap[prodName] || 0) + s.quantity;
        });
        const topProductName = Object.keys(productMap).sort((a, b) => productMap[b] - productMap[a])[0];

        // Chart Data (Branch)
        const chartData = Object.entries(branchMap).map(([name, value]) => ({ name, value })).sort((a,b) => b.value - a.value);

        return { 
            totalSales, 
            topBranchName, 
            topBranchCount: branchMap[topBranchName] || 0, 
            topProductName, 
            topProductCount: productMap[topProductName] || 0, 
            chartData 
        };
    }, [filteredData]);

    return (
        <div className="h-full w-full p-4 md:p-8 overflow-y-auto custom-scrollbar bg-[#09090b]">
            {/* Header */}
            <div className="mb-8 flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
