import React, { useState, useEffect, useMemo } from 'react';
import { SalesLog, Employee, Role } from '../types';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Trophy, TrendingUp, ShoppingBag, MapPin, Award, Medal, Calendar, Package, Activity, BarChart3, ListTodo, User, Lock, EyeOff } from 'lucide-react';

interface SalesDashboardProps {
    currentUser: Employee;
}

type TimeFilter = 'WEEKLY' | 'MONTHLY' | 'YEARLY';

const SalesDashboard: React.FC<SalesDashboardProps> = ({ currentUser }) => {
    const { t, formatDate } = useLanguage();
    const [salesData, setSalesData] = useState<SalesLog[]>([]);
    const [employees, setEmployees] = useState<Employee[]>([]);
    const [timeFilter, setTimeFilter] = useState<TimeFilter>('MONTHLY');
    const [isLoading, setIsLoading] = useState(true);

    const isAdmin = currentUser.role === Role.ADMIN;

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            // 1. Fetch Sales (Global Fetch - Filtering happens in memory for privacy)
            const { data: sales } = await supabase.from('sales_logs').select('*');
            if (sales) {
                const formattedSales = sales.map((l: any) => ({
                    id: l.id,
                    employeeId: l.employee_id, // Can be null
                    branch: l.branch,
                    productName: l.product_name,
                    quantity: l.quantity,
                    saleDate: l.sale_date,
                    status: l.status,
                    createdAt: l.created_at
                }));
                setSalesData(formattedSales);
            }

            // 2. Fetch Profiles for Names
            const { data: profiles } = await supabase.from('profiles').select('*');
            if (profiles) {
                const formattedEmps = profiles.map((p: any) => ({
                    id: p.id,
                    name: p.full_name,
                    avatarUrl: p.avatar_url || `https://ui-avatars.com/api/?name=${p.full_name}`,
                    branch: p.branch
                }));
                setEmployees(formattedEmps as Employee[]);
            }
        } catch (err) {
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    // Calculate GLOBAL stats for Leaderboard (must be calculated before filtering for user)
    const leaderboardData = useMemo(() => {
        const now = new Date();
        let startDate = new Date();

        if (timeFilter === 'WEEKLY') {
            const day = now.getDay() || 7;
            if (day !== 1) startDate.setHours(-24 * (day - 1));
            startDate.setHours(0, 0, 0, 0);
        } else if (timeFilter === 'MONTHLY') {
            startDate.setDate(1);
            startDate.setHours(0, 0, 0, 0);
        } else {
            startDate.setMonth(0, 1);
            startDate.setHours(0, 0, 0, 0);
        }

        // Global Approved Sales in Timeframe
        const globalFiltered = salesData.filter(s => {
            const saleDate = new Date(s.saleDate);
            return saleDate >= startDate && s.status === 'Onaylandı';
        });

        const personnelMap: Record<string, number> = {};
        globalFiltered.forEach(s => {
            const empId = s.employeeId || 'unknown';
            personnelMap[empId] = (personnelMap[empId] || 0) + s.quantity;
        });

        return Object.entries(personnelMap)
            .map(([id, count]) => {
                if (id === 'unknown') return null;
                const emp = employees.find(e => e.id === id);
                return { 
                    id, 
                    name: emp?.name || 'Bilinmeyen Personel', 
                    avatar: emp?.avatarUrl, 
                    count, 
                    branch: emp?.branch || '-' 
                };
            })
            .filter(Boolean)
            .sort((a, b) => (b?.count || 0) - (a?.count || 0))
            .slice(0, 5); // Top 5
    }, [salesData, timeFilter, employees]);


    // Filter Data for Charts/Cards (Private View)
    // If Admin: See ALL. If Staff: See ONLY OWN data.
    const filteredData = useMemo(() => {
        const now = new Date();
        let startDate = new Date();

        if (timeFilter === 'WEEKLY') {
            const day = now.getDay() || 7;
            if (day !== 1) startDate.setHours(-24 * (day - 1));
            startDate.setHours(0, 0, 0, 0);
        } else if (timeFilter === 'MONTHLY') {
            startDate.setDate(1);
            startDate.setHours(0, 0, 0, 0);
        } else {
            startDate.setMonth(0, 1);
            startDate.setHours(0, 0, 0, 0);
        }

        return salesData.filter(s => {
            // DATE CHECK
            const saleDate = new Date(s.saleDate);
            const inTime = saleDate >= startDate;

            // STATUS CHECK
            const isApproved = s.status === 'Onaylandı';

            // PRIVACY CHECK
            const isMine = s.employeeId === currentUser.id;

            // Return logic:
            // Must be in time range AND approved.
            // AND (User is Admin OR Record belongs to User)
            return inTime && isApproved && (isAdmin || isMine);
        });
    }, [salesData, timeFilter, isAdmin, currentUser]);


    // Statistics based on filtered data (Private View)
    const stats = useMemo(() => {
        const totalSales = filteredData.reduce((acc, curr) => acc + curr.quantity, 0);

        // Group by Branch (If staff, likely just their branch, if Admin, all branches)
        const branchMap: Record<string, number> = {};
        filteredData.forEach(s => {
            const branchName = s.branch || 'Bilinmiyor';
            branchMap[branchName] = (branchMap[branchName] || 0) + s.quantity;
        });
        const topBranchName = Object.keys(branchMap).sort((a, b) => branchMap[b] - branchMap[a])[0];

        // Group by Product
        const productMap: Record<string, number> = {};
        filteredData.forEach(s => {
            const prodName = s.productName || 'Bilinmiyor';
            productMap[prodName] = (productMap[prodName] || 0) + s.quantity;
        });
        const topProductName = Object.keys(productMap).sort((a, b) => productMap[b] - productMap[a])[0];

        // Chart Data (Branch)
        const chartData = Object.entries(branchMap).map(([name, value]) => ({ name, value })).sort((a,b) => b.value - a.value);

        return { 
            totalSales, 
            topBranchName, 
            topBranchCount: branchMap[topBranchName] || 0, 
            topProductName, 
            topProductCount: productMap[topProductName] || 0, 
            chartData 
        };
    }, [filteredData]);

    return (
        <div className="h-full w-full p-4 md:p-8 overflow-y-auto custom-scrollbar bg-[#09090b]">
            {/* Header */}
            <div className="mb-8 flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
                <div>
                    <h1 className="text-3xl font-bold text-white tracking-tight mb-2 flex items-center gap-3">
                        <ShoppingBag className="text-orange-500" size={32} />
                        {t('sales.title')}
                    </h1>
                    <p className="text-zinc-400 text-sm flex items-center gap-2">
                        <Activity size={14} className="text-green-500" />
                        {isAdmin ? t('sales.subtitle') : `${t('sales.subtitle')} (Kişisel Verileriniz)`}
                    </p>
                </div>

                <div className="flex bg-zinc-900 p-1 rounded-xl border border-zinc-800">
                    {(['WEEKLY', 'MONTHLY', 'YEARLY'] as TimeFilter[]).map(tf => (
                        <button
                            key={tf}
                            onClick={() => setTimeFilter(tf)}
                            className={`px-4 py-2 text-xs font-bold rounded-lg transition-all ${timeFilter === tf ? 'bg-orange-600 text-white shadow-lg shadow-orange-900/40' : 'text-zinc-500 hover:text-zinc-300'}`}
                        >
                            {tf === 'WEEKLY' ? t('sales.weekly') : tf === 'MONTHLY' ? t('sales.monthly') : t('sales.yearly')}
                        </button>
                    ))}
                </div>
            </div>

            {/* Top Stats Cards */}
            <div className={`grid grid-cols-1 ${isAdmin ? 'md:grid-cols-3' : 'md:grid-cols-2'} gap-6 mb-8`}>
                {/* Card 1: Total Sales */}
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl flex items-center gap-6 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-orange-500/10 rounded-full blur-2xl group-hover:bg-orange-500/20 transition-all"></div>
                    <div className="w-16 h-16 rounded-2xl bg-orange-500/20 flex items-center justify-center text-orange-500 border border-orange-500/30">
                        <TrendingUp size={32} />
                    </div>
                    <div>
                        <p className="text-sm text-zinc-500 font-bold uppercase tracking-wider">{isAdmin ? t('sales.totalSales') : 'Sizin Satışınız'}</p>
                        <p className="text-4xl font-bold text-white mt-1">{stats.totalSales}</p>
                    </div>
                </div>

                {/* Card 2: Top Branch (Or User Branch if staff) - ONLY FOR ADMIN */}
                {isAdmin && (
                    <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl flex items-center gap-6 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 w-24 h-24 bg-blue-500/10 rounded-full blur-2xl group-hover:bg-blue-500/20 transition-all"></div>
                        <div className="w-16 h-16 rounded-2xl bg-blue-500/20 flex items-center justify-center text-blue-500 border border-blue-500/30">
                            <MapPin size={32} />
                        </div>
                        <div>
                            <p className="text-sm text-zinc-500 font-bold uppercase tracking-wider">{t('sales.topBranch')}</p>
                            <div className="flex items-baseline gap-2">
                                <p className="text-2xl font-bold text-white mt-1">{stats.topBranchName || '-'}</p>
                                <span className="text-xs text-zinc-400">({stats.topBranchCount})</span>
                            </div>
                        </div>
                    </div>
                )}

                {/* Card 3: Top Product */}
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl flex items-center gap-6 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-purple-500/10 rounded-full blur-2xl group-hover:bg-purple-500/20 transition-all"></div>
                    <div className="w-16 h-16 rounded-2xl bg-purple-500/20 flex items-center justify-center text-purple-500 border border-purple-500/30">
                        <Package size={32} />
                    </div>
                    <div>
                        <p className="text-sm text-zinc-500 font-bold uppercase tracking-wider">{t('sales.topProduct')}</p>
                        <div className="flex items-baseline gap-2">
                            <p className="text-2xl font-bold text-white mt-1">{stats.topProductName || '-'}</p>
                            <span className="text-xs text-zinc-400">({stats.topProductCount})</span>
                        </div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left: Branch Chart */}
                <div className="lg:col-span-2 bg-zinc-900/30 border border-zinc-800 rounded-3xl p-6">
                    <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                        <BarChart3 className="text-indigo-500" size={20}/>
                        {t('sales.branchChart')}
                    </h3>
                    <div className="h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={stats.chartData}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#27272a" vertical={false} />
                                <XAxis dataKey="name" stroke="#71717a" fontSize={12} tickLine={false} axisLine={false} dy={10}/>
                                <YAxis stroke="#71717a" fontSize={12} tickLine={false} axisLine={false} />
                                <Tooltip 
                                    cursor={{fill: '#27272a', opacity: 0.4}}
                                    contentStyle={{ backgroundColor: '#09090b', border: '1px solid #27272a', borderRadius: '12px', color: '#fff' }}
                                />
                                <Bar dataKey="value" fill="#f97316" radius={[4, 4, 0, 0]} barSize={40}>
                                    {stats.chartData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={index === 0 ? '#f97316' : '#3f3f46'} />
                                    ))}
                                </Bar>
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Right: Personnel Leaderboard (WITH PRIVACY MASKING) */}
                <div className="bg-zinc-900/30 border border-zinc-800 rounded-3xl p-6 flex flex-col">
                    <div className="mb-6">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            <Trophy className="text-yellow-500" size={20}/>
                            {t('sales.leaderboard')}
                        </h3>
                        {!isAdmin && <p className="text-[10px] text-zinc-500 mt-1">Sıralama geneldir, diğer isimler gizlenmiştir.</p>}
                    </div>

                    <div className="flex-1 space-y-4">
                        {(leaderboardData || []).length === 0 ? (
                            <p className="text-center text-zinc-500 text-sm py-10">Veri yok.</p>
                        ) : (
                            (leaderboardData || []).map((item, index) => {
                                if(!item) return null;

                                // Privacy Logic: Show details only if Admin OR if it's me
                                const isMe = item.id === currentUser.id;
                                const showDetails = isAdmin || isMe;

                                return (
                                    <div key={item.id} className={`flex items-center gap-4 p-3 rounded-xl border transition-colors ${isMe ? 'bg-indigo-900/20 border-indigo-500/30 shadow-lg shadow-indigo-900/10' : 'bg-zinc-900/50 border-zinc-800 hover:border-zinc-700'}`}>
                                        <div className="relative font-bold text-lg w-6 text-center text-zinc-500">
                                            {index === 0 ? <Medal size={24} className="text-yellow-500"/> : 
                                            index === 1 ? <Medal size={24} className="text-zinc-400"/> : 
                                            index === 2 ? <Medal size={24} className="text-amber-700"/> : 
                                            index + 1}
                                        </div>
                                        <div className="w-10 h-10 rounded-full border border-zinc-700 bg-zinc-800 flex items-center justify-center overflow-hidden">
                                            {showDetails && item.avatar ? (
                                                <img src={item.avatar} alt={item.name} className="w-full h-full object-cover" />
                                            ) : (
                                                // Anonymous Icon
                                                <EyeOff size={16} className="text-zinc-600"/>
                                            )}
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <p className={`text-sm font-bold truncate ${isMe ? 'text-indigo-400' : 'text-zinc-300'}`}>
                                                {showDetails ? item.name : '??????'} {isMe && '(Siz)'}
                                            </p>
                                            <p className="text-xs text-zinc-500">
                                                {showDetails ? item.branch : '???'}
                                            </p>
                                        </div>
                                        <div className="text-right">
                                            {/* Count is always visible as requested */}
                                            <span className="block text-lg font-bold text-orange-500">{item.count}</span>
                                            <span className="text-[10px] text-zinc-600 uppercase">Satış</span>
                                        </div>
                                    </div>
                                )
                            })
                        )}
                    </div>
                </div>
            </div>

            {/* Detailed Table (Private View) */}
            <div className="mt-8 bg-zinc-900/30 border border-zinc-800 rounded-3xl overflow-hidden">
                <div className="p-6 border-b border-zinc-800 flex items-center justify-between">
                    <h3 className="text-lg font-bold text-white flex items-center gap-2">
                        <ListTodo className="text-blue-500" size={20}/>
                        {t('sales.tableTitle')} {isAdmin ? '' : '(Kayıtlarınız)'}
                    </h3>
                    <span className="text-xs text-zinc-500">{filteredData.length} Kayıt</span>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead>
                            <tr className="text-left text-xs font-bold text-zinc-500 uppercase bg-zinc-950/50 border-b border-zinc-800">
                                <th className="p-4">{t('sales.date')}</th>
                                <th className="p-4">{t('sales.personnel')}</th>
                                <th className="p-4">{t('sales.branch')}</th>
                                <th className="p-4">{t('sales.product')}</th>
                                <th className="p-4 text-center">{t('sales.quantity')}</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-zinc-800">
                            {filteredData.slice(0, 20).map((log) => {
                                const emp = employees.find(e => e.id === log.employeeId);

                                // HIDE DELETED PRODUCTS / RECORDS WHERE EMPLOYEE IS MISSING
                                if (!emp) return null;

                                return (
                                    <tr key={log.id} className="text-sm text-zinc-300 hover:bg-zinc-800/30 transition-colors">
                                        <td className="p-4 font-mono text-zinc-500">{formatDate(log.saleDate)}</td>
                                        <td className="p-4 font-bold text-white flex items-center gap-2">
                                            <div className="w-6 h-6 rounded-full bg-zinc-800 flex items-center justify-center text-[10px] overflow-hidden border border-zinc-700">
                                                {emp.avatarUrl ? (
                                                    <img src={emp.avatarUrl} className="w-full h-full object-cover"/>
                                                ) : (
                                                    log.employeeId ? log.employeeId.slice(0,1).toUpperCase() : '?'
                                                )}
                                            </div>
                                            {emp.name}
                                        </td>
                                        <td className="p-4 text-orange-400">{log.branch}</td>
                                        <td className="p-4 text-white font-medium">{log.productName}</td>
                                        <td className="p-4 text-center font-mono font-bold">{log.quantity}</td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default SalesDashboard;

import React, { ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  private handleReset = () => {
      this.setState({ hasError: false, error: null });
      window.location.href = '/'; // Hard reload to clear state
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen w-full bg-zinc-950 flex flex-col items-center justify-center p-4 text-center">
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center">
                <div className="w-16 h-16 bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mb-4 border border-red-500/20">
                    <AlertTriangle size={32} />
                </div>
                <h1 className="text-xl font-bold text-white mb-2">Bir Sorun Oluştu</h1>
                <p className="text-zinc-400 text-sm mb-6">
                    Sistem beklenmeyen bir veri durumuyla karşılaştı. Bu genellikle veritabanı bağlantısı veya eksik veriden kaynaklanır.
                </p>

                <div className="bg-black/30 p-3 rounded-lg border border-zinc-800 w-full mb-6 text-left overflow-hidden">
                    <p className="text-[10px] text-red-400 font-mono break-all">
                        {this.state.error?.message || 'Unknown Error'}
                    </p>
                </div>

                <button 
                    onClick={this.handleReset}
                    className="flex items-center gap-2 px-6 py-3 bg-white text-black hover:bg-zinc-200 font-bold rounded-xl transition-colors w-full justify-center"
                >
                    <RefreshCw size={18} /> Sistemi Yenile
                </button>
            </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
    };
  }

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  private handleReset = () => {
      this.setState({ hasError: false, error: null });
      window.location.href = '/'; // Hard reload to clear state
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen w-full bg-zinc-950 flex flex-col items-center justify-center p-4 text-center">
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center">
                <div className="w-16 h-16 bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mb-4 border border-red-500/20">
                    <AlertTriangle size={32} />
                </div>
                <h1 className="text-xl font-bold text-white mb-2">Bir Sorun Oluştu</h1>
                <p className="text-zinc-400 text-sm mb-6">
                    Sistem beklenmeyen bir veri durumuyla karşılaştı. Bu genellikle veritabanı bağlantısı veya eksik veriden kaynaklanır.
                </p>

                <div className="bg-black/30 p-3 rounded-lg border border-zinc-800 w-full mb-6 text-left overflow-hidden">
                    <p className="text-[10px] text-red-400 font-mono break-all">
                        {this.state.error?.message || 'Unknown Error'}
                    </p>
                </div>

                <button 
                    onClick={this.handleReset}
                    className="flex items-center gap-2 px-6 py-3 bg-white text-black hover:bg-zinc-200 font-bold rounded-xl transition-colors w-full justify-center"
                >
                    <RefreshCw size={18} /> Sistemi Yenile
                </button>
            </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useEffect, useRef } from 'react';
import { Message, Employee, Role } from '../types';
import { Search, Send, Mail, ChevronLeft, MessageSquare, Plus, X, Loader2, Check, CheckCheck, ShieldAlert, Trash2 } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface MessagesProps {
    currentUser: Employee;
}

const ADMIN_BOARD_ID = 'ADMIN_BOARD';

const Messages: React.FC<MessagesProps> = ({ currentUser }) => {
    // Mesaj Listesi (Sol Panel)
    const [messages, setMessages] = useState<Message[]>([]);

    // Aktif Sohbet
    const [activeChatPartnerId, setActiveChatPartnerId] = useState<string | null>(null);
    const [conversation, setConversation] = useState<Message[]>([]);

    const [isLoading, setIsLoading] = useState(true);
    const [loadingConversation, setLoadingConversation] = useState(false);
    const [replyText, setReplyText] = useState('');
    const [isSending, setIsSending] = useState(false);

    const scrollRef = useRef<HTMLDivElement>(null);

    const { t } = useLanguage();

    // Gerçek kullanıcı listesi
    const [recipientList, setRecipientList] = useState<Employee[]>([]);

    // Compose Modal
    const [showCompose, setShowCompose] = useState(false);
    const [composeForm, setComposeForm] = useState({
        receiverId: '',
        subject: '',
        content: ''
    });

    // Helper: ID'den İsim Bulma
    const getName = (id: string) => {
        if (id === currentUser.id) return 'Ben';
        if (id === 'ALL') return '📢 Tüm Personel';
        if (id === ADMIN_BOARD_ID) return '🏢 Yönetim Ekibi';
        const user = recipientList.find(e => e.id === id);
        return user ? user.name : 'Bilinmeyen Kullanıcı';
    };

    // Helper: ID'den Profil Resmi Bulma
    const getAvatar = (id: string) => {
        if (id === ADMIN_BOARD_ID) return null; // Özel ikon kullanılacak
        const user = recipientList.find(e => e.id === id);
        return user ? user.avatarUrl : null;
    };

    // Helper: Admin mi kontrolü
    const isAdmin = (id: string) => {
        const user = recipientList.find(e => e.id === id);
        return user?.role === Role.ADMIN;
    };

    // 1. Başlangıç Verilerini Çek
    useEffect(() => {
        fetchPotentialRecipients().then(() => {
            // Recipient list yüklendikten sonra mesajları çek ki Admin check yapabilelim
            fetchMessages(); 
        });
    }, [currentUser]);

    // 2. Realtime Aboneliği
    useEffect(() => {
        const channel = supabase.channel('messages-core')
            .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages' }, (payload) => {
                const newMsg = payload.new;

                // Realtime filtreleme:
                // 1. Bana geldi (receiver_id = me)
                // 2. Ben attım (sender_id = me)
                // 3. Herkese atıldı (ALL)
                // 4. ADMIN ise ve mesaj ADMIN_BOARD'a atıldıysa

                let isRelevant = false;

                if (newMsg.receiver_id === currentUser.id || newMsg.sender_id === currentUser.id || newMsg.receiver_id === 'ALL') {
                    isRelevant = true;
                } else if (currentUser.role === Role.ADMIN && newMsg.receiver_id === ADMIN_BOARD_ID) {
                    isRelevant = true;
                }

                if (isRelevant) {
                     fetchMessages();

                     // Aktif sohbet güncelleme mantığı
                     if (activeChatPartnerId) {
                         // Eğer Personel isem ve 'ADMIN_BOARD' açıksa:
                         // Gelen mesaj Admin'den bana ise VEYA ben Admin'e attıysam
                         if (currentUser.role !== Role.ADMIN && activeChatPartnerId === ADMIN_BOARD_ID) {
                             if (newMsg.receiver_id === currentUser.id || newMsg.receiver_id === ADMIN_BOARD_ID) {
                                 fetchConversation(ADMIN_BOARD_ID);
                             }
                         }
                         // Eğer Admin isem:
                         else {
                             // Mesajı atan şu an konuştuğum kişiyse (veya ben ona attıysam)
                             const senderIsActive = newMsg.sender_id === activeChatPartnerId;
                             const receiverIsActive = newMsg.receiver_id === activeChatPartnerId;

                             // Admin olarak ben Staff'a cevap yazdıysam
                             const iRepliedToActive = newMsg.sender_id === currentUser.id && newMsg.receiver_id === activeChatPartnerId;

                             // Staff, ADMIN_BOARD'a yazdıysa ve ben o Staff ile konuşuyorsam
                             const staffWroteToBoard = newMsg.sender_id === activeChatPartnerId && newMsg.receiver_id === ADMIN_BOARD_ID;

                             if (senderIsActive || receiverIsActive || iRepliedToActive || staffWroteToBoard) {
                                fetchConversation(activeChatPartnerId);
                             }
                         }
                     }
                }
            })
            .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'messages' }, () => {
                fetchMessages(); 
                if(activeChatPartnerId) fetchConversation(activeChatPartnerId);
            })
            .on('postgres_changes', { event: 'DELETE', schema: 'public', table: 'messages' }, () => {
                // Silme durumunda listeyi yenile
                if(activeChatPartnerId) fetchConversation(activeChatPartnerId);
                fetchMessages();
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [currentUser, activeChatPartnerId]);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [conversation]);

    useEffect(() => {
        if (activeChatPartnerId) {
            fetchConversation(activeChatPartnerId);
        } else {
            setConversation([]);
        }
    }, [activeChatPartnerId]);

    const fetchPotentialRecipients = async () => {
        const { data } = await supabase.from('profiles').select('*');
        if (data) {
            const formattedEmps: Employee[] = data.map((e: any) => ({
                id: e.id,
                name: e.full_name,
                email: e.email,
                role: e.role as Role,
                branch: e.branch,
                hourlyRate: e.hourly_rate,
                taxClass: e.tax_class,
                avatarUrl: e.avatar_url || `https://ui-avatars.com/api/?name=${e.full_name}`,
                advances: 0,
                phone: e.phone,
                bio: e.bio,
                badges: [],
                tags: [],
                metrics: e.metrics
            }));
            setRecipientList(formattedEmps);
        }
    };

    const fetchMessages = async () => {
        try {
            let query = supabase.from('messages').select('*').order('timestamp', { ascending: false });

            // SORGULAMA MANTIĞI:
            if (currentUser.role === Role.ADMIN) {
                // Admin: Kendisine gelen, Kendisinin attığı, ALL, ve ADMIN_BOARD'a gelenler
                query = query.or(`receiver_id.eq.${currentUser.id},sender_id.eq.${currentUser.id},receiver_id.eq.ALL,receiver_id.eq.${ADMIN_BOARD_ID}`);
            } else {
                // Personel: Kendisine gelen, Kendisinin attığı, ALL
                // (Personel ADMIN_BOARD'a attığında sender_id kendisi olduğu için zaten gelir)
                query = query.or(`receiver_id.eq.${currentUser.id},sender_id.eq.${currentUser.id},receiver_id.eq.ALL`);
            }

            const { data, error } = await query;
            if (error) throw error;

            const formattedMessages: Message[] = (data || []).map((m: any) => ({
                id: m.id,
                senderId: m.sender_id,
                receiverId: m.receiver_id,
                subject: m.subject,
                content: m.content,
                timestamp: m.timestamp,
                read: m.read
            }));

            // --- GRUPLAMA MANTIĞI ---
            const uniqueChats: Message[] = [];
            const seenPartners = new Set();

            formattedMessages.forEach(msg => {
                let partnerId = '';

                if (currentUser.role === Role.ADMIN) {
                    // ADMIN GÖZÜNDEN:
                    if (msg.receiverId === 'ALL') {
                        partnerId = 'ALL';
                    } else if (msg.receiverId === ADMIN_BOARD_ID) {
                        // Eğer mesaj Yönetim Havuzuna geldiyse, partner gönderen personeldir.
                        partnerId = msg.senderId;
                    } else if (msg.senderId === currentUser.id) {
                        // Ben birine attım, partner alıcıdır.
                        partnerId = msg.receiverId;
                    } else {
                        // Biri bana attı (Özel mesaj varsa)
                        partnerId = msg.senderId;
                    }
                } else {
                    // PERSONEL GÖZÜNDEN:
                    if (msg.receiverId === 'ALL') {
                        partnerId = 'ALL';
                    } else {
                        // Diğer tüm durumlar (Benim yönetime attığım veya Yönetimin bana attığı)
                        // Tek bir çatı altında toplanmalı: 'ADMIN_BOARD'
                        partnerId = ADMIN_BOARD_ID;
                    }
                }

                // Kendi kendime mesajlaşmayı engelle (Nadir durum)
                if (partnerId === currentUser.id) return;

                if (partnerId && !seenPartners.has(partnerId)) {
                    seenPartners.add(partnerId);
                    uniqueChats.push(msg);
                }
            });

            setMessages(uniqueChats);
            setIsLoading(false);
        } catch (error) {
            console.error("Mesajlar alınamadı:", error);
            setIsLoading(false);
        }
    };

    const fetchConversation = async (partnerId: string) => {
        if(conversation.length === 0) setLoadingConversation(true);

        try {
            let query = supabase.from('messages').select('*').order('timestamp', { ascending: true });

            if (partnerId === 'ALL') {
                query = query.eq('receiver_id', 'ALL');
            } else if (currentUser.role === Role.ADMIN) {
                // ADMIN OLARAK SOHBET GEÇMİŞİ (REVİZE EDİLDİ):
                // 1. Partnerin ADMIN_BOARD'a attıkları (Ortak Havuz)
                // 2. Partnerin BANA attıkları
                // 3. BENİM Partnere attıklarım
                // 4. (ÇIKARILDI) -> BAŞKA ADMİNLERİN Partnere attıkları (Gizlilik Kuralı)
                query = query.or(`and(sender_id.eq.${partnerId},receiver_id.eq.${ADMIN_BOARD_ID}),and(sender_id.eq.${partnerId},receiver_id.eq.${currentUser.id}),and(sender_id.eq.${currentUser.id},receiver_id.eq.${partnerId})`);
            } else {
                // PERSONEL OLARAK SOHBET GEÇMİŞİ (partnerId = ADMIN_BOARD):
                // 1. BENİM ADMIN_BOARD'a attıklarım
                // 2. HERHANGİ BİR ADMININ BANA attıkları (receiver_id = ME)
                if (partnerId === ADMIN_BOARD_ID) {
                     query = query.or(`and(sender_id.eq.${currentUser.id},receiver_id.eq.${ADMIN_BOARD_ID}),receiver_id.eq.${currentUser.id}`);
                }
            }

            const { data, error } = await query;
            if (error) throw error;

            const formattedConv: Message[] = (data || []).map((m: any) => ({
                id: m.id,
                senderId: m.sender_id,
                receiverId: m.receiver_id,
                subject: m.subject,
                content: m.content,
                timestamp: m.timestamp,
                read: m.read
            }));

            // Sadece ADMIN_BOARD dışı mesajları filtrele (Personel için ALL karışmasın)
            const cleanConv = partnerId === 'ALL' 
                ? formattedConv 
                : formattedConv.filter(m => m.receiverId !== 'ALL');

            setConversation(cleanConv);

            // Okundu İşaretleme
            if (partnerId !== 'ALL') {
                const unreadMsgIds = cleanConv
                    .filter(m => !m.read && m.senderId !== currentUser.id) // Başkası attıysa ve okunmadıysa
                    .map(m => m.id);

                if (unreadMsgIds.length > 0) {
                    await supabase.from('messages').update({ read: true }).in('id', unreadMsgIds);
                    fetchMessages(); 
                }
            }

        } catch (err) {
            console.error("Sohbet geçmişi hatası:", err);
        } finally {
            setLoadingConversation(false);
        }
    };

    const handleSelectChat = (msg: Message) => {
        let partnerId = '';
        if (currentUser.role === Role.ADMIN) {
            if (msg.receiverId === 'ALL') partnerId = 'ALL';
            else if (msg.receiverId === ADMIN_BOARD_ID) partnerId = msg.senderId;
            else if (msg.senderId === currentUser.id) partnerId = msg.receiverId;
            else partnerId = msg.senderId;
        } else {
            if (msg.receiverId === 'ALL') partnerId = 'ALL';
            else partnerId = ADMIN_BOARD_ID;
        }
        setActiveChatPartnerId(partnerId);
    };

    const handleDeleteMessage = async (msgId: string) => {
        if (!confirm('Bu mesajı silmek istediğinize emin misiniz?')) return;
        try {
            const { error } = await supabase.from('messages').delete().eq('id', msgId);
            if (error) throw error;
            // Local update (Realtime will also handle this but this makes it snappier)
            setConversation(prev => prev.filter(m => m.id !== msgId));
        } catch (err: any) {
            alert('Silme hatası: ' + err.message);
        }
    };

    const handleSendReply = async () => {
        if (!replyText.trim() || !activeChatPartnerId) return;
        setIsSending(true);

        try {
            let receiver = activeChatPartnerId;

            // Eğer personel isem ve "Yönetim Ekibi" seçiliyse, mesaj ADMIN_BOARD'a gider.
            if (currentUser.role !== Role.ADMIN && activeChatPartnerId === ADMIN_BOARD_ID) {
                receiver = ADMIN_BOARD_ID;
            }

            const newMessage = {
                sender_id: currentUser.id,
                receiver_id: receiver,
                subject: 'Sohbet Mesajı',
                content: replyText,
                read: false
            };

            const { error } = await supabase.from('messages').insert([newMessage]);
            if (error) throw error;

            setReplyText('');

        } catch (err: any) {
            alert("Gönderilemedi: " + err.message);
        } finally {
            setIsSending(false);
        }
    };

    const handleComposeSend = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!composeForm.receiverId || !composeForm.content) {
            alert("Alıcı ve mesaj içeriği zorunludur.");
            return;
        }

        setIsSending(true);
        try {
            const newMessage = {
                sender_id: currentUser.id,
                receiver_id: composeForm.receiverId,
                subject: composeForm.subject || 'Yeni Mesaj',
                content: composeForm.content,
                read: false
            };

            const { error } = await supabase.from('messages').insert([newMessage]);
            if (error) throw error;

            setShowCompose(false);
            setComposeForm({ receiverId: '', subject: '', content: '' });
            alert("Mesaj gönderildi.");

            // Sohbete geçiş yap
            let nextPartner = composeForm.receiverId;
            // Personel Yönetime attıysa, sohbet ID'si ADMIN_BOARD_ID olur
            if (currentUser.role !== Role.ADMIN && composeForm.receiverId === ADMIN_BOARD_ID) {
                nextPartner = ADMIN_BOARD_ID;
            }
            setActiveChatPartnerId(nextPartner);

        } catch (err: any) {
            alert("Hata: " + err.message);
        } finally {
            setIsSending(false);
        }
    };

    const handleOpenCompose = () => {
        // Varsayılan alıcı: Admin değilse Yönetim, Adminse boş
        const defaultReceiver = currentUser.role !== Role.ADMIN ? ADMIN_BOARD_ID : '';
        setComposeForm({ receiverId: defaultReceiver, subject: '', content: '' });
        setShowCompose(true);
    };

    // UI Helpers: Compose Dropdown Listesi
    const filteredRecipients = recipientList.filter(user => {
        if (user.id === currentUser.id) return false;
        // Personel sadece Yönetim'e atabilir (Dropdown'da özel seçenek olacak)
        // Admin herkese atabilir.
        return currentUser.role === Role.ADMIN;
    });

    return (
        <div className="flex h-full flex-col md:flex-row relative overflow-hidden bg-zinc-950">

            {/* COMPOSE MODAL */}
            {showCompose && (
                <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
                    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95">
                        <div className="p-5 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/50">
                            <h3 className="text-lg font-bold text-white flex items-center gap-2">
                                <Mail size={20} className="text-indigo-500" /> {t('msg.compose')}
                            </h3>
                            <button onClick={() => setShowCompose(false)} className="text-zinc-500 hover:text-white"><X size={20} /></button>
                        </div>
                        <form onSubmit={handleComposeSend} className="p-6 space-y-4">
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-zinc-400">{t('msg.recipient')}</label>
                                <select 
                                    value={composeForm.receiverId} 
                                    onChange={e => setComposeForm({...composeForm, receiverId: e.target.value})}
                                    className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-2.5 text-sm text-white focus:border-indigo-500 outline-none"
                                >
                                    {/* Personel için tek seçenek */}
                                    {currentUser.role !== Role.ADMIN && (
                                        <option value={ADMIN_BOARD_ID}>🏢 Yönetim Ekibi (Admin)</option>
                                    )}

                                    {/* Admin için seçenekler */}
                                    {currentUser.role === Role.ADMIN && (
                                        <>
                                            <option value="" disabled>Seçiniz</option>
                                            <option value="ALL">📢 Tüm Personel (Duyuru)</option>
                                            {filteredRecipients.map(emp => (
                                                <option key={emp.id} value={emp.id}>{emp.name} — {emp.branch}</option>
                                            ))}
                                        </>
                                    )}
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-zinc-400">{t('msg.subject')} (Opsiyonel)</label>
                                <input 
                                    type="text" 
                                    value={composeForm.subject}
                                    onChange={e => setComposeForm({...composeForm, subject: e.target.value})}
                                    className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-2.5 text-sm text-white focus:border-indigo-500 outline-none"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-zinc-400">{t('msg.content')}</label>
                                <textarea 
                                    value={composeForm.content}
                                    onChange={e => setComposeForm({...composeForm, content: e.target.value})}
                                    className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-2.5 text-sm text-white focus:border-indigo-500 outline-none min-h-[100px]"
                                />
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSending}
                                className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-medium shadow-lg flex items-center justify-center gap-2"
                            >
                                {isSending ? <Loader2 className="animate-spin" size={18}/> : t('msg.send')}
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* LIST PANEL (SOL) */}
            <div className={`w-full md:w-1/3 min-w-[300px] border-r border-zinc-800 flex flex-col bg-zinc-950/50 absolute md:relative inset-0 z-10 md:z-auto transition-transform duration-300 ${activeChatPartnerId ? '-translate-x-full md:translate-x-0' : 'translate-x-0'}`}>
                <div className="p-4 border-b border-zinc-800">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="font-bold text-white text-lg">{t('msg.chats')}</h2>
                        <button onClick={handleOpenCompose} className="bg-indigo-600 p-2 rounded-lg text-white hover:bg-indigo-500 shadow-lg flex items-center gap-2 px-3">
                            <Plus size={18} /> <span className="text-xs font-bold">{t('msg.new')}</span>
                        </button>
                    </div>
                    <div className="relative">
                        <Search size={16} className="absolute left-3 top-2.5 text-zinc-500" />
                        <input type="text" placeholder={t('msg.search')} className="w-full bg-zinc-900 border border-zinc-800 rounded-xl pl-9 pr-4 py-2.5 text-sm focus:border-indigo-500 outline-none text-zinc-300" />
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto custom-scrollbar">
                    {isLoading ? (
                        <div className="flex justify-center p-8"><Loader2 className="animate-spin text-zinc-500"/></div>
                    ) : messages.length === 0 ? (
                        <div className="text-center p-8 text-zinc-600 text-sm">{t('msg.empty')}</div>
                    ) : (
                        messages.map(msg => {
                            const isMe = msg.senderId === currentUser.id;

                            let partnerId = '';
                            if (currentUser.role === Role.ADMIN) {
                                if (msg.receiverId === 'ALL') partnerId = 'ALL';
                                else if (msg.receiverId === ADMIN_BOARD_ID) partnerId = msg.senderId;
                                else if (isMe) partnerId = msg.receiverId;
                                else partnerId = msg.senderId;
                            } else {
