                                </div>
                                <div className="flex-1 w-full">
                                    <label className="text-xs text-zinc-400 block mb-1.5">Ürün</label>
                                    <select value={salesForm.product} onChange={e => setSalesForm({...salesForm, product: e.target.value})} className="bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-white focus:border-orange-500 outline-none w-full">
                                        {AKTION_PRODUCTS.map(p => <option key={p} value={p}>{p}</option>)}
                                    </select>
                                </div>
                                <div className="w-full md:w-32">
                                    <label className="text-xs text-zinc-400 block mb-1.5">Adet</label>
                                    <input type="number" min="1" required value={salesForm.quantity} onChange={e => setSalesForm({...salesForm, quantity: parseInt(e.target.value)})} className="bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-white focus:border-orange-500 outline-none w-full"/>
                                </div>
                                <button type="submit" disabled={isSaving} className="w-full md:w-auto px-6 py-2.5 bg-orange-600 hover:bg-orange-500 text-white font-bold rounded-lg transition-colors flex items-center justify-center gap-2">
                                    {isSaving ? <Loader2 className="animate-spin" size={18}/> : <Plus size={18}/>}<span>Ekle</span>
                                </button>
                            </form>
                        </div>

                        {/* 2. STAFF: MY SALES TABLE (REPLACED GRID) */}
                        <div className="bg-zinc-900 border border-zinc-800 rounded-xl overflow-hidden mt-6 shadow-lg">
                            <div className="p-5 border-b border-zinc-800 flex items-center gap-2 bg-zinc-950/50">
                                <List size={18} className="text-zinc-400" />
                                <h3 className="text-sm font-bold text-zinc-300">Satış Kayıtları (Son Eklenenler)</h3>
                            </div>
                            <div className="overflow-x-auto">
                                <table className="w-full">
                                    <thead>
                                        <tr className="text-left text-xs text-zinc-500 bg-zinc-950/30 border-b border-zinc-800">
                                            <th className="p-4 font-bold uppercase w-32">Tarih</th>
                                            <th className="p-4 font-bold uppercase">Personel</th>
                                            <th className="p-4 font-bold uppercase">Ürün</th>
                                            <th className="p-4 font-bold uppercase text-center w-24">Adet</th>
                                            <th className="p-4 font-bold uppercase text-center w-20">İşlem</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-zinc-800">
                                        {salesLogs.length === 0 ? (
                                            <tr>
                                                <td colSpan={5} className="p-8 text-center text-zinc-500 italic">
                                                    Bu dönemde satış kaydınız bulunmuyor.
                                                </td>
                                            </tr>
                                        ) : (
                                            salesLogs.map(log => {
                                                const emp = availableEmployees.find(e => e.id === log.employeeId) || currentUser; // Fallback to current user if not found in list (e.g. self)
                                                return (
                                                    <tr key={log.id} className="group hover:bg-zinc-800/30 transition-colors">
                                                        <td className="p-4 text-sm font-bold text-white font-mono">
                                                            {formatDate(log.saleDate)}
                                                        </td>
                                                        <td className="p-4">
                                                            <div className="flex items-center gap-3">
                                                                <div className="w-8 h-8 rounded-full bg-orange-600/20 text-orange-500 flex items-center justify-center text-xs font-bold border border-orange-500/30">
                                                                    {emp.name.substring(0, 2).toUpperCase()}
                                                                </div>
                                                                <span className="text-sm font-bold text-zinc-200">{emp.name}</span>
                                                            </div>
                                                        </td>
                                                        <td className="p-4">
                                                            <span className="text-sm text-orange-400 font-medium">{log.productName}</span>
                                                        </td>
                                                        <td className="p-4 text-center">
                                                            <span className="text-sm font-bold text-white">{log.quantity}</span>
                                                        </td>
                                                        <td className="p-4 text-center">
                                                            {log.status === 'Bekliyor' ? (
                                                                <button 
                                                                    onClick={() => handleDeleteSale(log.id)}
                                                                    className="p-2 text-zinc-500 hover:text-red-400 hover:bg-red-900/10 rounded-lg transition-all"
                                                                    title="Sil"
                                                                >
                                                                    <Trash2 size={16} />
                                                                </button>
                                                            ) : (
                                                                <span className={`text-[10px] font-bold ${log.status === 'Onaylandı' ? 'text-green-500' : 'text-red-500'}`}>{log.status}</span>
                                                            )}
                                                        </td>
                                                    </tr>
                                                );
                                            })
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

