import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

// Define the interface for props to include children
interface Props {
  children?: ReactNode;
}

// Define the interface for state
interface State {
  hasError: boolean;
  error: Error | null;
}

// Fix: Explicitly import and extend Component to resolve type issues where setState and props were not recognized
class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Log the error to an error reporting service
    console.error('Uncaught error:', error, errorInfo);
  }

  private handleReset = () => {
      // Fix: Resetting the error state using the inherited setState method
      this.setState({ hasError: false, error: null });
      window.location.href = '/'; // Hard reload to clear state
  }

  public render() {
    if (this.state.hasError) {
      // Render a custom fallback UI when an error occurs
      return (
        <div className="min-h-screen w-full bg-zinc-950 flex flex-col items-center justify-center p-4 text-center">
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center">
                <div className="w-16 h-16 bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mb-4 border border-red-500/20">
                    <AlertTriangle size={32} />
                </div>
                <h1 className="text-xl font-bold text-white mb-2">Bir Sorun Oluştu</h1>
                <p className="text-zinc-400 text-sm mb-6">
                    Sistem beklenmeyen bir veri durumuyla karşılaştı. Bu genellikle veritabanı bağlantısı veya eksik veriden kaynaklanır.
                </p>

                <div className="bg-black/30 p-3 rounded-lg border border-zinc-800 w-full mb-6 text-left overflow-hidden">
                    <p className="text-[10px] text-red-400 font-mono break-all">
                        {this.state.error?.message || 'Unknown Error'}
                    </p>
                </div>

                <button 
                    onClick={this.handleReset}
                    className="flex items-center gap-2 px-6 py-3 bg-white text-black hover:bg-zinc-200 font-bold rounded-xl transition-colors w-full justify-center"
                >
                    <RefreshCw size={18} /> Sistemi Yenile
                </button>
            </div>
        </div>
      );
    }

    // Fix: Access props correctly as inherited from Component
    return this.props.children;
  }
}

export default ErrorBoundary;

import { GoogleGenAI } from "@google/genai";

// Basit bir önbellek mekanizması (Aynı metni tekrar tekrar sormamak için)
const translationCache: Record<string, string> = {};

// Demo Modu için Sözlük (API Key olmadığı durumlar için)
const DEMO_DICTIONARY: Record<string, string> = {
    "Hata düzelt": "Fehler beheben",
    "Sigorta teyit": "Versicherung bestätigen",
    "Fatura": "Rechnung",
    "Faturalar toplanacak": "Rechnungen werden gesammelt",
    "Sisteme giriş yapılacak": "Eingabe in das System",
    "Ön muhasebe girişi yapılacak": "Vorbuchhaltungseintrag wird erstellt",
    "Factoring ile fatura giriş": "Rechnungseingabe mit Factoring",
    "Pefra faturaları": "Pefra Rechnungen",
    "Melisa Gold montaj": "Melisa Gold Montage",
    "Tabela montaj": "Schildermontage"
};

export const translateContent = async (text: string, targetLang: 'tr' | 'de'): Promise<string> => {
    // 1. Boş metin kontrolü
    if (!text || !text.trim()) return text;

    // 2. Önbellek kontrolü
    const cacheKey = `${text}_${targetLang}`;
    if (translationCache[cacheKey]) {
        return translationCache[cacheKey];
    }

    // 3. Hedef dil Türkçe ise ve metin zaten Türkçe gibiyse (basit varsayım) çevirme
    // (Gerçek uygulamada kaynak dil tespiti daha karmaşık olabilir)
    if (targetLang === 'tr') {
        return text; 
    }

    // 4. Demo Sözlük Kontrolü (Hızlı tepki ve API keysiz çalışma için)
    if (targetLang === 'de' && DEMO_DICTIONARY[text]) {
        return DEMO_DICTIONARY[text];
    }

    try {
        // 5. Google Gemini API Çağrısı
        // Not: process.env.API_KEY tanımlı olmalıdır.
        if (process.env.API_KEY) {
            // Fix: Initialize GoogleGenAI with named parameter
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            const prompt = `Translate the following text to ${targetLang === 'de' ? 'German' : 'Turkish'}. Return only the translated text, do not add any explanations or quotes.\n\nText: "${text}"`;

            // Fix: Use ai.models.generateContent directly with the correct model and prompt
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: prompt,
            });

            // Fix: Access the text property directly (not a method)
            const result = response.text?.trim();
            if (result) {
                translationCache[cacheKey] = result;
                return result;
            }
        }

        // API Key yoksa simülasyon (Gerçek çeviri gibi görünmesi için)
        // Sadece demo amaçlı, metnin sonuna [DE] ekler.
        return new Promise((resolve) => {
            setTimeout(() => {
                const simulated = `[${targetLang.toUpperCase()}] ${text}`;
                translationCache[cacheKey] = simulated;
                resolve(simulated);
            }, 300); // Küçük bir gecikme ekle
        });

    } catch (error) {
        console.error("Translation error:", error);
        return text; // Hata durumunda orijinal metni döndür
    }
};

