                                <p className="text-orange-100 text-xs">Satış verilerinizi şubeniz üzerinden sisteme kaydedin.</p>
                            </div>
                            <form onSubmit={handleSaveSale} className="w-full lg:w-auto flex flex-wrap lg:flex-nowrap items-end gap-3">
                                <div className="flex-1 lg:w-40 min-w-[140px]">
                                    <input type="date" value={salesForm.date} onChange={e => setSalesForm({...salesForm, date: e.target.value})} className="w-full bg-orange-700/50 border border-orange-400/30 rounded-xl px-4 py-3 text-sm text-white outline-none focus:bg-orange-700" />
                                </div>
                                <div className="flex-[2] lg:w-64 min-w-[180px]">
                                    <select value={salesForm.product} onChange={e => setSalesForm({...salesForm, product: e.target.value})} className="w-full bg-orange-700/50 border border-orange-400/30 rounded-xl px-4 py-3 text-sm text-white outline-none focus:bg-orange-700">
                                        {AKTION_PRODUCTS.map(p => <option key={p} value={p} className="bg-orange-900">{p}</option>)}
                                    </select>
                                </div>
                                <div className="w-24">
                                    <input type="number" min="1" value={salesForm.quantity} onChange={e => setSalesForm({...salesForm, quantity: parseInt(e.target.value)})} className="w-full bg-orange-700/50 border border-orange-400/30 rounded-xl px-4 py-3 text-sm text-white font-bold text-center outline-none focus:bg-orange-700" />
                                </div>
                                <button type="submit" disabled={isSaving} className="px-6 py-3 bg-white text-orange-600 font-black rounded-xl hover:scale-105 active:scale-95 transition-all shadow-lg flex items-center gap-2">
                                    {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
                                    Ekle
                                </button>
                            </form>
                        </div>
                    </div>
                )}

                {/* SALES LIST (UNIFIED LIST VIEW) */}
                <div className="bg-zinc-900 border border-zinc-800 rounded-3xl overflow-hidden shadow-2xl">
                    <div className="p-6 border-b border-zinc-800 bg-zinc-950/50 flex justify-between items-center">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            <History size={20} className="text-indigo-400"/>
                            {isAdmin ? "Satış Geçmişi Raporu" : "Satış Geçmişim"}
                        </h3>
                        <span className="text-xs text-zinc-500 font-bold px-3 py-1 bg-zinc-900 rounded-full border border-zinc-800">
                            {salesLogs.length} Kayıt
                        </span>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-zinc-950 text-[10px] font-black text-zinc-500 uppercase tracking-widest border-b border-zinc-800">
                                <tr>
                                    <th className="p-4">Tarih</th>
                                    <th className="p-4">Personel</th>
                                    <th className="p-4">Şube</th>
                                    <th className="p-4">Ürün</th>
                                    <th className="p-4 text-center">Adet</th>
                                    <th className="p-4 text-right">İşlem / Durum</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-zinc-800/50">
                                {salesLogs.length === 0 ? (
                                    <tr><td colSpan={6} className="p-20 text-center text-zinc-600 italic">Gösterilecek veri yok.</td></tr>
                                ) : (
                                    salesLogs.map(log => {
                                        const emp = availableEmployees.find(e => e.id === log.employeeId) || { name: 'Kullanıcı', avatarUrl: '' };
                                        const isPending = log.status === 'Bekliyor';
                                        return (
                                            <tr key={log.id} className={`hover:bg-zinc-800/30 transition-colors ${isPending ? 'bg-orange-500/5' : ''}`}>
                                                <td className="p-4 text-xs font-bold text-zinc-500 font-mono">{formatDate(log.saleDate)}</td>
                                                <td className="p-4">
                                                    <div className="flex items-center gap-3">
                                                        <div className="w-8 h-8 rounded-full bg-zinc-800 border border-zinc-700 overflow-hidden">
                                                            <img src={emp.avatarUrl} className="w-full h-full object-cover" alt="" />
                                                        </div>
                                                        <span className="text-sm font-bold text-zinc-300">{emp.name}</span>
                                                    </div>
                                                </td>
                                                <td className="p-4 text-xs font-bold text-zinc-600">{log.branch}</td>
                                                <td className="p-4">
                                                    <div className="flex items-center gap-2">
                                                        <Package size={14} className="text-indigo-500" />
                                                        <span className="text-sm font-medium text-white">{log.productName}</span>
                                                    </div>
                                                </td>
                                                <td className="p-4 text-center">
                                                    <span className="text-lg font-black text-white">{log.quantity}</span>
                                                </td>
                                                <td className="p-4 text-right">
                                                    {isAdmin && isPending ? (
                                                        <div className="flex justify-end gap-2">
                                                            <button onClick={() => handleUpdateStatus(log.id, 'Onaylandı')} className="p-2 bg-green-500/10 text-green-500 hover:bg-green-500 rounded-lg transition-all"><CheckCircle2 size={18}/></button>
                                                            <button onClick={() => handleUpdateStatus(log.id, 'Reddedildi')} className="p-2 bg-red-500/10 text-red-500 hover:bg-red-500 rounded-lg transition-all"><XCircle size={18}/></button>
                                                        </div>
                                                    ) : (
                                                        <div className="flex justify-end items-center gap-3">
                                                            <span className={`text-[10px] font-black uppercase px-2 py-1 rounded border ${
                                                                log.status === 'Onaylandı' ? 'bg-green-500/10 text-green-500 border-green-500/20' : 
                                                                log.status === 'Reddedildi' ? 'bg-red-500/10 text-red-500 border-red-500/20' : 
                                                                'bg-orange-500/10 text-orange-500 border-orange-500/20 animate-pulse'
                                                            }`}>{log.status}</span>
                                                            {(isAdmin || isPending) && (
                                                                <button onClick={() => handleDeleteSale(log.id)} className="p-1.5 text-zinc-700 hover:text-red-500"><Trash2 size={16}/></button>
                                                            )}
                                                        </div>
                                                    )}
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default ShiftSchedule;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useLanguage } from '../lib/i18n';
import { Branch, Employee, Role, SalesLog } from '../types';
import { Save, Clock, ChevronLeft, ChevronRight, Copy, Plus, Trash2, User, Loader2, Lock, ArrowRightLeft, ShoppingBag, Tag, List, CheckCircle2, XCircle, Filter, Calendar, History, AlignLeft, Layers, BarChart3, Package, Send } from 'lucide-react';
import { supabase } from '../lib/supabase';

const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
const AKTION_PRODUCTS = [
    "Ploom",
    "Vuse",
    "İqos iluma prime",
    "İqos iluma",
    "İqos one",
    "Veev"
];

const YEARS = [2024, 2025, 2026];
const MONTHS = [
    { val: 1, label: 'Ocak' }, { val: 2, label: 'Şubat' }, { val: 3, label: 'Mart' },
    { val: 4, label: 'Nisan' }, { val: 5, label: 'Mayıs' }, { val: 6, label: 'Haziran' },
    { val: 7, label: 'Temmuz' }, { val: 8, label: 'Ağustos' }, { val: 9, label: 'Eylül' },
    { val: 10, label: 'Ekim' }, { val: 11, label: 'Kasım' }, { val: 12, label: 'Aralık' }
];

interface RosterRow {
    id?: string;
    timeLabel: string;
    assignments: string[];
}

interface ShiftScheduleProps {
    currentUser: Employee;
}

const getMonday = (d: Date) => {
  const date = new Date(d);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
  return new Date(date.setDate(diff));
};

const ShiftSchedule: React.FC<ShiftScheduleProps> = ({ currentUser }) => {
  const { t, formatDate } = useLanguage();
  const isAdmin = currentUser.role === Role.ADMIN;

  const [activeBranch, setActiveBranch] = useState<string>(isAdmin ? Branch.MULHEIM : currentUser.branch);
  const [viewMode, setViewMode] = useState<'ROSTER' | 'AKTION'>('ROSTER');

  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getMonday(new Date()));
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [rosterData, setRosterData] = useState<RosterRow[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);
  const [transferredEmpIds, setTransferredEmpIds] = useState<string[]>([]); 

  const [salesLogs, setSalesLogs] = useState<SalesLog[]>([]);
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);

  const [salesForm, setSalesForm] = useState({
      product: AKTION_PRODUCTS[0],
      quantity: 1,
      date: new Date().toISOString().split('T')[0]
  });

  const weekKey = `${currentWeekStart.getFullYear()}-${String(currentWeekStart.getMonth() + 1).padStart(2, '0')}-${String(currentWeekStart.getDate()).padStart(2, '0')}`;
  const currentWeekEnd = new Date(currentWeekStart);
  currentWeekEnd.setDate(currentWeekEnd.getDate() + 6);

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; };
  }, []);

  useEffect(() => {
      fetchEmployeesAndTransfers();
  }, [currentWeekStart]); 

  useEffect(() => {
      if (viewMode === 'ROSTER') {
          if (activeBranch !== 'PENDING_ALL') fetchWeekData();
      } else {
          fetchSalesLogs();
      }
  }, [activeBranch, weekKey, viewMode, selectedYear, selectedMonth]); 

  const fetchEmployeesAndTransfers = async () => {
      try {
          const { data: empData } = await supabase.from('profiles').select('*').neq('role', 'Admin');
          if (!isMounted.current) return;

          let currentEmployees: Employee[] = [];
          if (empData) {
              currentEmployees = empData.map((e: any) => ({
                  id: e.id, name: e.full_name, email: e.email, role: e.role, branch: e.branch,
                  hourlyRate: e.hourly_rate, taxClass: e.tax_class, avatarUrl: e.avatar_url, advances: 0, metrics: e.metrics
              }));
          }
          const startStr = currentWeekStart.toISOString().split('T')[0];
          const endStr = currentWeekEnd.toISOString().split('T')[0];
          const { data: transferData } = await supabase.from('calendar_events').select('attendees').eq('type', 'Şube Transferi').lte('date', endStr).gte('end_date', startStr);

          if (!isMounted.current) return;
          if (transferData) setTransferredEmpIds(transferData.flatMap((t: any) => t.attendees || []));
          setAvailableEmployees(currentEmployees);
      } catch (err) { console.error(err); }
  };

  const fetchWeekData = async () => {
      if (activeBranch === 'PENDING_ALL') return;
      setIsLoading(true);
      try {
          const { data, error } = await supabase.from('shift_schedules').select('*').eq('week_start_date', weekKey).eq('branch', activeBranch).order('created_at', { ascending: true });
          if (!isMounted.current) return;
          if (data) setRosterData(data.map((r: any) => ({ id: r.id, timeLabel: r.time_slot || '', assignments: r.days || Array(7).fill('') })));
      } catch (err: any) { console.error(err); } finally { if (isMounted.current) setIsLoading(false); }
  };

  const fetchSalesLogs = async () => {
      setIsLoading(true);
      try {
          const startDate = new Date(selectedYear, selectedMonth - 1, 1).toISOString().split('T')[0];
          const endDate = new Date(selectedYear, selectedMonth, 0).toISOString().split('T')[0];

          let query = supabase.from('sales_logs').select('*')
              .gte('sale_date', startDate)
              .lte('sale_date', endDate)
              .order('sale_date', { ascending: false });

          if (!isAdmin) query = query.eq('employee_id', currentUser.id);

          const { data, error } = await query;
          if (data && isMounted.current) {
              setSalesLogs(data.map((l: any) => ({
                  id: l.id, employeeId: l.employee_id, branch: l.branch, productName: l.product_name,
                  quantity: l.quantity, saleDate: l.sale_date, status: l.status || 'Bekliyor', createdAt: l.created_at
              })));
          }
      } catch (err) { console.error(err); } finally { if (isMounted.current) setIsLoading(false); }
  };

  const handleWeekChange = (direction: 'prev' | 'next') => {
      const newDate = new Date(currentWeekStart);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setCurrentWeekStart(newDate);
  };

  const saveRowToDb = async (row: RosterRow) => {
      if (!isAdmin) return;
      setIsSaving(true);
      try {
          const payload = { week_start_date: weekKey, branch: String(activeBranch), time_slot: row.timeLabel, days: row.assignments };
          if (row.id && !row.id.startsWith('temp_')) {
              await supabase.from('shift_schedules').update(payload).eq('id', row.id);
          } else {
              const { data, error } = await supabase.from('shift_schedules').insert([payload]).select().single();
              if(!error && data && isMounted.current) setRosterData(prev => prev.map(r => r.id === row.id ? { ...r, id: data.id } : r));
          }
      } catch (err) { console.error(err); } finally { if (isMounted.current) setIsSaving(false); }
  };

  const handleAssignmentChange = (rowId: string | undefined, dayIndex: number, employeeId: string) => {
      if (!isAdmin) return;
      const updatedRows = rosterData.map(row => {
          if (row.id !== rowId) return row;
          const newAssignments = [...row.assignments];
          newAssignments[dayIndex] = employeeId;
          return { ...row, assignments: newAssignments };
      });
      setRosterData(updatedRows);
      const rowToSave = updatedRows.find(r => r.id === rowId);
      if (rowToSave) saveRowToDb(rowToSave);
  };

  const handleTimeLabelChange = (rowId: string | undefined, newLabel: string) => {
      if (!isAdmin) return;
      setRosterData(prev => prev.map(row => row.id === rowId ? { ...row, timeLabel: newLabel } : row));
  };

  const addNewRow = async () => {
      if (!isAdmin) return;
      const newRow: RosterRow = { id: `temp_${Date.now()}`, timeLabel: '', assignments: Array(7).fill('') };
      setRosterData([...rosterData, newRow]);
  };

  const deleteRow = async (rowId: string) => {
      if (!isAdmin) return;
      if(!confirm("Silmek istediğinize emin misiniz?")) return;
      setRosterData(prev => prev.filter(r => r.id !== rowId));
      if (rowId && !rowId.startsWith('temp_')) await supabase.from('shift_schedules').delete().eq('id', rowId);
  };

  // Fix: Added handleManualSave function to satisfy the button click handler
  const handleManualSave = async () => {
      await fetchWeekData();
  };

  const handleCopyNextWeek = async () => {
      if (!isAdmin) return;
      const nextWeekDate = new Date(currentWeekStart); nextWeekDate.setDate(nextWeekDate.getDate() + 7);
      const nextWeekKey = `${nextWeekDate.getFullYear()}-${String(nextWeekDate.getMonth() + 1).padStart(2, '0')}-${String(nextWeekDate.getDate()).padStart(2, '0')}`;
      if (confirm(`${formatDate(nextWeekDate)} haftasına kopyalamak istiyor musunuz?`)) {
          setIsLoading(true);
          try {
              await supabase.from('shift_schedules').delete().eq('week_start_date', nextWeekKey).eq('branch', String(activeBranch));
              const payload = rosterData.map(row => ({ week_start_date: nextWeekKey, branch: String(activeBranch), time_slot: row.timeLabel, days: row.assignments }));
              if(payload.length > 0) await supabase.from('shift_schedules').insert(payload);
              if (isMounted.current) setCurrentWeekStart(nextWeekDate);
          } catch (err: any) { console.error(err); } finally { if (isMounted.current) setIsLoading(false); }
      }
  };

  const handleSaveSale = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsSaving(true);
      try {
          const payload = { employee_id: currentUser.id, branch: currentUser.branch, product_name: salesForm.product, quantity: salesForm.quantity, sale_date: salesForm.date, status: 'Bekliyor' };
          const { data, error } = await supabase.from('sales_logs').insert([payload]).select();
          if (error) throw error;
          if (data && isMounted.current) {
              setSalesLogs([{ id: data[0].id, employeeId: data[0].employee_id, branch: data[0].branch, productName: data[0].product_name, quantity: data[0].quantity, saleDate: data[0].sale_date, status: 'Bekliyor', createdAt: data[0].created_at }, ...salesLogs]);
              alert("Onaya gönderildi.");
          }
      } catch (err: any) { alert(err.message); } finally { setIsSaving(false); }
  };

  const handleUpdateStatus = async (id: string, newStatus: 'Onaylandı' | 'Reddedildi') => {
      if(!isAdmin) return;
      try {
          await supabase.from('sales_logs').update({ status: newStatus }).eq('id', id);
          setSalesLogs(prev => prev.map(l => l.id === id ? { ...l, status: newStatus } : l));
      } catch (err) { console.error(err); }
  };

  const handleDeleteSale = async (id: string) => {
      if(!confirm("Silmek istediğinize emin misiniz?")) return;
      try {
          await supabase.from('sales_logs').delete().eq('id', id);
          setSalesLogs(prev => prev.filter(l => l.id !== id));
      } catch (err) { console.error(err); }
  };

  const branchSummary = useMemo(() => {
    if (!isAdmin) return [];
    const summary: Record<string, { a: number, p: number }> = {};
    Object.values(Branch).forEach(b => summary[b] = { a: 0, p: 0 });
    salesLogs.forEach(l => {
        if (summary[l.branch]) {
            if (l.status === 'Onaylandı') summary[l.branch].a += l.quantity;
            else if (l.status === 'Bekliyor') summary[l.branch].p += l.quantity;
        }
    });
    return Object.entries(summary).map(([n, d]) => ({ n, a: d.a, p: d.p }));
  }, [salesLogs, isAdmin]);

  const filteredEmployees = availableEmployees.filter(e => e.branch === activeBranch);
  const displayedRows = isAdmin ? rosterData : rosterData.filter(row => row.assignments.includes(currentUser.id));

  return (
    <div className="h-full w-full flex flex-col bg-[#09090b] relative overflow-hidden">

      {/* HEADER */}
      <div className="p-4 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-md sticky top-0 z-30 shrink-0">
          <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
              <div className="flex items-center gap-2 overflow-x-auto max-w-full pb-1 xl:pb-0">
                  {isAdmin ? (
                      <>
                        <button onClick={() => setActiveBranch('ALL')} className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all border ${activeBranch === 'ALL' ? 'bg-white text-black' : 'bg-zinc-900 text-zinc-500 border-zinc-800'}`}>Tümü</button>
                        {Object.values(Branch).map(b => (
                            <button key={b} onClick={() => setActiveBranch(b)} className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all border whitespace-nowrap ${activeBranch === b ? 'bg-orange-600 text-white border-orange-500' : 'bg-zinc-900 text-zinc-500 border-zinc-800'}`}>{b}</button>
                        ))}
                        {viewMode === 'AKTION' && (
                            <button onClick={() => setActiveBranch('PENDING_ALL')} className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold transition-all border ${activeBranch === 'PENDING_ALL' ? 'bg-red-600 text-white' : 'bg-zinc-900 text-orange-400 border-zinc-800'}`}>
                                <Layers size={14} /> Onay Bekleyenler
                            </button>
                        )}
                      </>
                  ) : (
                      <div className="px-4 py-2 bg-zinc-900 border border-zinc-800 rounded-xl text-sm font-bold text-white">{activeBranch}</div>
                  )}
              </div>

              <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto">
                  <div className="flex bg-zinc-900 rounded-xl p-1 border border-zinc-800">
                      <button onClick={() => setViewMode('ROSTER')} className={`px-6 py-2 rounded-lg text-xs font-bold transition-all ${viewMode === 'ROSTER' ? 'bg-zinc-800 text-white shadow' : 'text-zinc-500 hover:text-zinc-300'}`}>Vardiya</button>
                      <button onClick={() => setViewMode('AKTION')} className={`px-6 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'AKTION' ? 'bg-orange-600 text-white' : 'text-zinc-500 hover:text-zinc-300'}`}><ShoppingBag size={14}/> Aktion</button>
                  </div>

                  {viewMode === 'ROSTER' && (
                      <div className="flex items-center bg-zinc-900 rounded-xl border border-zinc-800 p-1">
                            <button onClick={() => handleWeekChange('prev')} className="p-2 text-zinc-400 hover:text-white"><ChevronLeft size={20}/></button>
                            <div className="px-4 text-center min-w-[140px] text-sm font-bold text-white">{formatDate(currentWeekStart, { day: 'numeric', month: 'short' })} - {formatDate(currentWeekEnd, { day: 'numeric', month: 'short' })}</div>
