    const isAdmin = currentUser.role === Role.ADMIN;

    // Filter States - Admin starts with ALL, Staff starts with their own branch
    const [selectedBranch, setSelectedBranch] = useState<string>(isAdmin ? 'ALL' : currentUser.branch);
    const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth() + 1);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const { data: sales } = await supabase.from('sales_logs').select('*');
            if (sales) {
                const formattedSales = sales.map((l: any) => ({
                    id: l.id,
                    employeeId: l.employee_id,
                    branch: l.branch,
                    productName: l.product_name,
                    quantity: l.quantity,
                    saleDate: l.sale_date,
                    status: l.status,
                    createdAt: l.created_at
                }));
                setSalesData(formattedSales);
            }

            const { data: profiles } = await supabase.from('profiles').select('*');
            if (profiles) {
                const formattedEmps = profiles.map((p: any) => ({
                    id: p.id,
                    name: p.full_name,
                    avatarUrl: p.avatar_url || `https://ui-avatars.com/api/?name=${p.full_name}`,
                    branch: p.branch
                }));
                setEmployees(formattedEmps as Employee[]);
            }
        } catch (err) {
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    // Filtered Data Logic
    const filteredResults = useMemo(() => {
        return salesData.filter(s => {
            const date = new Date(s.saleDate);
            const matchesYear = date.getFullYear() === selectedYear;
            const matchesMonth = (date.getMonth() + 1) === selectedMonth;

            // KRİTİK: Admin seçtiği şubeyi görür, Personel SADECE kendi şubesini görür.
            const branchToMatch = isAdmin ? selectedBranch : currentUser.branch;
            const matchesBranch = branchToMatch === 'ALL' || s.branch === branchToMatch;

            return matchesYear && matchesMonth && matchesBranch;
        });
    }, [salesData, selectedYear, selectedMonth, selectedBranch, isAdmin, currentUser.branch]);

    // Leaderboard Data (With Masking Logic)
    const leaderboardData = useMemo(() => {
        const currentMonthData = salesData.filter(s => {
            const d = new Date(s.saleDate);
            const branchToMatch = isAdmin ? selectedBranch : currentUser.branch;
            const matchesBranch = branchToMatch === 'ALL' || s.branch === branchToMatch;

            return d.getFullYear() === selectedYear && 
                   (d.getMonth() + 1) === selectedMonth && 
                   s.status === 'Onaylandı' &&
                   matchesBranch;
        });

        const personnelMap: Record<string, number> = {};
        currentMonthData.forEach(s => {
            const empId = s.employeeId || 'unknown';
            personnelMap[empId] = (personnelMap[empId] || 0) + s.quantity;
        });

        return Object.entries(personnelMap)
            .map(([id, count]) => {
                if (id === 'unknown') return null;
                const emp = employees.find(e => e.id === id);
                const isMe = id === currentUser.id;

                // GİZLİLİK KURALI: Admin her şeyi görür. Personel sadece kendisini görür, diğerlerini ? görür.
                const displayName = (isAdmin || isMe) ? (emp?.name || 'Bilinmeyen') : '???';
                const displayAvatar = (isAdmin || isMe) 
                    ? (emp?.avatarUrl || `https://ui-avatars.com/api/?name=${emp?.name || '?'}`)
                    : `https://ui-avatars.com/api/?name=?&background=27272a&color=a1a1aa`;
                const displayBranch = (isAdmin || isMe) ? (emp?.branch || '-') : '***';

                return { 
                    id, 
                    name: displayName, 
                    avatar: displayAvatar, 
                    count, 
                    branch: displayBranch,
                    isMe 
                };
            })
            .filter(Boolean)
            .sort((a, b) => (b?.count || 0) - (a?.count || 0))
            .slice(0, 10);
    }, [salesData, selectedYear, selectedMonth, employees, isAdmin, selectedBranch, currentUser.id, currentUser.branch]);

    // Statistics based on filtered data
    const stats = useMemo(() => {
        const approvedCount = filteredResults.filter(s => s.status === 'Onaylandı').reduce((a, b) => a + b.quantity, 0);
        const pendingCount = filteredResults.filter(s => s.status === 'Bekliyor').reduce((a, b) => a + b.quantity, 0);

        const branchMap: Record<string, { approved: number, pending: number }> = {};
        filteredResults.forEach(s => {
            const b = s.branch || 'Bilinmiyor';
            if (!branchMap[b]) branchMap[b] = { approved: 0, pending: 0 };
            if (s.status === 'Onaylandı') branchMap[b].approved += s.quantity;
            else branchMap[b].pending += s.quantity;
        });

        const chartData = Object.entries(branchMap).map(([name, val]) => ({
            name,
            approved: val.approved,
            pending: val.pending
        })).sort((a,b) => (b.approved + b.pending) - (a.approved + a.pending));

        const productMap: Record<string, number> = {};
        filteredResults.forEach(s => {
            productMap[s.productName] = (productMap[s.productName] || 0) + s.quantity;
        });
        const topProduct = Object.keys(productMap).sort((a, b) => productMap[b] - productMap[a])[0];

        return { approvedCount, pendingCount, chartData, topProduct, topProductVal: productMap[topProduct] || 0 };
    }, [filteredResults]);

    return (
        <div className="h-full w-full p-4 md:p-8 overflow-y-auto custom-scrollbar bg-[#09090b]">
            {/* Header & Global Filters */}
            <div className="mb-8 flex flex-col xl:flex-row justify-between items-start xl:items-end gap-6">
                <div>
                    <h1 className="text-3xl font-bold text-white tracking-tight mb-2 flex items-center gap-3">
                        <ShoppingBag className="text-orange-500" size={32} />
                        {t('sales.title')}
                    </h1>
                    <p className="text-zinc-500 text-sm flex items-center gap-2">
                        <Activity size={14} className="text-green-500" />
                        {formatDate(new Date(selectedYear, selectedMonth - 1, 1), { month: 'long', year: 'numeric' })} Performans Verileri
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-3 bg-zinc-900/50 p-2 rounded-2xl border border-zinc-800">
                    <div className="flex items-center gap-2 px-3 border-r border-zinc-800">
                        <Filter size={14} className="text-zinc-500" />
                        <select 
                            value={selectedYear} 
                            onChange={e => setSelectedYear(Number(e.target.value))}
                            className="bg-transparent text-sm font-bold text-zinc-300 outline-none cursor-pointer hover:text-white"
                        >
                            {YEARS.map(y => <option key={y} value={y} className="bg-zinc-900">{y}</option>)}
                        </select>
                        <select 
                            value={selectedMonth} 
                            onChange={e => setSelectedMonth(Number(e.target.value))}
                            className="bg-transparent text-sm font-bold text-zinc-300 outline-none cursor-pointer hover:text-white"
                        >
                            {MONTHS.map(m => <option key={m.v} value={m.v} className="bg-zinc-900">{m.l}</option>)}
                        </select>
                    </div>

                    <div className="flex gap-1 overflow-x-auto">
                        {isAdmin ? (
                            <>
                                <button 
                                    onClick={() => setSelectedBranch('ALL')}
                                    className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${selectedBranch === 'ALL' ? 'bg-white text-black' : 'text-zinc-500 hover:text-zinc-300'}`}
                                >
                                    Tümü
                                </button>
                                {Object.values(Branch).map(b => (
                                    <button 
                                        key={b}
                                        onClick={() => setSelectedBranch(b)}
                                        className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${selectedBranch === b ? 'bg-orange-600 text-white' : 'text-zinc-500 hover:text-zinc-300'}`}
                                    >
                                        {b}
                                    </button>
                                ))}
                            </>
                        ) : (
                            <div className="px-4 py-1.5 bg-orange-600/20 text-orange-400 rounded-lg text-xs font-bold border border-orange-500/30 flex items-center gap-2">
                                <MapPin size={12} />
                                {currentUser.branch} Şubesi Verileri
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Quick Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-20 h-20 bg-green-500/10 rounded-full blur-2xl"></div>
                    <p className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">Onaylı Satış</p>
                    <p className="text-3xl font-bold text-green-400">{stats.approvedCount}</p>
                </div>
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-20 h-20 bg-orange-500/10 rounded-full blur-2xl"></div>
                    <p className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">Onay Bekleyen</p>
                    <p className="text-3xl font-bold text-orange-400">{stats.pendingCount}</p>
                </div>
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-20 h-20 bg-blue-500/10 rounded-full blur-2xl"></div>
                    <p className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">Toplam İşlem</p>
                    <p className="text-3xl font-bold text-white">{stats.approvedCount + stats.pendingCount}</p>
                </div>
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-20 h-20 bg-purple-500/10 rounded-full blur-2xl"></div>
                    <p className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">En Çok Satan</p>
                    <div className="flex items-baseline gap-2">
                        <p className="text-xl font-bold text-purple-400 truncate">{stats.topProduct || '-'}</p>
                        <span className="text-xs text-zinc-600">({stats.topProductVal})</span>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-8">
                {/* Visual Chart */}
                <div className="lg:col-span-2 bg-zinc-900/30 border border-zinc-800 rounded-3xl p-6 flex flex-col">
                    <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                        <BarChart3 className="text-indigo-500" size={20}/>
                        {isAdmin ? 'Şube Bazlı Dağılım' : `${currentUser.branch} Şube Analizi`}
                    </h3>
                    <div className="flex-1 min-h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={stats.chartData} barSize={40}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#27272a" vertical={false} />
                                <XAxis dataKey="name" stroke="#71717a" fontSize={12} tickLine={false} axisLine={false} dy={10}/>
                                <YAxis stroke="#71717a" fontSize={12} tickLine={false} axisLine={false} />
                                <Tooltip 
                                    cursor={{fill: '#27272a', opacity: 0.2}}
                                    contentStyle={{ backgroundColor: '#09090b', border: '1px solid #27272a', borderRadius: '12px', color: '#fff' }}
                                />
                                <Legend wrapperStyle={{paddingTop: '20px'}} />
                                <Bar dataKey="approved" name="Onaylı" stackId="a" fill="#22c55e" radius={[0, 0, 4, 4]} />
                                <Bar dataKey="pending" name="Bekliyor" stackId="a" fill="#f97316" radius={[4, 4, 0, 0]} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Mini Leaderboard with Privacy Masking */}
                <div className="bg-zinc-900/30 border border-zinc-800 rounded-3xl p-6 flex flex-col">
                    <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                        <Trophy className="text-yellow-500" size={20}/>
                        {t('sales.leaderboard')}
                    </h3>
                    <div className="space-y-4 flex-1">
                        {leaderboardData.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center text-zinc-600 opacity-30">
                                <Award size={48} />
                                <p className="text-xs mt-2">Henüz veri yok</p>
                            </div>
                        ) : leaderboardData.map((item, idx) => (
                            <div 
                                key={item!.id} 
                                className={`flex items-center gap-3 p-3 border rounded-2xl transition-all ${
                                    item!.isMe ? 'bg-orange-500/10 border-orange-500/50' : 'bg-zinc-900/50 border-zinc-800'
                                }`}
                            >
                                <span className={`font-bold w-4 ${item!.isMe ? 'text-orange-400' : 'text-zinc-600'}`}>{idx + 1}</span>
                                <div className="w-10 h-10 rounded-full overflow-hidden border border-zinc-700 bg-zinc-800">
                                    <img src={item!.avatar} alt="" className="w-full h-full object-cover" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <p className={`text-sm font-bold truncate ${item!.isMe ? 'text-orange-400' : 'text-zinc-200'}`}>
                                        {item!.name} {item!.isMe && <span className="text-[10px] ml-1">(Siz)</span>}
                                    </p>
                                    <p className="text-[10px] text-zinc-500 uppercase">{item!.branch}</p>
                                </div>
                                <span className={`text-lg font-bold ${item!.isMe ? 'text-orange-400' : 'text-zinc-400'}`}>{item!.count}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* DETAILED TABLE SECTION */}
            <div className="bg-zinc-900/30 border border-zinc-800 rounded-3xl overflow-hidden shadow-2xl">
                <div className="p-6 border-b border-zinc-800 bg-zinc-950/50 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                    <div>
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            <ListTodo className="text-blue-500" size={20}/>
                            Detaylı Satış Kayıtları
                        </h3>
                        <p className="text-xs text-zinc-500 mt-1">
                            {isAdmin ? 'Seçili dönemdeki tüm kayıtlar.' : `Sadece ${currentUser.branch} şubesine ait kayıtlar.`}
                        </p>
                    </div>
                    <div className="flex gap-2">
                        <div className="flex items-center gap-2 px-3 py-1.5 bg-green-500/10 rounded-lg border border-green-500/20">
                            <div className="w-2 h-2 rounded-full bg-green-500"></div>
                            <span className="text-[10px] font-bold text-green-400 uppercase">Onaylı</span>
                        </div>
                        <div className="flex items-center gap-2 px-3 py-1.5 bg-orange-500/10 rounded-lg border border-orange-500/20">
                            <div className="w-2 h-2 rounded-full bg-orange-500"></div>
                            <span className="text-[10px] font-bold text-orange-400 uppercase">Bekliyor</span>
                        </div>
                    </div>
                </div>

                <div className="overflow-x-auto custom-scrollbar">
                    <table className="w-full text-left">
                        <thead className="bg-zinc-950 border-b border-zinc-800">
                            <tr className="text-[11px] font-bold text-zinc-500 uppercase tracking-widest">
                                <th className="p-4">Tarih</th>
                                <th className="p-4">Personel</th>
                                <th className="p-4">Şube</th>
                                <th className="p-4">Ürün</th>
                                <th className="p-4 text-center">Adet</th>
                                <th className="p-4 text-right">Durum</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-zinc-800">
                            {filteredResults.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="p-12 text-center text-zinc-600 italic">
                                        Seçili kriterlere uygun kayıt bulunamadı.
                                    </td>
                                </tr>
                            ) : filteredResults.map(log => {
                                const emp = employees.find(e => e.id === log.employeeId);
                                const isMe = log.employeeId === currentUser.id;
                                const isPending = log.status === 'Bekliyor';

                                // TABLO GİZLİLİK: Personel ise kendisi dışındakilerin ismini gizle
                                const displayName = (isAdmin || isMe) ? (emp?.name || 'Bilinmeyen') : '???';
                                const displayAvatar = (isAdmin || isMe) 
                                    ? (emp?.avatarUrl || `https://ui-avatars.com/api/?name=${emp?.name || '?'}`)
                                    : `https://ui-avatars.com/api/?name=?&background=18181b&color=52525b`;

                                return (
                                    <tr key={log.id} className={`hover:bg-zinc-800/30 transition-colors group ${isPending ? 'bg-orange-500/5' : ''}`}>
                                        <td className="p-4">
                                            <div className="flex items-center gap-2">
                                                <Calendar size={14} className="text-zinc-600" />
                                                <span className="text-sm font-medium text-zinc-400">{formatDate(log.saleDate)}</span>
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full overflow-hidden border border-zinc-800 bg-zinc-900 shrink-0">
                                                    <img src={displayAvatar} className="w-full h-full object-cover" />
                                                </div>
                                                <span className={`text-sm font-bold ${isMe ? 'text-orange-400' : 'text-zinc-200'}`}>
                                                    {displayName}
                                                </span>
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <span className="text-xs font-bold text-zinc-500 bg-zinc-900 border border-zinc-800 px-2 py-1 rounded">
                                                {log.branch}
                                            </span>
                                        </td>
                                        <td className="p-4">
                                            <div className="flex items-center gap-2">
                                                <Package size={14} className="text-indigo-400" />
                                                <span className="text-sm text-zinc-200">{log.productName}</span>
                                            </div>
                                        </td>
                                        <td className="p-4 text-center">
                                            <span className={`text-base font-mono font-bold ${isPending ? 'text-orange-400' : 'text-white'}`}>
                                                {log.quantity}
                                            </span>
                                        </td>
                                        <td className="p-4 text-right">
                                            <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full border text-[10px] font-bold uppercase ${
                                                log.status === 'Onaylandı' ? 'bg-green-500/10 text-green-500 border-green-500/20' : 
                                                log.status === 'Reddedildi' ? 'bg-red-500/10 text-red-500 border-red-500/20' : 
                                                'bg-orange-500/10 text-orange-500 border-orange-500/20'
                                            }`}>
                                                {isPending ? <Clock size={10} className="animate-pulse" /> : null}
                                                {log.status}
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default SalesDashboard;

import React, { ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

// Define the interface for props to include children
interface Props {
  children?: ReactNode;
}

// Define the interface for state
interface State {
  hasError: boolean;
  error: Error | null;
}

// ErrorBoundary class to catch and handle frontend errors gracefully.
// Fix: Explicitly extending React.Component solves the issue where inherited properties like 'setState' and 'props' were not recognized.
class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Log the error to an error reporting service
    console.error('Uncaught error:', error, errorInfo);
  }

  // Fix: Inherited method 'setState' is now correctly identified through explicit inheritance from React.Component.
  private handleReset = () => {
      this.setState({ hasError: false, error: null });
      window.location.href = '/'; // Hard reload to clear state
  }

  public render() {
    if (this.state.hasError) {
      // Render a custom fallback UI when an error occurs
      return (
        <div className="min-h-screen w-full bg-zinc-950 flex flex-col items-center justify-center p-4 text-center">
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center">
                <div className="w-16 h-16 bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mb-4 border border-red-500/20">
                    <AlertTriangle size={32} />
                </div>
                <h1 className="text-xl font-bold text-white mb-2">Bir Sorun Oluştu</h1>
                <p className="text-zinc-400 text-sm mb-6">
                    Sistem beklenmeyen bir veri durumuyla karşılaştı. Bu genellikle veritabanı bağlantısı veya eksik veriden kaynaklanır.
                </p>

                <div className="bg-black/30 p-3 rounded-lg border border-zinc-800 w-full mb-6 text-left overflow-hidden">
                    <p className="text-[10px] text-red-400 font-mono break-all">
                        {this.state.error?.message || 'Unknown Error'}
                    </p>
                </div>

                <button 
                    onClick={this.handleReset}
                    className="flex items-center gap-2 px-6 py-3 bg-white text-black hover:bg-zinc-200 font-bold rounded-xl transition-colors w-full justify-center"
                >
                    <RefreshCw size={18} /> Sistemi Yenile
                </button>
            </div>
        </div>
      );
    }

    // Fix: Accessing children through the inherited 'props' property from React.Component.
    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useEffect, useMemo } from 'react';
import { SalesLog, Employee, Role, Branch } from '../types';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, Legend } from 'recharts';
import { Trophy, TrendingUp, ShoppingBag, MapPin, Award, Medal, Calendar, Package, Activity, BarChart3, ListTodo, User, Lock, EyeOff, Filter, ChevronDown, Clock } from 'lucide-react';

interface SalesDashboardProps {
    currentUser: Employee;
}

const YEARS = [2024, 2025, 2026];
const MONTHS = [
    { v: 1, l: 'Ocak' }, { v: 2, l: 'Şubat' }, { v: 3, l: 'Mart' },
    { v: 4, l: 'Nisan' }, { v: 5, l: 'Mayıs' }, { v: 6, l: 'Haziran' },
    { v: 7, l: 'Temmuz' }, { v: 8, l: 'Ağustos' }, { v: 9, l: 'Eylül' },
    { v: 10, l: 'Ekim' }, { v: 11, l: 'Kasım' }, { v: 12, l: 'Aralık' }
];

const SalesDashboard: React.FC<SalesDashboardProps> = ({ currentUser }) => {
    const { t, formatDate } = useLanguage();
    const [salesData, setSalesData] = useState<SalesLog[]>([]);
    const [employees, setEmployees] = useState<Employee[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const isAdmin = currentUser.role === Role.ADMIN;

    // Filter States - Admin starts with ALL, Staff starts with their own branch
    const [selectedBranch, setSelectedBranch] = useState<string>(isAdmin ? 'ALL' : currentUser.branch);
    const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth() + 1);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const { data: sales } = await supabase.from('sales_logs').select('*');
            if (sales) {
                const formattedSales = sales.map((l: any) => ({
                    id: l.id,
                    employeeId: l.employee_id,
                    branch: l.branch,
                    productName: l.product_name,
                    quantity: l.quantity,
                    saleDate: l.sale_date,
                    status: l.status,
                    createdAt: l.created_at
                }));
                setSalesData(formattedSales);
            }

            const { data: profiles } = await supabase.from('profiles').select('*');
            if (profiles) {
                const formattedEmps = profiles.map((p: any) => ({
                    id: p.id,
                    name: p.full_name,
                    avatarUrl: p.avatar_url || `https://ui-avatars.com/api/?name=${p.full_name}`,
                    branch: p.branch
                }));
                setEmployees(formattedEmps as Employee[]);
            }
        } catch (err) {
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    // Filtered Data Logic
    const filteredResults = useMemo(() => {
        return salesData.filter(s => {
            const date = new Date(s.saleDate);
            const matchesYear = date.getFullYear() === selectedYear;
            const matchesMonth = (date.getMonth() + 1) === selectedMonth;

            // KRİTİK: Admin seçtiği şubeyi görür, Personel SADECE kendi şubesini görür.
            const branchToMatch = isAdmin ? selectedBranch : currentUser.branch;
            const matchesBranch = branchToMatch === 'ALL' || s.branch === branchToMatch;

            return matchesYear && matchesMonth && matchesBranch;
        });
    }, [salesData, selectedYear, selectedMonth, selectedBranch, isAdmin, currentUser.branch]);

    // Leaderboard Data (With Masking Logic)
    const leaderboardData = useMemo(() => {
        const currentMonthData = salesData.filter(s => {
            const d = new Date(s.saleDate);
            const branchToMatch = isAdmin ? selectedBranch : currentUser.branch;
            const matchesBranch = branchToMatch === 'ALL' || s.branch === branchToMatch;

            return d.getFullYear() === selectedYear && 
                   (d.getMonth() + 1) === selectedMonth && 
                   s.status === 'Onaylandı' &&
                   matchesBranch;
        });

        const personnelMap: Record<string, number> = {};
        currentMonthData.forEach(s => {
            const empId = s.employeeId || 'unknown';
            personnelMap[empId] = (personnelMap[empId] || 0) + s.quantity;
        });

        return Object.entries(personnelMap)
            .map(([id, count]) => {
                if (id === 'unknown') return null;
                const emp = employees.find(e => e.id === id);
                const isMe = id === currentUser.id;

                // GİZLİLİK KURALI: 
                // Admin her şeyi görür. 
                // Personel sadece kendisini görür, diğerlerini ??????? görür.
                const displayName = (isAdmin || isMe) ? (emp?.name || 'Bilinmeyen') : '???????';

                const displayAvatar = (isAdmin || isMe) 
                    ? (emp?.avatarUrl || `https://ui-avatars.com/api/?name=${emp?.name || '?'}`)
                    : `https://ui-avatars.com/api/?name=?&background=27272a&color=52525b&length=1`; // Gri soru işareti avatarı

                const displayBranch = (isAdmin || isMe) ? (emp?.branch || '-') : '***';

                return { 
                    id, 
                    name: displayName, 
                    avatar: displayAvatar, 
                    count, 
                    branch: displayBranch,
                    isMe 
                };
            })
            .filter(Boolean)
            .sort((a, b) => (b?.count || 0) - (a?.count || 0))
            .slice(0, 10);
    }, [salesData, selectedYear, selectedMonth, employees, isAdmin, selectedBranch, currentUser.id, currentUser.branch]);

    // Statistics based on filtered data
    const stats = useMemo(() => {
        const approvedCount = filteredResults.filter(s => s.status === 'Onaylandı').reduce((a, b) => a + b.quantity, 0);
        const pendingCount = filteredResults.filter(s => s.status === 'Bekliyor').reduce((a, b) => a + b.quantity, 0);

        const branchMap: Record<string, { approved: number, pending: number }> = {};
        filteredResults.forEach(s => {
            const b = s.branch || 'Bilinmiyor';
            if (!branchMap[b]) branchMap[b] = { approved: 0, pending: 0 };
            if (s.status === 'Onaylandı') branchMap[b].approved += s.quantity;
            else branchMap[b].pending += s.quantity;
        });

        const chartData = Object.entries(branchMap).map(([name, val]) => ({
            name,
            approved: val.approved,
            pending: val.pending
        })).sort((a,b) => (b.approved + b.pending) - (a.approved + a.pending));

        const productMap: Record<string, number> = {};
        filteredResults.forEach(s => {
            productMap[s.productName] = (productMap[s.productName] || 0) + s.quantity;
        });
        const topProduct = Object.keys(productMap).sort((a, b) => productMap[b] - productMap[a])[0];

        return { approvedCount, pendingCount, chartData, topProduct, topProductVal: productMap[topProduct] || 0 };
    }, [filteredResults]);

    return (
        <div className="h-full w-full p-4 md:p-8 overflow-y-auto custom-scrollbar bg-[#09090b]">
            {/* Header & Global Filters */}
            <div className="mb-8 flex flex-col xl:flex-row justify-between items-start xl:items-end gap-6">
                <div>
                    <h1 className="text-3xl font-bold text-white tracking-tight mb-2 flex items-center gap-3">
                        <ShoppingBag className="text-orange-500" size={32} />
