          const staffOnly = allEmployees.filter(e => e.role !== Role.ADMIN);
          setDashboardEmployees(staffOnly);
      } else {
          setDashboardEmployees([]);
      }

      checkTransfers();

      // 3. Fetch Recent Transfers (ONLY ACTIVE/FUTURE)
