          msgQuery = msgQuery.or(`receiver_id.eq.${currentUser.id},receiver_id.eq.ALL,receiver_id.eq.ADMIN_BOARD`);
      } else {
          msgQuery = msgQuery.or(`receiver_id.eq.${currentUser.id},receiver_id.eq.ALL`);
      }

      const { data: msgData } = await msgQuery;
      if (msgData) {
          const formattedMessages: Message[] = msgData.map((m: any) => ({
              id: m.id,
              senderId: m.sender_id,
              receiverId: m.receiver_id,
              subject: m.subject,
              content: m.content,
              timestamp: m.timestamp,
              read: m.read
          }));
          setRecentMessages(formattedMessages);
      }
  };

  const checkTransfers = async () => {
    try {
        const today = new Date().toISOString().split('T')[0];
        const { data, error } = await supabase.from('calendar_events').select('*');
        if (!error && data) {
            const transfer = data.find((e: any) => 
                e.type === 'Şube Transferi' && 
                e.attendees && e.attendees.includes(currentUser.id) &&
                today >= e.date && today <= (e.end_date || e.date)
            );

            if (transfer) {
                setActiveTransferEvent({
                    id: transfer.id,
                    title: transfer.title,
                    type: transfer.type,
                    date: transfer.date,
                    endDate: transfer.end_date,
                    startTime: transfer.start_time,
                    endTime: transfer.end_time,
                    attendees: transfer.attendees,
                    description: transfer.description
                });
            } else {
                setActiveTransferEvent(null);
            }
        }
