                              </div>
                          )) : (
                              <div className="h-full flex flex-col items-center justify-center text-zinc-600">
                                  <Bell size={32} className="mb-2 opacity-20"/>
                                  <div className="text-sm">Bildirim yok.</div>
                              </div>
