import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

// Define the interface for props to include children
interface Props {
  children?: ReactNode;
}

// Define the interface for state
interface State {
  hasError: boolean;
  error: Error | null;
}

// ErrorBoundary class to catch and handle frontend errors gracefully.
class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Log the error to an error reporting service
    console.error('Uncaught error:', error, errorInfo);
  }

  private handleReset = () => {
      this.setState({ hasError: false, error: null });
      window.location.href = '/'; // Hard reload to clear state
  }

  public render() {
    if (this.state.hasError) {
      // Render a custom fallback UI when an error occurs
      return (
        <div className="min-h-screen w-full bg-zinc-950 flex flex-col items-center justify-center p-4 text-center">
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center">
                <div className="w-16 h-16 bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mb-4 border border-red-500/20">
                    <AlertTriangle size={32} />
                </div>
                <h1 className="text-xl font-bold text-white mb-2">Bir Sorun Oluştu</h1>
                <p className="text-zinc-400 text-sm mb-6">
                    Sistem beklenmeyen bir veri durumuyla karşılaştı. Bu genellikle veritabanı bağlantısı veya eksik veriden kaynaklanır.
                </p>

                <div className="bg-black/30 p-3 rounded-lg border border-zinc-800 w-full mb-6 text-left overflow-hidden">
                    <p className="text-[10px] text-red-400 font-mono break-all">
                        {this.state.error?.message || 'Unknown Error'}
                    </p>
                </div>

                <button 
                    onClick={this.handleReset}
                    className="flex items-center gap-2 px-6 py-3 bg-white text-black hover:bg-zinc-200 font-bold rounded-xl transition-colors w-full justify-center"
                >
                    <RefreshCw size={18} /> Sistemi Yenile
                </button>
            </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { SalesLog, Employee, Role, Branch } from '../types';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, Legend } from 'recharts';
import { Trophy, TrendingUp, ShoppingBag, MapPin, Award, Medal, Calendar, Package, Activity, BarChart3, ListTodo, User, Lock, EyeOff, Filter, ChevronDown, Clock, Tag, Send, Loader2, CheckCircle2, XCircle, Trash2, X, Star, Zap, Crown, Percent } from 'lucide-react';

interface SalesDashboardProps {
    currentUser: Employee;
}

const AKTION_PRODUCTS = [
    "Ploom",
    "Vuse",
    "İqos iluma prime",
    "İqos iluma",
    "İqos one",
    "Veev"
];

const YEARS = [2024, 2025, 2026];
const MONTHS = [
    { v: 1, l: 'Ocak' }, { v: 2, l: 'Şubat' }, { v: 3, l: 'Mart' },
    { v: 4, l: 'Nisan' }, { v: 5, l: 'Mayıs' }, { v: 6, l: 'Haziran' },
    { v: 7, l: 'Temmuz' }, { v: 8, l: 'Ağustos' }, { v: 9, l: 'Eylül' },
    { v: 10, l: 'Ekim' }, { v: 11, l: 'Kasım' }, { v: 12, l: 'Aralık' }
];

const SalesDashboard: React.FC<SalesDashboardProps> = ({ currentUser }) => {
    const { t, formatDate } = useLanguage();
    const [salesData, setSalesData] = useState<SalesLog[]>([]);
    const [employees, setEmployees] = useState<Employee[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    // PERFORMANCE CARD STATE
    const [selectedStaffId, setSelectedStaffId] = useState<string | null>(null);

    const isAdmin = currentUser.role === Role.ADMIN;
    const isMounted = useRef(true);

    // Filter States
    const [selectedBranch, setSelectedBranch] = useState<string>(isAdmin ? 'ALL' : currentUser.branch);
    const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth() + 1);

    // New Sales Form State
    const [salesForm, setSalesForm] = useState({
        product: AKTION_PRODUCTS[0],
        quantity: 1,
        date: new Date().toISOString().split('T')[0]
    });

    useEffect(() => {
        isMounted.current = true;
        fetchData();
        return () => { isMounted.current = false; };
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const { data: sales } = await supabase.from('sales_logs').select('*').order('sale_date', { ascending: false });
            if (sales && isMounted.current) {
                const formattedSales = sales.map((l: any) => ({
                    id: l.id,
                    employeeId: l.employee_id,
                    branch: l.branch,
                    productName: l.product_name,
                    quantity: l.quantity,
                    saleDate: l.sale_date,
                    status: l.status,
                    createdAt: l.created_at
                }));
                setSalesData(formattedSales);
            }

            const { data: profiles } = await supabase.from('profiles').select('*');
            if (profiles && isMounted.current) {
                const formattedEmps = profiles.map((p: any) => ({
                    id: p.id,
                    name: p.full_name,
                    avatarUrl: p.avatar_url || `https://ui-avatars.com/api/?name=${p.full_name}`,
                    branch: p.branch,
                    role: p.role // Rol bilgisi eklendi
                }));
                setEmployees(formattedEmps as Employee[]);
            }
        } catch (err) {
            console.error(err);
        } finally {
            if(isMounted.current) setIsLoading(false);
        }
    };

    // SALES MANAGEMENT FUNCTIONS (Ported from ShiftSchedule)
    const handleSaveSale = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const payload = { 
                employee_id: currentUser.id, 
                branch: currentUser.branch, 
                product_name: salesForm.product, 
                quantity: salesForm.quantity, 
                sale_date: salesForm.date, 
                status: 'Bekliyor' 
            };
            const { data, error } = await supabase.from('sales_logs').insert([payload]).select();
            if (error) throw error;

            if (data && isMounted.current) {
                const newLog = {
                    id: data[0].id,
                    employeeId: data[0].employee_id,
                    branch: data[0].branch,
                    productName: data[0].product_name,
                    quantity: data[0].quantity,
                    saleDate: data[0].sale_date,
                    status: 'Bekliyor',
                    createdAt: data[0].created_at
                };
                setSalesData(prev => [newLog, ...prev]);
                alert("Satış kaydı başarıyla oluşturuldu ve onaya gönderildi.");
            }
        } catch (err: any) { 
            alert(err.message); 
        } finally { 
            if(isMounted.current) setIsSaving(false); 
        }
    };

    const handleUpdateStatus = async (id: string, newStatus: 'Onaylandı' | 'Reddedildi') => {
        if(!isAdmin) return;
        try {
            await supabase.from('sales_logs').update({ status: newStatus }).eq('id', id);
            setSalesData(prev => prev.map(l => l.id === id ? { ...l, status: newStatus } : l));
        } catch (err) { console.error(err); }
    };

    const handleDeleteSale = async (id: string) => {
        if(!confirm("Bu kaydı silmek istediğinize emin misiniz?")) return;
        try {
            await supabase.from('sales_logs').delete().eq('id', id);
            setSalesData(prev => prev.filter(l => l.id !== id));
        } catch (err) { console.error(err); }
    };

    // Filtered Data Logic
    const filteredResults = useMemo(() => {
        return salesData.filter(s => {
            const date = new Date(s.saleDate);
            const matchesYear = date.getFullYear() === selectedYear;
            const matchesMonth = (date.getMonth() + 1) === selectedMonth;

            // KRİTİK: Admin seçtiği şubeyi görür, Personel SADECE kendi şubesini görür.
            const branchToMatch = isAdmin ? selectedBranch : currentUser.branch;
            const matchesBranch = branchToMatch === 'ALL' || s.branch === branchToMatch;

            return matchesYear && matchesMonth && matchesBranch;
        });
    }, [salesData, selectedYear, selectedMonth, selectedBranch, isAdmin, currentUser.branch]);

    // Leaderboard Data (With Masking Logic & GLOBAL SCOPE)
    const leaderboardData = useMemo(() => {
        const currentMonthData = salesData.filter(s => {
            const d = new Date(s.saleDate);
            return d.getFullYear() === selectedYear && 
                   (d.getMonth() + 1) === selectedMonth && 
                   s.status === 'Onaylandı';
        });

        const personnelMap: Record<string, number> = {};
        currentMonthData.forEach(s => {
            const empId = s.employeeId || 'unknown';
            personnelMap[empId] = (personnelMap[empId] || 0) + s.quantity;
        });

        return Object.entries(personnelMap)
            .map(([id, count]) => {
                if (id === 'unknown') return null;
                const emp = employees.find(e => e.id === id);
                const isMe = id === currentUser.id;

                const displayName = (isAdmin || isMe) ? (emp?.name || 'Bilinmeyen') : '???????';
                const displayAvatar = (isAdmin || isMe) 
                    ? (emp?.avatarUrl || `https://ui-avatars.com/api/?name=${emp?.name || '?'}`)
                    : `https://ui-avatars.com/api/?name=?&background=27272a&color=52525b&length=1`; 
                const displayBranch = (isAdmin || isMe) ? (emp?.branch || '-') : '***';

                return { id, name: displayName, avatar: displayAvatar, count, branch: displayBranch, isMe, role: emp?.role };
            })
            .filter(Boolean)
            .sort((a, b) => (b?.count || 0) - (a?.count || 0));
    }, [salesData, selectedYear, selectedMonth, employees, isAdmin, currentUser.id]);

    // Statistics based on filtered data
    const stats = useMemo(() => {
        const approvedCount = filteredResults.filter(s => s.status === 'Onaylandı').reduce((a, b) => a + b.quantity, 0);
        const pendingCount = filteredResults.filter(s => s.status === 'Bekliyor').reduce((a, b) => a + b.quantity, 0);

        const branchMap: Record<string, { approved: number, pending: number }> = {};
        filteredResults.forEach(s => {
            const b = s.branch || 'Bilinmiyor';
            if (!branchMap[b]) branchMap[b] = { approved: 0, pending: 0 };
            if (s.status === 'Onaylandı') branchMap[b].approved += s.quantity;
            else branchMap[b].pending += s.quantity;
        });

        const chartData = Object.entries(branchMap).map(([name, val]) => ({
            name,
            approved: val.approved,
            pending: val.pending
        })).sort((a,b) => (b.approved + b.pending) - (a.approved + a.pending));

        const productMap: Record<string, number> = {};
        filteredResults.forEach(s => {
            productMap[s.productName] = (productMap[s.productName] || 0) + s.quantity;
        });
        const topProduct = Object.keys(productMap).sort((a, b) => productMap[b] - productMap[a])[0];

        return { approvedCount, pendingCount, chartData, topProduct, topProductVal: productMap[topProduct] || 0 };
    }, [filteredResults]);

    // --- HELPER: STAFF CARD CALCULATIONS ---
    const getStaffPerformance = (staffId: string) => {
        const staffSales = salesData.filter(s => s.employeeId === staffId);
        const totalSales = staffSales.reduce((a, b) => a + b.quantity, 0);
        const approved = staffSales.filter(s => s.status === 'Onaylandı').length;
        const rejected = staffSales.filter(s => s.status === 'Reddedildi').length;

        const productBreakdown: Record<string, number> = {};
        staffSales.forEach(s => {
            productBreakdown[s.productName] = (productBreakdown[s.productName] || 0) + s.quantity;
        });
        const favoriteProduct = Object.keys(productBreakdown).sort((a, b) => productBreakdown[b] - productBreakdown[a])[0] || '-';

        // Rank Calculation (Global)
        const rank = leaderboardData.findIndex(i => i?.id === staffId) + 1;

        return { totalSales, approved, rejected, favoriteProduct, rank, history: staffSales.slice(0, 5) };
    };

    // --- RENDER: PERFORMANCE CARD MODAL ---
    const renderPerformanceCard = () => {
        if (!selectedStaffId || !isAdmin) return null;

        const staff = employees.find(e => e.id === selectedStaffId);
        if (!staff) return null;

        const perf = getStaffPerformance(selectedStaffId);
        const rankColor = perf.rank === 1 ? 'from-yellow-400 to-amber-600' : perf.rank === 2 ? 'from-slate-300 to-slate-500' : perf.rank === 3 ? 'from-amber-700 to-orange-800' : 'from-indigo-600 to-blue-700';
        const rankIcon = perf.rank === 1 ? <Crown size={32} className="text-white drop-shadow-lg" /> : perf.rank === 2 ? <Medal size={32} className="text-slate-100" /> : perf.rank === 3 ? <Medal size={32} className="text-amber-100" /> : <Star size={32} className="text-indigo-200" />;

        return (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-in fade-in duration-300" onClick={() => setSelectedStaffId(null)}>
                <div className="w-full max-w-md bg-zinc-900 border border-zinc-700/50 rounded-3xl shadow-2xl overflow-hidden relative" onClick={e => e.stopPropagation()}>

                    {/* Decorative Background */}
                    <div className={`absolute top-0 w-full h-32 bg-gradient-to-r ${rankColor} opacity-90`}></div>
                    <div className="absolute top-0 left-0 w-full h-32 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-20"></div>

                    <button onClick={() => setSelectedStaffId(null)} className="absolute top-4 right-4 p-2 bg-black/20 hover:bg-black/40 rounded-full text-white transition-colors z-20 backdrop-blur-sm">
                        <X size={20} />
                    </button>

                    <div className="relative pt-16 px-6 pb-6 text-center">
                        {/* Avatar & Rank */}
                        <div className="relative inline-block mb-4">
                            <div className="w-24 h-24 rounded-full border-4 border-zinc-900 bg-zinc-800 overflow-hidden shadow-xl">
                                <img src={staff.avatarUrl} className="w-full h-full object-cover" />
                            </div>
                            <div className={`absolute -bottom-2 -right-2 w-10 h-10 rounded-full flex items-center justify-center bg-gradient-to-br ${rankColor} border-4 border-zinc-900 shadow-lg`}>
                                <span className="text-sm font-black text-white">#{perf.rank > 0 ? perf.rank : '-'}</span>
                            </div>
                        </div>

                        {/* Name & Title */}
                        <h2 className="text-2xl font-bold text-white mb-1">{staff.name}</h2>
                        <div className="flex items-center justify-center gap-2 text-sm text-zinc-400 mb-6">
                            <span className="px-2 py-0.5 rounded bg-zinc-800 border border-zinc-700">{staff.role}</span>
                            <span className="flex items-center gap-1 text-indigo-400"><MapPin size={12}/> {staff.branch}</span>
                        </div>

                        {/* KPI Grid */}
                        <div className="grid grid-cols-2 gap-4 mb-6">
                            <div className="bg-zinc-800/50 p-4 rounded-2xl border border-zinc-700/50">
                                <p className="text-xs text-zinc-500 uppercase font-bold mb-1 flex items-center gap-1"><ShoppingBag size={12}/> Toplam Satış</p>
                                <p className="text-2xl font-black text-white">{perf.totalSales}</p>
                            </div>
                            <div className="bg-zinc-800/50 p-4 rounded-2xl border border-zinc-700/50">
                                <p className="text-xs text-zinc-500 uppercase font-bold mb-1 flex items-center gap-1"><Zap size={12}/> Favori Ürün</p>
                                <p className="text-sm font-bold text-white truncate">{perf.favoriteProduct}</p>
                            </div>
                            <div className="bg-zinc-800/50 p-4 rounded-2xl border border-zinc-700/50">
                                <p className="text-xs text-zinc-500 uppercase font-bold mb-1 flex items-center gap-1"><CheckCircle2 size={12}/> Onaylanan</p>
                                <p className="text-xl font-bold text-green-400">{perf.approved}</p>
                            </div>
                            <div className="bg-zinc-800/50 p-4 rounded-2xl border border-zinc-700/50">
                                <p className="text-xs text-zinc-500 uppercase font-bold mb-1 flex items-center gap-1"><Percent size={12}/> Başarı Oranı</p>
                                <p className="text-xl font-bold text-indigo-400">
                                    {perf.totalSales > 0 ? Math.round((perf.approved / perf.totalSales) * 100) : 0}%
                                </p>
                            </div>
                        </div>

                        {/* Badges / Motivation */}
                        <div className="mb-6 text-left">
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-3 ml-1">Kazanılan Rozetler</h4>
                            <div className="flex gap-2 flex-wrap">
                                {perf.rank === 1 && <span className="px-3 py-1 bg-yellow-500/10 text-yellow-400 border border-yellow-500/20 rounded-full text-xs font-bold flex items-center gap-1"><Crown size={12}/> Lider</span>}
                                {perf.totalSales > 50 && <span className="px-3 py-1 bg-purple-500/10 text-purple-400 border border-purple-500/20 rounded-full text-xs font-bold flex items-center gap-1"><Zap size={12}/> Hızlı Satıcı</span>}
                                {perf.approved > 20 && <span className="px-3 py-1 bg-green-500/10 text-green-400 border border-green-500/20 rounded-full text-xs font-bold flex items-center gap-1"><CheckCircle2 size={12}/> Güvenilir</span>}
                                <span className="px-3 py-1 bg-zinc-800 text-zinc-400 border border-zinc-700 rounded-full text-xs flex items-center gap-1"> +{Math.max(0, (staff.badges?.length || 0))} Diğer</span>
                            </div>
                        </div>

                        {/* Recent History */}
                        <div className="text-left bg-zinc-950/50 rounded-xl p-4 border border-zinc-800">
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-3">Son İşlemler</h4>
                            <div className="space-y-2">
                                {perf.history.length === 0 ? <p className="text-xs text-zinc-600">Kayıt yok.</p> : perf.history.map((h: any) => (
                                    <div key={h.id} className="flex justify-between items-center text-xs">
                                        <span className="text-zinc-300">{h.productName}</span>
                                        <div className="flex items-center gap-2">
                                            <span className="font-mono text-white">x{h.quantity}</span>
