                    </div>

                    <div className="flex gap-1 overflow-x-auto">
                        {isAdmin ? (
                            <>
                                <button 
                                    onClick={() => setSelectedBranch('ALL')}
                                    className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${selectedBranch === 'ALL' ? 'bg-white text-black' : 'text-zinc-500 hover:text-zinc-300'}`}
                                >
                                    Tümü
                                </button>
                                {Object.values(Branch).map(b => (
                                    <button 
                                        key={b}
                                        onClick={() => setSelectedBranch(b)}
                                        className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${selectedBranch === b ? 'bg-orange-600 text-white' : 'text-zinc-500 hover:text-zinc-300'}`}
                                    >
                                        {b}
                                    </button>
                                ))}
                            </>
                        ) : (
                            <div className="px-4 py-1.5 bg-orange-600/20 text-orange-400 rounded-lg text-xs font-bold border border-orange-500/30 flex items-center gap-2">
                                <MapPin size={12} />
                                {currentUser.branch} Şubesi Verileri
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* STAFF: SALES INPUT FORM (Ported from ShiftSchedule) */}
            {!isAdmin && (
                <div className="mb-8 bg-orange-600 border border-orange-500 rounded-2xl p-6 shadow-xl shadow-orange-950/20">
                    <div className="flex flex-col lg:flex-row items-center gap-6">
                        <div className="flex-1 w-full space-y-2">
                            <h3 className="text-white font-black uppercase text-sm flex items-center gap-2">
                                <Tag size={16}/> Yeni Satış Girişi
                            </h3>
                            <p className="text-orange-100 text-xs">Satış verilerinizi şubeniz üzerinden sisteme kaydedin.</p>
                        </div>
                        <form onSubmit={handleSaveSale} className="w-full lg:w-auto flex flex-wrap lg:flex-nowrap items-end gap-3">
                            <div className="flex-1 lg:w-40 min-w-[140px]">
                                <input type="date" value={salesForm.date} onChange={e => setSalesForm({...salesForm, date: e.target.value})} className="w-full bg-orange-700/50 border border-orange-400/30 rounded-xl px-4 py-3 text-sm text-white outline-none focus:bg-orange-700" />
                            </div>
                            <div className="flex-[2] lg:w-64 min-w-[180px]">
                                <select value={salesForm.product} onChange={e => setSalesForm({...salesForm, product: e.target.value})} className="w-full bg-orange-700/50 border border-orange-400/30 rounded-xl px-4 py-3 text-sm text-white outline-none focus:bg-orange-700">
                                    {AKTION_PRODUCTS.map(p => <option key={p} value={p} className="bg-orange-900">{p}</option>)}
                                </select>
                            </div>
                            <div className="w-24">
                                <input type="number" min="1" value={salesForm.quantity} onChange={e => setSalesForm({...salesForm, quantity: parseInt(e.target.value)})} className="w-full bg-orange-700/50 border border-orange-400/30 rounded-xl px-4 py-3 text-sm text-white font-bold text-center outline-none focus:bg-orange-700" />
                            </div>
                            <button type="submit" disabled={isSaving} className="px-6 py-3 bg-white text-orange-600 font-black rounded-xl hover:scale-105 active:scale-95 transition-all shadow-lg flex items-center gap-2">
                                {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
                                Ekle
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Quick Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-20 h-20 bg-green-500/10 rounded-full blur-2xl"></div>
                    <p className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">Onaylı Satış</p>
                    <p className="text-3xl font-bold text-green-400">{stats.approvedCount}</p>
                </div>
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-20 h-20 bg-orange-500/10 rounded-full blur-2xl"></div>
                    <p className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">Onay Bekleyen</p>
                    <p className="text-3xl font-bold text-orange-400">{stats.pendingCount}</p>
                </div>
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-20 h-20 bg-blue-500/10 rounded-full blur-2xl"></div>
                    <p className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">Toplam İşlem</p>
                    <p className="text-3xl font-bold text-white">{stats.approvedCount + stats.pendingCount}</p>
                </div>
                <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-20 h-20 bg-purple-500/10 rounded-full blur-2xl"></div>
                    <p className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">En Çok Satan</p>
                    <div className="flex items-baseline gap-2">
                        <p className="text-xl font-bold text-purple-400 truncate">{stats.topProduct || '-'}</p>
                        <span className="text-xs text-zinc-600">({stats.topProductVal})</span>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-8">
                {/* Visual Chart */}
                <div className="lg:col-span-2 bg-zinc-900/30 border border-zinc-800 rounded-3xl p-6 flex flex-col">
                    <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                        <BarChart3 className="text-indigo-500" size={20}/>
                        {isAdmin ? 'Şube Bazlı Dağılım' : `${currentUser.branch} Şube Analizi`}
                    </h3>
                    <div className="flex-1 min-h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={stats.chartData} barSize={40}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#27272a" vertical={false} />
                                <XAxis dataKey="name" stroke="#71717a" fontSize={12} tickLine={false} axisLine={false} dy={10}/>
                                <YAxis stroke="#71717a" fontSize={12} tickLine={false} axisLine={false} />
                                <Tooltip 
                                    cursor={{fill: '#27272a', opacity: 0.2}}
                                    contentStyle={{ backgroundColor: '#09090b', border: '1px solid #27272a', borderRadius: '12px', color: '#fff' }}
                                />
                                <Legend wrapperStyle={{paddingTop: '20px'}} />
                                <Bar dataKey="approved" name="Onaylı" stackId="a" fill="#22c55e" radius={[0, 0, 4, 4]} />
                                <Bar dataKey="pending" name="Bekliyor" stackId="a" fill="#f97316" radius={[4, 4, 0, 0]} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Mini Leaderboard with Privacy Masking - NOW CLICKABLE FOR ADMIN */}
                <div className="bg-zinc-900/30 border border-zinc-800 rounded-3xl p-6 flex flex-col h-[400px]">
                    <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2 sticky top-0 bg-zinc-900/0 backdrop-blur-sm z-10">
                        <Trophy className="text-yellow-500" size={20}/>
                        {t('sales.leaderboard')}
                        {isAdmin && <span className="text-[9px] bg-zinc-800 text-zinc-400 px-2 py-0.5 rounded ml-auto">Detay için tıkla</span>}
                    </h3>
                    <div className="space-y-3 flex-1 overflow-y-auto custom-scrollbar pr-2">
                        {leaderboardData.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center text-zinc-600 opacity-30">
                                <Award size={48} />
                                <p className="text-xs mt-2">Henüz veri yok</p>
                            </div>
                        ) : leaderboardData.map((item, idx) => (
                            <div 
                                key={item!.id}
                                onClick={() => isAdmin && setSelectedStaffId(item!.id)}
                                className={`flex items-center gap-3 p-3 border rounded-2xl transition-all relative overflow-hidden group ${
                                    item!.isMe ? 'bg-orange-500/10 border-orange-500/50 sticky top-0 bottom-0 z-10 shadow-lg' : 'bg-zinc-900/50 border-zinc-800'
                                } ${isAdmin ? 'cursor-pointer hover:border-indigo-500/50 hover:bg-zinc-800' : ''}`}
                            >
                                <span className={`font-bold w-6 text-center ${item!.isMe ? 'text-orange-400' : 'text-zinc-600'}`}>{idx + 1}</span>
                                <div className="w-8 h-8 rounded-full overflow-hidden border border-zinc-700 bg-zinc-800 shrink-0">
                                    <img src={item!.avatar} alt="" className="w-full h-full object-cover" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <p className={`text-xs font-bold truncate ${item!.isMe ? 'text-orange-400' : 'text-zinc-200'}`}>
                                        {item!.name} {item!.isMe && <span className="text-[10px] ml-1">(Siz)</span>}
                                    </p>
                                    <p className="text-[9px] text-zinc-500 uppercase">{item!.branch}</p>
                                </div>
                                <span className={`text-sm font-bold ${item!.isMe ? 'text-orange-400' : 'text-zinc-400'}`}>{item!.count}</span>

                                {isAdmin && <ChevronDown className="text-zinc-600 opacity-0 group-hover:opacity-100 transition-opacity -rotate-90" size={14} />}
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* DETAILED TABLE SECTION (UPDATED WITH ACTIONS) */}
            <div className="bg-zinc-900/30 border border-zinc-800 rounded-3xl overflow-hidden shadow-2xl">
