interface CalendarProps {
    currentUser: Employee;
}

interface DisplayEvent extends CalendarEvent {
    isTask?: boolean;
    isShift?: boolean;
    status?: string;
}

const Calendar: React.FC<CalendarProps> = ({ currentUser }) => {
  // --- STATE ---
  const [viewDate, setViewDate] = useState(new Date()); // Haftanın referans günü

  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { t, formatDate, language } = useLanguage();

  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [shifts, setShifts] = useState<any[]>([]); // New Shift State
  const [employees, setEmployees] = useState<Employee[]>([]); // New Employee State for Attendees

  // Modal & Selection
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<DisplayEvent | null>(null);

  // Filters
  const [selectedBranches, setSelectedBranches] = useState<Branch[]>([]);
  const [targetBranch, setTargetBranch] = useState<Branch>(Branch.DOM);

  // Form
  const [newEventForm, setNewEventForm] = useState<Partial<CalendarEvent>>({
      title: '',
      type: 'Toplantı',
      date: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0], 
      startTime: '09:00',
      endTime: '10:00',
      attendees: [],
      description: ''
  });

  // --- DATA FETCHING ---
  useEffect(() => {
    const fetchData = async () => {
        setIsLoading(true);
        try {
            // 1. Events
            let eventQuery = supabase.from('calendar_events').select('*');
            if (currentUser.role !== Role.ADMIN) {
                eventQuery = eventQuery.contains('attendees', [currentUser.id]);
            }
            const { data: eventData } = await eventQuery;
            if (eventData) {
                const dbEvents: CalendarEvent[] = eventData.map((e: any) => ({
                    id: e.id, title: e.title, type: e.type, date: e.date,
                    endDate: e.end_date || e.date, startTime: e.start_time, endTime: e.end_time,
                    attendees: e.attendees || [], description: e.description
                }));
                setEvents(dbEvents);
            }

            // 2. Tasks
            let taskQuery = supabase.from('tasks').select('*');
            if (currentUser.role !== Role.ADMIN) {
                taskQuery = taskQuery.contains('assigned_to', [currentUser.id]);
            }
            const { data: taskData } = await taskQuery;
            if(taskData) {
                 const dbTasks: Task[] = taskData.map((t: any) => ({
                    id: t.id, title: t.title, description: t.description,
                    assignedTo: t.assigned_to || [], dueDate: t.due_date,
                    priority: t.priority, status: t.status, progress: t.progress, checklist: t.checklist || []
                }));
                setTasks(dbTasks);
            }

            // 3. Shifts (Vardiyalar)
            const { data: shiftData } = await supabase
                .from('shift_schedules')
                .select('*');

            if (shiftData) {
                setShifts(shiftData);
            }

            // 4. Employees (For Attendees Selector) - EXCLUDE ADMINS
            const { data: empData } = await supabase.from('profiles').select('*').neq('role', 'Admin');
            if (empData) {
                const fetchedEmployees: Employee[] = empData.map((e: any) => ({
                    id: e.id,
                    name: e.full_name,
                    email: e.email,
                    role: e.role,
                    branch: e.branch,
                    hourlyRate: e.hourly_rate,
                    taxClass: e.tax_class,
                    avatarUrl: e.avatar_url || `https://ui-avatars.com/api/?name=${e.full_name}`,
                    advances: 0,
                    metrics: e.metrics
                }));
                setEmployees(fetchedEmployees);
            }

        } catch (e) {
            console.log("Error:", e);
        } finally {
            setIsLoading(false);
        }
    };
    fetchData();
  }, [currentUser]); 

  // --- LOGIC ---
  const combinedEvents = useMemo((): DisplayEvent[] => {
      const filteredEvents = currentUser.role === Role.ADMIN ? events : events.filter(evt => evt.attendees.includes(currentUser.id));
      const filteredTasks = currentUser.role === Role.ADMIN ? tasks : tasks.filter(t => t.assignedTo.includes(currentUser.id));

      const taskEvents: DisplayEvent[] = filteredTasks.map(t => ({
          id: t.id, title: t.title, type: 'Diğer', date: t.dueDate, endDate: t.dueDate,
          startTime: '09:00', endTime: '18:00', attendees: t.assignedTo, description: t.description,
          isTask: true, status: t.status
      }));

      // Generate Shift Events from Roster Data (UPDATED for Transposed Table)
      const shiftEvents: DisplayEvent[] = shifts.flatMap(schedule => {
          const start = new Date(schedule.week_start_date);
          const timeLabel = schedule.time_slot || "09:00 - 17:00";

          return schedule.days.map((assignedEmpId: string, index: number) => {
              // Filter: Only create event if this slot is assigned to the current user
              if (assignedEmpId !== currentUser.id) return null;

              const eventDate = new Date(start);
              eventDate.setDate(eventDate.getDate() + index);
              const dateStr = eventDate.toISOString().split('T')[0];

              // Basit parse (örn: "09:00 - 17:00" veya "09-17")
              // Handle "9-15" format from screenshot
              let sTime = '08:00';
              let eTime = '18:00';

              if (timeLabel.includes('-')) {
                  const parts = timeLabel.split('-');
                  sTime = parts[0].trim();
                  eTime = parts[1].trim();
                  // Normalize "9" to "09:00" if needed
                  if (!sTime.includes(':') && sTime.length <= 2) sTime = sTime.padStart(2, '0') + ":00";
                  if (!eTime.includes(':') && eTime.length <= 2) eTime = eTime.padStart(2, '0') + ":00";
              }

              return {
                  id: `shift_${schedule.id}_${index}`,
                  title: `Vardiya: ${timeLabel}`,
                  type: 'Diğer', 
                  date: dateStr,
                  endDate: dateStr,
                  startTime: sTime,
                  endTime: eTime,
                  attendees: [currentUser.id],
                  description: `Şube: ${schedule.branch}`,
                  isShift: true
              } as DisplayEvent;
          }).filter(Boolean) as DisplayEvent[];
      });

      return [...(filteredEvents as DisplayEvent[]), ...taskEvents, ...shiftEvents];
  }, [events, tasks, shifts, currentUser]);

  // WEEK LOGIC
  const getStartOfWeek = (d: Date) => {
      const date = new Date(d);
      const day = date.getDay(); 
      const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust when day is Sunday
      return new Date(date.setDate(diff));
  };

  const currentWeekStart = useMemo(() => getStartOfWeek(viewDate), [viewDate]);

  const weekDays = useMemo(() => {
      const days = [];
      for (let i = 0; i < 7; i++) {
          const d = new Date(currentWeekStart);
          d.setDate(d.getDate() + i);
          days.push(d);
      }
      return days;
  }, [currentWeekStart]);

  const changeWeek = (direction: 'prev' | 'next') => {
      const newDate = new Date(viewDate);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setViewDate(newDate);
  };

  const isToday = (d: Date) => {
      const today = new Date();
      return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
  };

  const getText = (text?: string) => {
    if (!text) return '';
    return text.startsWith('task.mock') ? t(text) : text;
  };

  // Handlers
  const handleSaveEvent = async (e: React.FormEvent) => {
      e.preventDefault();
      const isTransfer = newEventForm.type === 'Şube Transferi';
      if (!newEventForm.title && !isTransfer) return alert(t('cal.warnTitle'));

      setIsSaving(true);
      try {
          const finalTitle = isTransfer ? `${newEventForm.attendees?.length} Personel -> ${targetBranch}` : newEventForm.title!;
          const dbPayload = {
              title: finalTitle, type: newEventForm.type, date: newEventForm.date,
              end_date: newEventForm.endDate || newEventForm.date, start_time: newEventForm.startTime,
              end_time: newEventForm.endTime, attendees: newEventForm.attendees || [], description: newEventForm.description
          };
          const { data, error } = await supabase.from('calendar_events').insert([dbPayload]).select();
          if (error) throw error;

          if(isTransfer && currentUser.role === Role.ADMIN) {
               await supabase.from('profiles').update({ branch: targetBranch }).in('id', newEventForm.attendees || []);
          }

          if (data && data[0]) {
              // FIX: Convert DB response (snake_case) to Frontend Type (camelCase) to prevent crash
              const newEvent: CalendarEvent = {
                  id: data[0].id,
                  title: data[0].title,
                  type: data[0].type,
                  date: data[0].date,
                  endDate: data[0].end_date,
                  startTime: data[0].start_time,
                  endTime: data[0].end_time,
                  attendees: data[0].attendees || [],
                  description: data[0].description
              };
              setEvents(prev => [...prev, newEvent]);
              setShowAddModal(false);
              alert(t('common.success'));
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handleDeleteEvent = async () => {
      if (!selectedEvent || selectedEvent.isTask || selectedEvent.isShift) return;
      if (confirm('Silmek istediğinize emin misiniz?')) {
          const { error } = await supabase.from('calendar_events').delete().eq('id', selectedEvent.id);
          if (!error) {
              setEvents(events.filter(e => e.id !== selectedEvent.id));
              setSelectedEvent(null);
          }
      }
  };

  const toggleBranchSelection = (branch: Branch) => {
    setSelectedBranches(prev => prev.includes(branch) ? prev.filter(b => b !== branch) : [...prev, branch]);
  };

  const toggleAttendee = (id: string) => {
    setNewEventForm(prev => {
        const cur = prev.attendees || [];
        return cur.includes(id) ? { ...prev, attendees: cur.filter(x => x !== id) } : { ...prev, attendees: [...cur, id] };
    });
  };

  // --- WEEK STATS ---
  const weekStats = useMemo(() => {
      const startStr = weekDays[0].toISOString().split('T')[0];
      const endStr = weekDays[6].toISOString().split('T')[0];

      const eventsInWeek = combinedEvents.filter(e => e.date >= startStr && e.date <= endStr);

      return {
          total: eventsInWeek.length,
          meetings: eventsInWeek.filter(e => e.type === 'Toplantı').length,
          transfers: eventsInWeek.filter(e => e.type === 'Şube Transferi').length,
          tasks: eventsInWeek.filter(e => e.isTask).length
      };
  }, [combinedEvents, weekDays]);

  return (
    <div className="flex h-full relative overflow-hidden bg-zinc-950">

        {/* ADD EVENT MODAL */}
        {showAddModal && (
            <div className="fixed inset-0 z-[100] flex justify-center items-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in">
                <div className="bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/80 backdrop-blur">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            {newEventForm.type === 'Şube Transferi' ? <Rocket size={20} className="text-orange-500"/> : <CalendarIcon size={20} className="text-indigo-500"/>}
                            {t('cal.newEvent')}
                        </h3>
                        <button onClick={() => setShowAddModal(false)}><X size={20} className="text-zinc-500 hover:text-white"/></button>
                    </div>
                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1">
                        <form onSubmit={handleSaveEvent} className="space-y-5">
                            {/* Type */}
                            <div>
                                <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.type')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {['Toplantı', 'Montaj', 'Teslim Tarihi', 'Şube Transferi', 'Diğer'].map(type => (
                                        <button key={type} type="button" onClick={() => setNewEventForm({...newEventForm, type: type as any})}
                                            className={`px-3 py-1.5 rounded-lg text-xs font-medium border whitespace-nowrap transition-all ${newEventForm.type === type ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>
                                            {type === 'Şube Transferi' ? t('cal.type.transfer') : type}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Title (If not transfer) */}
                            {newEventForm.type !== 'Şube Transferi' && (
                                <div>
                                    <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.eventTitle')}</label>
                                    <input type="text" required value={newEventForm.title} onChange={e => setNewEventForm({...newEventForm, title: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-white focus:border-indigo-500 outline-none" />
                                </div>
                            )}

                            {/* Transfer Logic */}
                            {newEventForm.type === 'Şube Transferi' && (
                                <div className="p-3 bg-orange-950/20 border border-orange-500/20 rounded-lg">
                                    <label className="text-xs font-bold text-orange-400 block mb-2">{t('cal.targetBranch')}</label>
                                    <div className="flex flex-wrap gap-2">
                                        {Object.values(Branch).map(branch => (
                                            <button key={branch} type="button" onClick={() => setTargetBranch(branch)} className={`px-2 py-1 text-xs rounded border ${targetBranch === branch ? 'bg-orange-600 text-white border-orange-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>{branch}</button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Dates */}
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startDate')}</label><input type="date" value={newEventForm.date} onChange={e => setNewEventForm({...newEventForm, date: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startTime')}</label><input type="time" value={newEventForm.startTime} onChange={e => setNewEventForm({...newEventForm, startTime: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                            </div>

                            {/* Attendees Selector */}
                            <div className="p-4 bg-zinc-950/50 border border-zinc-800 rounded-xl space-y-3">
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.branchFilter')}</label>
                                <div className="flex gap-2 flex-wrap">
                                    {Object.values(Branch).map(b => (
                                        <button key={b} type="button" onClick={() => toggleBranchSelection(b)} className={`px-2 py-1 text-[10px] rounded border ${selectedBranches.includes(b) ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-500 border-zinc-800'}`}>{b}</button>
                                    ))}
                                </div>
                                <div className="h-px bg-zinc-800"></div>
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.attendees')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {employees.filter(e => selectedBranches.length === 0 || selectedBranches.includes(e.branch)).map(emp => (
                                        <div key={emp.id} onClick={() => toggleAttendee(emp.id)} className={`cursor-pointer flex flex-col items-center gap-1 min-w-[50px] p-2 rounded-lg border transition-all ${newEventForm.attendees?.includes(emp.id) ? 'bg-indigo-500/20 border-indigo-500' : 'bg-zinc-900 border-zinc-800'}`}>
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <span className="text-[9px] text-zinc-400 truncate w-full text-center">{emp.name.split(' ')[0]}</span>
                                        </div>
                                    ))}
                                    {employees.length === 0 && <div className="text-xs text-zinc-500">{t('cal.loadingStaff')}</div>}
                                </div>
                            </div>

                            {/* Footer */}
                            <div className="pt-4 flex gap-3">
                                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 bg-zinc-800 text-zinc-400 rounded-xl text-sm">{t('tasks.cancel')}</button>
                                <button type="submit" disabled={isSaving} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg">
                                    {isSaving ? '...' : t('cal.saveEvent')}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* --- LEFT PANEL: SUMMARY & NAV (HIDDEN ON MOBILE) --- */}
        <div className="w-full md:w-80 bg-zinc-950 border-b md:border-b-0 md:border-r border-zinc-800 flex-col hidden md:flex">
            <div className="p-6 border-b border-zinc-900">
                <h2 className="text-xl font-bold text-white mb-1">Ajanda</h2>
                <p className="text-xs text-zinc-500">Haftalık Planlama</p>
            </div>

            <div className="p-6 space-y-6 flex-1 overflow-y-auto">
                {/* Stats Card */}
                <div className="bg-zinc-900/50 rounded-xl border border-zinc-800 p-4 space-y-4">
                    <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest">{t('cal.week')}</h3>
                    <div className="grid grid-cols-2 gap-3">
                        <div className="p-3 bg-zinc-950 rounded-lg border border-zinc-800">
                            <span className="text-2xl font-bold text-white block">{weekStats.total}</span>
                            <span className="text-[10px] text-zinc-500">{t('cal.totalEvent')}</span>
                        </div>
                        <div className="p-3 bg-indigo-950/30 rounded-lg border border-indigo-500/20">
                            <span className="text-2xl font-bold text-indigo-400 block">{weekStats.meetings}</span>
                            <span className="text-[10px] text-indigo-300/70">{t('cal.type.meeting')}</span>
                        </div>
                        <div className="p-3 bg-orange-950/30 rounded-lg border border-orange-500/20">
                            <span className="text-2xl font-bold text-orange-400 block">{weekStats.transfers}</span>
                            <span className="text-[10px] text-orange-300/70">Transfer</span>
                        </div>
                        <div className="p-3 bg-blue-950/30 rounded-lg border border-blue-500/20">
                            <span className="text-2xl font-bold text-blue-400 block">{weekStats.tasks}</span>
                            <span className="text-[10px] text-blue-300/70">Görev</span>
                        </div>
                    </div>
                </div>

                <div className="p-4 rounded-xl border border-zinc-800 bg-zinc-900/30">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="w-2 h-2 rounded-full bg-green-500"></div>
                        <span className="text-xs text-zinc-300">{t('cal.today')}</span>
                    </div>
                    <div className="text-sm font-medium text-white">{formatDate(new Date(), { weekday: 'long', day: 'numeric', month: 'long' })}</div>
                </div>
            </div>

            {currentUser.role === Role.ADMIN && (
                <div className="p-6 border-t border-zinc-900">
                    <button 
                        onClick={() => { setNewEventForm(p => ({...p, date: new Date().toISOString().split('T')[0]})); setShowAddModal(true); }}
                        className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 transition-all active:scale-95"
                    >
                        <Plus size={18} /> {t('cal.newEvent')}
                    </button>
                </div>
            )}
        </div>

        {/* --- MAIN CONTENT: WEEKLY AGENDA LIST --- */}
        <div className="flex-1 flex flex-col h-full bg-zinc-950 relative">

            {/* Header / Week Nav */}
            <div className="p-4 md:p-6 border-b border-zinc-800 flex items-center justify-between bg-zinc-950/90 backdrop-blur z-20 sticky top-0">
                <div className="flex items-center gap-4">
                    <button onClick={() => changeWeek('prev')} className="p-2 hover:bg-zinc-900 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronLeft size={20}/></button>
                    <div>
                        <h2 className="text-lg md:text-xl font-bold text-white text-center min-w-[150px]">
                            {formatDate(weekDays[0], {day: 'numeric', month: 'short'})} - {formatDate(weekDays[6], {day: 'numeric', month: 'short', year: 'numeric'})}
                        </h2>
                    </div>
                    <button onClick={() => changeWeek('next')} className="p-2 hover:bg-zinc-900 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronRight size={20}/></button>
                </div>

                {/* Mobile Add Button */}
                <button 
                    onClick={() => { setNewEventForm(p => ({...p, date: new Date().toISOString().split('T')[0]})); setShowAddModal(true); }}
                    className="md:hidden w-10 h-10 flex items-center justify-center bg-indigo-600 rounded-full text-white shadow-lg"
                >
                    <Plus size={20} />
                </button>
            </div>

            {/* Scrollable Content */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-8 space-y-6">
                {weekDays.map(day => {
                    const dateStr = day.toISOString().split('T')[0];
                    const isCurrentDay = isToday(day);

                    // Filter events for this day
                    const dayEvents = combinedEvents.filter(e => {
                        if (!e.isTask && !e.isShift && e.endDate) return dateStr >= e.date && dateStr <= e.endDate;
                        return e.date === dateStr;
                    }).sort((a,b) => a.startTime.localeCompare(b.startTime));

                    return (
                        <div key={dateStr} className={`flex flex-col md:flex-row gap-4 md:gap-8 group ${dayEvents.length === 0 ? 'opacity-50 hover:opacity-80 transition-opacity' : ''}`}>
                            {/* Date Column */}
                            <div className="md:w-32 flex-shrink-0 pt-2 flex md:flex-col items-center md:items-start gap-2 md:gap-0">
                                <span className={`text-xs font-bold uppercase tracking-wider ${isCurrentDay ? 'text-indigo-400' : 'text-zinc-500'}`}>
                                    {formatDate(day, {weekday: 'long'})}
                                </span>
                                <div className={`text-2xl font-light ${isCurrentDay ? 'text-white' : 'text-zinc-400'}`}>
                                    {day.getDate()}
                                </div>
                                {isCurrentDay && <div className="text-[10px] bg-indigo-500/20 text-indigo-300 px-2 py-0.5 rounded mt-1 hidden md:block">{t('cal.today')}</div>}
                            </div>

                            {/* Events List */}
                            <div className="flex-1 space-y-3 pb-6 border-b border-zinc-800/50 group-last:border-none">
                                {dayEvents.length === 0 ? (
                                    <div className="py-2 text-sm text-zinc-600 italic">{t('cal.noEvents')}</div>
                                ) : (
                                    dayEvents.map(evt => (
                                        <div 
                                            key={evt.id}
                                            onClick={() => setSelectedEvent(evt)}
                                            className="bg-zinc-900/40 hover:bg-zinc-900 border border-zinc-800/60 hover:border-zinc-700 rounded-xl p-4 cursor-pointer transition-all hover:translate-x-1 group/card relative overflow-hidden"
                                        >
                                            {/* Left Colored Strip */}
                                            <div className={`absolute top-0 bottom-0 left-0 w-1 ${
                                                evt.isTask ? 'bg-blue-500' : 
                                                evt.isShift ? 'bg-zinc-500' :
                                                evt.type === 'Şube Transferi' ? 'bg-orange-500' : 
                                                evt.type === 'Toplantı' ? 'bg-indigo-500' : 'bg-zinc-500'
                                            }`}></div>

                                            <div className="flex justify-between items-start pl-3">
                                                <div className="flex-1">
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <span className="text-xs font-mono text-zinc-500 flex items-center gap-1">
                                                            <Clock size={12}/> {evt.startTime} - {evt.endTime}
                                                        </span>
                                                        {evt.type === 'Şube Transferi' && <span className="text-[10px] bg-orange-500/20 text-orange-400 px-1.5 rounded font-bold">TRANSFER</span>}
                                                        {evt.isShift && <span className="text-[10px] bg-zinc-800 text-zinc-400 px-1.5 rounded font-bold">VARDİYA</span>}
                                                    </div>
                                                    <h4 className="text-base font-bold text-zinc-200 group-hover/card:text-white transition-colors">{getText(evt.title)}</h4>
                                                    {evt.description && <p className="text-xs text-zinc-500 mt-1 line-clamp-1">{getText(evt.description)}</p>}
                                                </div>

                                                {/* Avatars */}
                                                <div className="flex -space-x-2 pl-2">
                                                    {evt.attendees.slice(0, 3).map(id => {
                                                        const emp = employees.find(e => e.id === id);
                                                        return emp ? <img key={id} src={emp.avatarUrl} className="w-8 h-8 rounded-full border-2 border-zinc-900 bg-zinc-800" title={emp.name}/> : null;
                                                    })}
                                                    {evt.attendees.length > 3 && <div className="w-8 h-8 rounded-full bg-zinc-800 border-2 border-zinc-900 flex items-center justify-center text-[10px] text-zinc-400">+{evt.attendees.length-3}</div>}
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    );
                })}

                <div className="h-20"></div> {/* Bottom Spacer */}
            </div>
        </div>

        {/* --- DETAIL PANEL (SLIDE OVER) --- */}
        {selectedEvent && (
            <div className="fixed inset-0 z-[200] flex justify-end bg-black/50 backdrop-blur-sm animate-in fade-in" onClick={() => setSelectedEvent(null)}>
                <div className="w-full md:w-[400px] h-full bg-zinc-950 border-l border-zinc-800 p-6 flex flex-col shadow-2xl animate-in slide-in-from-right duration-300" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-start mb-8">
                        <div>
                            <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest">{selectedEvent.isTask ? t('cal.taskDetail') : selectedEvent.isShift ? t('cal.shiftDetail') : t('cal.eventDetail')}</span>
                            <h2 className="text-2xl font-bold text-white mt-2 leading-tight">{getText(selectedEvent.title)}</h2>
                        </div>
                        <button onClick={() => setSelectedEvent(null)} className="p-2 bg-zinc-900 rounded-lg text-zinc-400 hover:text-white"><X size={20}/></button>
                    </div>

                    <div className="space-y-6 flex-1 overflow-y-auto">
                        <div className="flex items-center gap-4 text-zinc-300">
                            <div className="w-10 h-10 rounded-lg bg-zinc-900 flex items-center justify-center border border-zinc-800"><CalendarIcon size={20}/></div>
                            <div>
                                <p className="text-xs text-zinc-500">Tarih</p>
                                <p className="font-medium">{formatDate(selectedEvent.date, {day:'numeric', month:'long', year: 'numeric'})}</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4 text-zinc-300">
                            <div className="w-10 h-10 rounded-lg bg-zinc-900 flex items-center justify-center border border-zinc-800"><Clock size={20}/></div>
                            <div>
                                <p className="text-xs text-zinc-500">Saat</p>
                                <p className="font-medium">{selectedEvent.startTime} - {selectedEvent.endTime}</p>
                            </div>
                        </div>

                        <div className="p-4 bg-zinc-900/50 rounded-xl border border-zinc-800">
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-2">Açıklama</h4>
                            <p className="text-sm text-zinc-300 leading-relaxed">{getText(selectedEvent.description) || 'Açıklama yok.'}</p>
                        </div>

                        <div>
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-3">Katılımcılar ({selectedEvent.attendees.length})</h4>
                            <div className="space-y-2">
                                {selectedEvent.attendees.map(id => {
                                    const emp = employees.find(e => e.id === id);
                                    return emp ? (
                                        <div key={id} className="flex items-center gap-3 p-2 rounded-lg bg-zinc-900/30 border border-zinc-800/50">
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <div>
                                                <p className="text-sm font-bold text-zinc-200">{emp.name}</p>
                                                <p className="text-[10px] text-zinc-500">{emp.branch}</p>
                                            </div>
                                        </div>
                                    ) : null;
                                })}
                            </div>
                        </div>
                    </div>

                    {!selectedEvent.isTask && !selectedEvent.isShift && (
                        <div className="pt-6 border-t border-zinc-800">
                            <button onClick={handleDeleteEvent} className="w-full py-3 bg-red-900/20 text-red-400 border border-red-900/30 rounded-xl text-sm font-bold hover:bg-red-900/40 transition-colors flex items-center justify-center gap-2">
                                <Trash2 size={16}/> {t('cal.deleteEvent')}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        )}
    </div>
  );
};

export default Calendar;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { SalesLog, Employee, Role, Branch } from '../types';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, Legend } from 'recharts';
import { Trophy, TrendingUp, ShoppingBag, MapPin, Award, Medal, Calendar, Package, Activity, BarChart3, ListTodo, User, Lock, EyeOff, Filter, ChevronDown, Clock, Tag, Send, Loader2, CheckCircle2, XCircle, Trash2, X, Star, Zap, Crown, Percent } from 'lucide-react';

interface SalesDashboardProps {
    currentUser: Employee;
}

const AKTION_PRODUCTS = [
    "Ploom",
    "Vuse",
    "İqos iluma prime",
    "İqos iluma",
    "İqos one",
    "Veev"
];

const YEARS = [2024, 2025, 2026];
const MONTHS = [
    { v: 1, l: 'Ocak' }, { v: 2, l: 'Şubat' }, { v: 3, l: 'Mart' },
    { v: 4, l: 'Nisan' }, { v: 5, l: 'Mayıs' }, { v: 6, l: 'Haziran' },
    { v: 7, l: 'Temmuz' }, { v: 8, l: 'Ağustos' }, { v: 9, l: 'Eylül' },
    { v: 10, l: 'Ekim' }, { v: 11, l: 'Kasım' }, { v: 12, l: 'Aralık' }
];

const SalesDashboard: React.FC<SalesDashboardProps> = ({ currentUser }) => {
    const { t, formatDate } = useLanguage();
    const [salesData, setSalesData] = useState<SalesLog[]>([]);
    const [employees, setEmployees] = useState<Employee[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    // PERFORMANCE CARD STATE
    const [selectedStaffId, setSelectedStaffId] = useState<string | null>(null);

    const isAdmin = currentUser.role === Role.ADMIN;
    const isMounted = useRef(true);

    // Filter States
    const [selectedBranch, setSelectedBranch] = useState<string>(isAdmin ? 'ALL' : currentUser.branch);
    const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth() + 1);

    // New Sales Form State
    const [salesForm, setSalesForm] = useState({
        product: AKTION_PRODUCTS[0],
        quantity: 1,
        date: new Date().toISOString().split('T')[0]
    });

    useEffect(() => {
        isMounted.current = true;
        fetchData();
        return () => { isMounted.current = false; };
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const { data: sales } = await supabase.from('sales_logs').select('*').order('sale_date', { ascending: false });
            if (sales && isMounted.current) {
                const formattedSales = sales.map((l: any) => ({
                    id: l.id,
                    employeeId: l.employee_id,
                    branch: l.branch,
                    productName: l.product_name,
                    quantity: l.quantity,
                    saleDate: l.sale_date,
                    status: l.status,
                    createdAt: l.created_at
                }));
                setSalesData(formattedSales);
            }

            const { data: profiles } = await supabase.from('profiles').select('*');
            if (profiles && isMounted.current) {
                const formattedEmps = profiles.map((p: any) => ({
                    id: p.id,
                    name: p.full_name,
                    avatarUrl: p.avatar_url || `https://ui-avatars.com/api/?name=${p.full_name}`,
                    branch: p.branch,
                    role: p.role // Rol bilgisi eklendi
                }));
                setEmployees(formattedEmps as Employee[]);
            }
        } catch (err) {
            console.error(err);
        } finally {
            if(isMounted.current) setIsLoading(false);
        }
    };

    // SALES MANAGEMENT FUNCTIONS (Ported from ShiftSchedule)
    const handleSaveSale = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const payload = { 
                employee_id: currentUser.id, 
                branch: currentUser.branch, 
                product_name: salesForm.product, 
                quantity: salesForm.quantity, 
                sale_date: salesForm.date, 
                status: 'Bekliyor' 
            };
            const { data, error } = await supabase.from('sales_logs').insert([payload]).select();
            if (error) throw error;

            if (data && isMounted.current) {
                const newLog = {
                    id: data[0].id,
                    employeeId: data[0].employee_id,
                    branch: data[0].branch,
                    productName: data[0].product_name,
                    quantity: data[0].quantity,
                    saleDate: data[0].sale_date,
                    status: 'Bekliyor',
                    createdAt: data[0].created_at
                };
                setSalesData(prev => [newLog, ...prev]);
                alert(t('sales.alertSuccess'));
            }
        } catch (err: any) { 
            alert(err.message); 
        } finally { 
            if(isMounted.current) setIsSaving(false); 
        }
    };

    const handleUpdateStatus = async (id: string, newStatus: 'Onaylandı' | 'Reddedildi') => {
        if(!isAdmin) return;
        try {
            await supabase.from('sales_logs').update({ status: newStatus }).eq('id', id);
            setSalesData(prev => prev.map(l => l.id === id ? { ...l, status: newStatus } : l));
        } catch (err) { console.error(err); }
    };

    const handleDeleteSale = async (id: string) => {
        if(!confirm(t('sales.deleteConfirm'))) return;
        try {
            await supabase.from('sales_logs').delete().eq('id', id);
            setSalesData(prev => prev.filter(l => l.id !== id));
        } catch (err) { console.error(err); }
    };

    // Filtered Data Logic
    const filteredResults = useMemo(() => {
        return salesData.filter(s => {
            const date = new Date(s.saleDate);
            const matchesYear = date.getFullYear() === selectedYear;
            const matchesMonth = (date.getMonth() + 1) === selectedMonth;

            // KRİTİK: Admin seçtiği şubeyi görür, Personel SADECE kendi şubesini görür.
            const branchToMatch = isAdmin ? selectedBranch : currentUser.branch;
            const matchesBranch = branchToMatch === 'ALL' || s.branch === branchToMatch;

            return matchesYear && matchesMonth && matchesBranch;
        });
    }, [salesData, selectedYear, selectedMonth, selectedBranch, isAdmin, currentUser.branch]);

    // Leaderboard Data (With Masking Logic & GLOBAL SCOPE)
    const leaderboardData = useMemo(() => {
        const currentMonthData = salesData.filter(s => {
            const d = new Date(s.saleDate);
            return d.getFullYear() === selectedYear && 
                   (d.getMonth() + 1) === selectedMonth && 
                   s.status === 'Onaylandı';
        });

        const personnelMap: Record<string, number> = {};
        currentMonthData.forEach(s => {
            const empId = s.employeeId || 'unknown';
            personnelMap[empId] = (personnelMap[empId] || 0) + s.quantity;
        });

        return Object.entries(personnelMap)
            .map(([id, count]) => {
                if (id === 'unknown') return null;
                const emp = employees.find(e => e.id === id);
                const isMe = id === currentUser.id;

                const displayName = (isAdmin || isMe) ? (emp?.name || 'Bilinmeyen') : '???????';
                const displayAvatar = (isAdmin || isMe) 
                    ? (emp?.avatarUrl || `https://ui-avatars.com/api/?name=${emp?.name || '?'}`)
                    : `https://ui-avatars.com/api/?name=?&background=27272a&color=52525b&length=1`; 
                const displayBranch = (isAdmin || isMe) ? (emp?.branch || '-') : '***';

                return { id, name: displayName, avatar: displayAvatar, count, branch: displayBranch, isMe, role: emp?.role };
            })
            .filter(Boolean)
            .sort((a, b) => (b?.count || 0) - (a?.count || 0));
    }, [salesData, selectedYear, selectedMonth, employees, isAdmin, currentUser.id]);

    // Statistics based on filtered data
    const stats = useMemo(() => {
        const approvedCount = filteredResults.filter(s => s.status === 'Onaylandı').reduce((a, b) => a + b.quantity, 0);
        const pendingCount = filteredResults.filter(s => s.status === 'Bekliyor').reduce((a, b) => a + b.quantity, 0);

        const branchMap: Record<string, { approved: number, pending: number }> = {};
        filteredResults.forEach(s => {
            const b = s.branch || 'Bilinmiyor';
            if (!branchMap[b]) branchMap[b] = { approved: 0, pending: 0 };
            if (s.status === 'Onaylandı') branchMap[b].approved += s.quantity;
            else branchMap[b].pending += s.quantity;
        });

        const chartData = Object.entries(branchMap).map(([name, val]) => ({
            name,
            approved: val.approved,
            pending: val.pending
        })).sort((a,b) => (b.approved + b.pending) - (a.approved + a.pending));

        const productMap: Record<string, number> = {};
        filteredResults.forEach(s => {
            productMap[s.productName] = (productMap[s.productName] || 0) + s.quantity;
        });
        const topProduct = Object.keys(productMap).sort((a, b) => productMap[b] - productMap[a])[0];

        return { approvedCount, pendingCount, chartData, topProduct, topProductVal: productMap[topProduct] || 0 };
    }, [filteredResults]);

    // --- HELPER: STAFF CARD CALCULATIONS ---
    const getStaffPerformance = (staffId: string) => {
        const staffSales = salesData.filter(s => s.employeeId === staffId);
        const totalSales = staffSales.reduce((a, b) => a + b.quantity, 0);
        const approved = staffSales.filter(s => s.status === 'Onaylandı').length;
        const rejected = staffSales.filter(s => s.status === 'Reddedildi').length;

        const productBreakdown: Record<string, number> = {};
        staffSales.forEach(s => {
            productBreakdown[s.productName] = (productBreakdown[s.productName] || 0) + s.quantity;
        });
        const favoriteProduct = Object.keys(productBreakdown).sort((a, b) => productBreakdown[b] - productBreakdown[a])[0] || '-';

        // Rank Calculation (Global)
        const rank = leaderboardData.findIndex(i => i?.id === staffId) + 1;

        // Sadece son 30 işlemi göster (Scroll testi için yeterli)
        return { totalSales, approved, rejected, favoriteProduct, rank, history: staffSales.slice(0, 30) }; 
    };

    // --- RENDER: PERFORMANCE CARD MODAL (UPDATED DESIGN) ---
    const renderPerformanceCard = () => {
        if (!selectedStaffId || !isAdmin) return null;

        const staff = employees.find(e => e.id === selectedStaffId);
        if (!staff) return null;

        const perf = getStaffPerformance(selectedStaffId);

        // Rank styling
        let rankColor = 'text-zinc-400';
        let rankBg = 'bg-zinc-800';
        if (perf.rank === 1) { rankColor = 'text-yellow-400'; rankBg = 'bg-yellow-500/10 border-yellow-500/30'; }
        if (perf.rank === 2) { rankColor = 'text-gray-300'; rankBg = 'bg-gray-500/10 border-gray-500/30'; }
        if (perf.rank === 3) { rankColor = 'text-amber-600'; rankBg = 'bg-amber-700/10 border-amber-700/30'; }

        return (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-200" onClick={() => setSelectedStaffId(null)}>
                <div 
                    className="w-full max-w-2xl h-[85vh] bg-zinc-950 border border-zinc-800 rounded-3xl shadow-2xl flex flex-col overflow-hidden relative ring-1 ring-white/10"
                    onClick={e => e.stopPropagation()}
                >
                    {/* --- FIXED HEADER SECTION --- */}
                    <div className="shrink-0 p-6 border-b border-zinc-800 bg-zinc-900/50 backdrop-blur relative overflow-hidden">
                        {/* Decorative Background */}
                        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-900/10 rounded-full blur-3xl pointer-events-none -mr-16 -mt-16"></div>

                        <div className="flex justify-between items-start relative z-10">
                            <div className="flex gap-5 items-center">
                                <div className="relative">
                                    <div className="w-20 h-20 rounded-full p-1 bg-gradient-to-br from-zinc-700 to-zinc-800 shadow-xl">
                                        <img src={staff.avatarUrl} className="w-full h-full rounded-full object-cover border-2 border-zinc-950" />
                                    </div>
                                    <div className={`absolute -bottom-2 -right-2 w-8 h-8 flex items-center justify-center rounded-full border-4 border-zinc-950 text-xs font-bold ${rankBg} ${rankColor}`}>
                                        #{perf.rank}
                                    </div>
                                </div>
                                <div>
                                    <h2 className="text-2xl font-bold text-white tracking-tight">{staff.name}</h2>
                                    <div className="flex items-center gap-3 mt-1 text-sm text-zinc-400">
                                        <span className="flex items-center gap-1"><User size={14}/> {staff.role}</span>
                                        <span className="flex items-center gap-1 px-2 py-0.5 rounded bg-zinc-800 border border-zinc-700 text-zinc-300"><MapPin size={12}/> {staff.branch}</span>
                                    </div>
                                </div>
                            </div>
                            <button onClick={() => setSelectedStaffId(null)} className="p-2 bg-zinc-800 hover:bg-zinc-700 text-zinc-400 hover:text-white rounded-full transition-colors">
                                <X size={20} />
                            </button>
                        </div>
                    </div>

                    {/* --- SCROLLABLE CONTENT BODY --- */}
                    <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-8 bg-zinc-950">

                        {/* 1. Main Stats Grid */}
                        <div className="grid grid-cols-3 gap-4">
                            <div className="p-4 rounded-2xl bg-zinc-900 border border-zinc-800 flex flex-col gap-1 hover:border-indigo-500/30 transition-colors group">
                                <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-wider">{t('sales.totalSales')}</span>
                                <span className="text-2xl font-black text-white group-hover:text-indigo-400 transition-colors">{perf.totalSales}</span>
                            </div>
                            <div className="p-4 rounded-2xl bg-green-950/20 border border-green-900/30 flex flex-col gap-1">
                                <span className="text-[10px] text-green-500/70 font-bold uppercase tracking-wider">{t('sales.approved')}</span>
                                <span className="text-2xl font-black text-green-500">{perf.approved}</span>
                            </div>
                            <div className="p-4 rounded-2xl bg-orange-950/20 border border-orange-900/30 flex flex-col gap-1">
                                <span className="text-[10px] text-orange-500/70 font-bold uppercase tracking-wider">{t('sales.pendingCount')}</span>
                                <span className="text-2xl font-black text-orange-500">{perf.totalSales - perf.approved - perf.rejected}</span>
                            </div>
                        </div>

                        {/* 2. Success Rate & Favorite */}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                            <div className="p-5 rounded-2xl bg-zinc-900/50 border border-zinc-800">
                                <div className="flex justify-between items-end mb-3">
                                    <span className="text-xs font-bold text-zinc-400 uppercase">{t('sales.successRate')}</span>
                                    <span className="text-xl font-bold text-white">{perf.totalSales > 0 ? Math.round((perf.approved / perf.totalSales) * 100) : 0}%</span>
                                </div>
                                <div className="w-full h-2 bg-zinc-800 rounded-full overflow-hidden">
                                    <div 
                                        className="h-full bg-gradient-to-r from-blue-500 to-indigo-500" 
                                        style={{width: `${perf.totalSales > 0 ? Math.round((perf.approved / perf.totalSales) * 100) : 0}%`}}
                                    ></div>
                                </div>
                            </div>
                            <div className="p-5 rounded-2xl bg-zinc-900/50 border border-zinc-800 flex items-center gap-4">
                                <div className="w-10 h-10 rounded-xl bg-purple-500/10 flex items-center justify-center text-purple-400">
                                    <Zap size={20} />
                                </div>
                                <div>
                                    <span className="text-xs font-bold text-zinc-500 uppercase block mb-0.5">{t('sales.favProduct')}</span>
                                    <span className="text-sm font-bold text-white truncate max-w-[150px] block">{perf.favoriteProduct}</span>
                                </div>
                            </div>
                        </div>

                        {/* 3. Detailed History List */}
                        <div>
                            <h4 className="text-sm font-bold text-white mb-4 flex items-center gap-2">
                                <Clock size={16} className="text-zinc-500"/> 
                                {t('sales.history')} ({perf.history.length})
                            </h4>
                            <div className="space-y-3">
                                {perf.history.length === 0 ? (
                                    <div className="text-center py-10 text-zinc-600 italic bg-zinc-900/30 rounded-2xl border border-dashed border-zinc-800">
                                        {t('sales.noHistory')}
                                    </div>
                                ) : (
                                    perf.history.map((log: any) => (
                                        <div key={log.id} className="flex items-center justify-between p-4 rounded-2xl bg-zinc-900 border border-zinc-800 hover:border-zinc-700 transition-all group">
                                            <div className="flex items-center gap-4">
                                                <div className="w-10 h-10 rounded-xl bg-zinc-800 flex items-center justify-center text-zinc-400 border border-zinc-700 group-hover:text-white transition-colors">
                                                    <ShoppingBag size={18} />
                                                </div>
                                                <div>
                                                    <p className="text-sm font-bold text-white mb-0.5">{log.productName}</p>
                                                    <p className="text-[10px] text-zinc-500 font-medium">{formatDate(log.saleDate)}</p>
                                                </div>
                                            </div>
                                            <div className="text-right">
                                                <div className="text-sm font-bold text-white mb-0.5">{log.quantity} {t('sales.quantity')}</div>
                                                <span className={`inline-block px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider ${
                                                    log.status === 'Onaylandı' ? 'bg-green-500/10 text-green-500' : 
                                                    log.status === 'Reddedildi' ? 'bg-red-500/10 text-red-500' : 'bg-orange-500/10 text-orange-500'
                                                }`}>
                                                    {log.status === 'Onaylandı' ? t('sales.statusApproved') : 
                                                     log.status === 'Reddedildi' ? t('sales.statusRejected') : t('sales.statusPending')}
                                                </span>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>

                        {/* Footer Spacer */}
                        <div className="h-4"></div>
                    </div>
                </div>
            </div>
        );
    };

    return (
        <div className="h-full w-full p-4 md:p-8 overflow-y-auto custom-scrollbar bg-[#09090b]">

            {/* RENDER MODAL */}
            {renderPerformanceCard()}

            {/* Header & Global Filters */}
            <div className="mb-8 flex flex-col xl:flex-row justify-between items-start xl:items-end gap-6">
                <div>
                    <h1 className="text-3xl font-bold text-white tracking-tight mb-2 flex items-center gap-3">
                        <ShoppingBag className="text-orange-500" size={32} />
                        {t('sales.title')}
                    </h1>
                    <p className="text-zinc-500 text-sm flex items-center gap-2">
                        <Activity size={14} className="text-green-500" />
                        {formatDate(new Date(selectedYear, selectedMonth - 1, 1), { month: 'long', year: 'numeric' })}
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-3 bg-zinc-900/50 p-2 rounded-2xl border border-zinc-800">
                    <div className="flex items-center gap-2 px-3 border-r border-zinc-800">
                        <Filter size={14} className="text-zinc-500" />
                        <select 
                            value={selectedYear} 
                            onChange={e => setSelectedYear(Number(e.target.value))}
                            className="bg-transparent text-sm font-bold text-zinc-300 outline-none cursor-pointer hover:text-white"
                        >
                            {YEARS.map(y => <option key={y} value={y} className="bg-zinc-900">{y}</option>)}
                        </select>
                        <select 
                            value={selectedMonth} 
                            onChange={e => setSelectedMonth(Number(e.target.value))}
                            className="bg-transparent text-sm font-bold text-zinc-300 outline-none cursor-pointer hover:text-white"
                        >
                            {MONTHS.map(m => <option key={m.v} value={m.v} className="bg-zinc-900">{m.l}</option>)}
                        </select>
                    </div>

                    <div className="flex gap-1 overflow-x-auto">
                        {isAdmin ? (
                            <>
                                <button 
                                    onClick={() => setSelectedBranch('ALL')}
                                    className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${selectedBranch === 'ALL' ? 'bg-white text-black' : 'text-zinc-500 hover:text-zinc-300'}`}
                                >
                                    All
                                </button>
                                {Object.values(Branch).map(b => (
                                    <button 
                                        key={b}
                                        onClick={() => setSelectedBranch(b)}
                                        className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${selectedBranch === b ? 'bg-orange-600 text-white' : 'text-zinc-500 hover:text-zinc-300'}`}
                                    >
                                        {b}
                                    </button>
                                ))}
                            </>
                        ) : (
                            <div className="px-4 py-1.5 bg-orange-600/20 text-orange-400 rounded-lg text-xs font-bold border border-orange-500/30 flex items-center gap-2">
                                <MapPin size={12} />
                                {currentUser.branch}
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* STAFF: SALES INPUT FORM (Ported from ShiftSchedule) */}
            {!isAdmin && (
                <div className="mb-8 bg-orange-600 border border-orange-500 rounded-2xl p-6 shadow-xl shadow-orange-950/20">
                    <div className="flex flex-col lg:flex-row items-center gap-6">
                        <div className="flex-1 w-full space-y-2">
                            <h3 className="text-white font-black uppercase text-sm flex items-center gap-2">
                                <Tag size={16}/> {t('sales.newEntry')}
                            </h3>
                            <p className="text-orange-100 text-xs">{t('sales.entryDesc')}</p>
                        </div>
                        <form onSubmit={handleSaveSale} className="w-full lg:w-auto flex flex-wrap lg:flex-nowrap items-end gap-3">
                            <div className="flex-1 lg:w-40 min-w-[140px]">
                                <input type="date" value={salesForm.date} onChange={e => setSalesForm({...salesForm, date: e.target.value})} className="w-full bg-orange-700/50 border border-orange-400/30 rounded-xl px-4 py-3 text-sm text-white outline-none focus:bg-orange-700" />
                            </div>
                            <div className="flex-[2] lg:w-64 min-w-[180px]">
                                <select value={salesForm.product} onChange={e => setSalesForm({...salesForm, product: e.target.value})} className="w-full bg-orange-700/50 border border-orange-400/30 rounded-xl px-4 py-3 text-sm text-white outline-none focus:bg-orange-700">
